window.HB_TR["matthew"]["ur"]=["1۔ یسوع مسیح کی نسل کی کتاب، جو داؤد کا بیٹا، ابراہیم کا بیٹا تھا۔ \n2۔ ابراہیم نے اسحاق کو جنم دیا؛ اور اسحاق نے یعقوب کو جنم دیا؛ اور یعقوب نے یہودا اور اس کے بھائیوں کو جنم دیا؛ \n3۔ اور یہوداہ نے فارس اور زارا کو تھامار سے جنم دیا؛ اور فارس نے ایسروم کو جنم دیا؛ اور ایسروم نے آرام کو جنم دیا؛ \n4۔ اور آرام نے امیناداب کو جنم دیا؛ اور امیناداب نے ناصون کو جنم دیا؛ اور ناصون نے سالمون کو جنم دیا؛ \n5۔ اور سالمن نے راخاب کے بوز کو جنم دیا؛ اور بوز نے روتھ کے اوبید کو جنم دیا؛ اور اوبید نے یسوع کو جنم دیا؛ \n6۔ اور یسوع نے بادشاہ داؤد کو جنم دیا؛ اور داؤد بادشاہ نے سلیمان کو اس سے پیدا کیا {جو یوریاس کی بیوی تھی}؛ \n7۔ اور سلیمان نے روبعام کو جنم دیا؛ اور روبعام نے ابیا کو جنم دیا؛ اور ابیا نے آسا کو جنم دیا؛ \n8۔ اور آسا نے یوسفات کو جنم دیا؛ اور یوسفات نے یورام کو جنم دیا؛ اور یورام نے اوزیاس کو جنم دیا؛ \n9۔ اور اوزیاس نے یوآتھم کو جنم دیا؛ اور یوآتھم نے اخاز کو جنم دیا؛ اور اخاز نے حزقیہ کو جنم دیا؛ \n10۔ اور حزقی اس نے ماناسس کو جنم دیا؛ اور ماناسس نے آمون کو جنم دیا؛ اور آمون نے جوسیا کو جنم دیا؛ \n11۔ اور یوسیا نے یحونیا اور اس کے بھائیوں کو جنم دیا، جب وہ بابل لے جایا گیا: {یوشیاس...: کچھ نے پڑھا، یوسیا نے یعقوب کو جنم دیا، اور یعقوب نے یحونیا کو جنم دیا}\n12۔ اور جب وہ بابل لائے گئے، تو یحونیاس نے سلاثئیل کو جنم دیا؛ اور سلاتھیئل نے زوروبابل کو جنم دیا؛ \n13۔ اور زوروبابیل نے ابید کو جنم دیا؛ اور ابید نے ایلیاقیم کو جنم دیا؛ اور ایلیاقیم نے آزور کو جنم دیا؛ \n14۔ اور آزور نے سادوک کو جنم دیا؛ اور سادوک نے آخیم کو جنم دیا؛ اور اخیم نے ایلیوڈ کو جنم دیا؛ \n15۔ اور ایلیود نے الیعزر کو جنم دیا؛ اور الیعزر نے متان کو جنم دیا؛ اور متان نے یعقوب کو جنم دیا؛ \n16۔ اور یعقوب نے یوسف کو جنم دیا، جو مریم کا شوہر تھا، جس میں سے یسوع پیدا ہوا، جسے مسیح کہا جاتا ہے۔ \n17۔ تو ابراہیم سے لے کر داؤد تک تمام نسلیں چودہ نسلیں ہیں؛ اور داؤد سے لے کر بابل میں جانے تک چودہ نسلیں ہیں؛ اور بابل میں لے جانے سے لے کر مسیح تک چودہ نسلیں ہیں۔ \n18۔ اب یسوع مسیح کی پیدائش اس طرح تھی: جب اس کی والدہ مریم یوسف کے پاس تھیں، تو وہ ایک ہونے سے پہلے روح القدس کے بچے کے ساتھ پائی گئیں۔ \n19۔ پھر اس کے شوہر جوزف، جو ایک منصف آدمی تھے اور انہیں عوامی مثال بنانے کے لیے تیار نہیں تھے، نے انہیں نجی طور پر قید کرنے کا ارادہ کیا۔ \n20۔ لیکن جب وہ ان باتوں پر غور کر رہا تھا، تو خداوند کا فرشتہ خواب میں اس کے سامنے نمودار ہوا اور کہا، یوسف، اے داؤد کا بیٹا، اپنی بیوی مریم کو اپنے پاس لینے سے نہ ڈرو، کیونکہ جو کچھ اس میں پیدا ہوا ہے وہ روح القدس کا ہے۔ {حاملہ: گری. بیگاٹن}\n21۔ اور وہ ایک بیٹا پیدا کرے گی، اور تم اس کا نام یسوع رکھو گے: کیونکہ وہ اپنے لوگوں کو ان کے گناہوں سے بچائے گا۔ {یسوع: یعنی، نجات دہندہ، عبری}\n22۔ اب یہ سب کچھ کیا گیا تاکہ وہ پورا ہو سکے جو نبی نے خداوند کے بارے میں کہا تھا، اور کہا تھا، \n23. دیکھو، ایک کنواری حاملہ ہوگی، اور ایک بیٹا پیدا کرے گی، اور وہ اس کا نام عمانوئیل کہیں گے، جس کی ترجمانی ہے، خدا ہمارے ساتھ۔ {وہ...: یا، اس کا نام پکارا جائے گا}\n24۔ پھر یوسف جو نیند سے جاگ گیا، اس نے خداوند کے فرشتے کے حکم پر عمل کیا اور اپنی بیوی کو اپنے پاس لے لیا: \n25۔ اور میں نے اسے اس وقت تک نہیں جانا جب تک اس نے اپنا پہلا بیٹا پیدا نہ کیا: اور اس نے اپنا نام یسوع رکھا۔","1۔ اب جب یسوع بیت لحم یہودیہ میں ہیرودیس بادشاہ کے زمانے میں پیدا ہوا، دیکھو مشرق سے یروشلم میں حکیم آئے، \n2۔ پوچھتے ہوئے، وہ کہاں ہے جو یہودیوں کا بادشاہ پیدا ہوا ہے؟ کیونکہ ہم نے اس کا ستارہ مشرق میں دیکھا ہے، اور ہم اس کی عبادت کے لیے آئے ہیں۔ \n3۔ جب ہیرودیس بادشاہ نے یہ سب باتیں سنی، تو وہ پریشان ہو گیا، اور پورا یروشلم اس کے ساتھ تھا۔ \n4۔ اور جب اس نے لوگوں کے تمام سردار کاہنوں اور کاتبوں کو اکٹھا کیا، تو اس نے ان سے مطالبہ کیا کہ مسیح کہاں پیدا ہوگا۔ \n5۔ اور انہوں نے اسے کہا، بیت لحم یہودیہ میں: کیونکہ یہ نبی نے لکھا ہے، \n6۔ اور تم بیت لحم، جو یہودا کی سرزمین میں ہے، یہودا کے شہزادوں میں سب سے کم نہیں ہو: کیونکہ تم سے ایک گورنر آئے گا، جو میرے لوگوں کے اسرائیل پر حکومت کرے گا۔ {حکمرانی: یا، کھلاؤ}\n7۔ پھر ہیرودیس نے جب اس نے دانا لوگوں کو خصوصی طور پر بلایا تو ان سے پوچھا کہ ستارہ کب ظاہر ہوتا ہے۔ \n8۔ اور اس نے انہیں بیت لحم بھیجا اور کہا، جاؤ اور اس چھوٹے بچے کی تلاش میں محنت کرو؛ اور جب تم اسے پا لو، تو مجھے دوبارہ خبر دینا، تاکہ میں بھی آ کر اس کی عبادت کروں۔ \n9۔ جب انہوں نے بادشاہ کی آواز سنی تو وہ روانہ ہو گئے؛ اور دیکھو، وہ ستارہ، جو انہوں نے مشرق میں دیکھا، ان کے سامنے آ گیا، یہاں تک کہ وہ آ کر اس جگہ کھڑا ہو گیا جہاں بچہ تھا۔ \n10۔ جب انہوں نے ستارہ دیکھا، تو بے حد خوشی منائی۔ \n11۔ اور جب وہ گھر میں آئے، تو انہوں نے بچے کو مریم اپنی ماں کے ساتھ دیکھا، وہ گر پڑے اور اس کی عبادت کی: اور جب انہوں نے اپنے خزانے کھولے تو اسے تحفے دیے؛ سونا، لوبان اور مر۔ {پیش کیا گیا: یا، پیش کیا گیا}\n12۔ اور جب انہیں خواب میں خدا کی طرف سے خبردار کیا گیا کہ وہ ہیرودیس کے پاس واپس نہ جائیں، تو وہ اپنے ملک میں کسی اور راستے پر روانہ ہو گئے۔ \n13۔ اور جب وہ روانہ ہوئے، دیکھو، خداوند کا فرشتہ یوسف کے خواب میں ظاہر ہوتا ہے اور کہتا ہے: اٹھو، اور بچے اور اس کی ماں کو لے کر مصر میں بھاگ جاؤ، اور وہاں رہو جب تک میں تمہیں خبر نہ پہنچاؤں: کیونکہ ہیرودیس بچے کو تلاش کرے گا تاکہ اسے تباہ کر دے۔ \n14۔ جب وہ اٹھا، تو اس نے چھوٹے بچے اور اس کی ماں کو رات کو لے کر مصر کی طرف روانہ ہو گیا: \n15۔ اور وہ ہیرودیس کی موت تک وہاں رہا: تاکہ وہ عمل پورا ہو جو نبی نے خداوند کے بارے میں کہا تھا، اور کہا تھا، میں نے اپنے بیٹے کو مصر سے بلایا ہے۔ \n16۔ پھر وہ بات پوری ہوئی جو یرمیائی نبی نے کہی تھی، اور کہا تھا: \n17۔ رام میں ایک آواز سنائی دی، نوحہ، رونا، اور شدید سوگ، راحیل اپنے بچوں کے لیے رو رہی تھی، اور اسے تسلی نہیں ملی، کیونکہ وہ نہیں ہیں۔ \n18۔ لیکن جب ہیرودیس مر گیا، دیکھو، خداوند کا ایک فرشتہ خواب میں مصر میں یوسف کے سامنے ظاہر ہوتا ہے، \n19۔ اور کہا، اٹھو، اور بچے اور اس کی ماں کو لے کر اسرائیل کی سرزمین میں چلے جاؤ، کیونکہ وہ مر چکے ہیں جنہوں نے بچے کی جان تلاش کی۔ \n20۔ اور وہ اٹھا، بچے اور اس کی ماں کو لے کر اسرائیل کی سرزمین میں آیا۔ \n21۔ لیکن جب اس نے سنا کہ آرکیلاؤس یہودیہ میں اپنے والد ہیروڈ کے کمرے میں حکومت کرتا ہے، تو وہ وہاں جانے سے ڈر گیا: اگرچہ خواب میں خدا کی خبر دی گئی تھی، وہ گلیل کے حصوں میں چلا گیا: \n22۔ اور وہ آیا اور ناصرت ناصری نامی شہر میں رہا: تاکہ وہ جو نبیوں نے کہا تھا اسے پورا کر سکے، اسے ناصری کہا جائے گا۔","1۔ ان دنوں یوحنا بپتسمہ دینے والا آیا، جو یہودیہ کے بیابان میں تبلیغ کر رہا تھا، \n2۔ اور کہتے ہوئے، توبہ کرو، کیونکہ آسمان کی بادشاہی قریب ہے۔ \n3۔ کیونکہ یہی وہ ہے جس کے بارے میں نبی عیسیٰ نے کہا، جو صحرا میں پکار رہا ہے، خداوند کے راستے تیار کرو، اس کے راستے سیدھے کرو۔ \n4۔ اور اسی یوحنا نے اونٹ کے بالوں کا لباس پہنا ہوا تھا، اور اس کی کمر پر چمڑے کا بیلٹ تھا؛ اور اس کا گوشت ٹڈی دل اور جنگلی شہد سے بھرا ہوا تھا۔ \n5۔ پھر اس کے پاس یروشلم، پورے یہودیہ اور اردن کے آس پاس کے تمام علاقے نکلے، \n6۔ اور انہیں اردن میں بپتسمہ دیا گیا، اپنے گناہوں کا اعتراف کیا۔ \n7۔ لیکن جب اس نے بہت سے فریسی اور صدوقیوں کو اپنی بپتسمہ کے لیے آتے دیکھا، تو اس نے ان سے کہا، اے سانپوں کی نسل، کس نے تمہیں آنے والے غضب سے بھاگنے کی تنبیہ کی ہے؟ \n8. یوں پھل پیدا کرو جو توبہ کے لیے ملتے ہیں: {مل...: یا، زندگی کی اصلاح کے جوابدہ}\n9۔ اور اپنے اندر یہ نہ کہیں کہ ہمارے پاس ابراہیم ہے، کیونکہ میں تم سے کہتا ہوں، کہ خدا ان پتھروں سے بچے ابراہیم کے لیے پیدا کرنے کے قابل ہے۔ \n10۔ اور اب کلہاڑی بھی درختوں کی جڑ میں رکھی جاتی ہے: اس لیے ہر وہ درخت جو اچھا پھل نہیں دیتا، اسے کاٹ کر آگ میں پھینک دیا جاتا ہے۔ \n11. میں واقعی تمہیں توبہ کے لیے پانی سے بپتسمہ دیتا ہوں: لیکن جو میرے بعد آئے گا وہ مجھ سے زیادہ طاقتور ہے، جس کے جوتے میں اٹھانے کے قابل نہیں ہوں: وہ تمہیں روح القدس اور آگ سے بپتسمہ دے گا: \n12۔ جس کا پنکھا اس کے ہاتھ میں ہے، اور وہ اپنی زمین کو مکمل طور پر صاف کرے گا، اور گندم کو جمع کرے گا؛ لیکن وہ بھوسے کو بے قابو آگ سے جلا دے گا۔ \n13۔ پھر یسوع گلیل سے اردن اور یوحنا کے پاس آتا ہے، تاکہ اسے بپتسمہ دیا جائے۔ \n14۔ لیکن یوحنا نے اسے منع کیا اور کہا، مجھے تم سے بپتسمہ لینا ضروری ہے، اور کیا تم میرے پاس آتے ہو؟ \n15۔ اور یسوع نے جواب میں کہا، اب ایسا ہونے دو، کیونکہ یوں ہم تمام راستبازی کو پورا کرتے ہیں۔ پھر اس نے اسے برداشت کیا۔ \n16۔ اور جب یسوع نے بپتسمہ لیا تو وہ سیدھا پانی سے باہر آ گیا: اور دیکھتے آسمان اس کے لیے کھل گئے، اور اس نے خدا کی روح کو کبوتر کی طرح اترتے اور اس پر روشنی دی: \n17۔ اور آسمان سے ایک آواز آئی، جو کہتی ہے، یہ میرا محبوب بیٹا ہے، جس سے میں خوش ہوں۔","1۔ پھر یسوع کو روح کی طرف لے کر صحرا میں لے جایا گیا تاکہ شیطان کو آزمایا جا سکے۔ \n2۔ اور جب اس نے چالیس دن اور چالیس راتیں روزہ رکھا، تو اس کے بعد وہ بھوکا ہو گیا۔ \n3۔ اور جب آزمائش کرنے والا اس کے پاس آیا، اس نے کہا، اگر تم خدا کے بیٹے ہو، تو حکم دو کہ یہ پتھر روٹی بنائیں۔ \n4۔ لیکن اس نے جواب دیا اور کہا، لکھا ہے کہ انسان صرف روٹی سے نہیں بلکہ خدا کے منہ سے نکلنے والے ہر لفظ سے زندہ رہے گا۔ \n5۔ پھر شیطان اسے مقدس شہر میں لے جاتا ہے اور ہیکل کی چوٹی پر بٹھا دیتا ہے، \n6۔ اور اس سے کہتا ہے، اگر تم خدا کے بیٹے ہو، تو خود کو نیچے گرا دو، کیونکہ لکھا ہے کہ وہ اپنے فرشتوں کو تمہارے بارے میں حکم دے گا، اور وہ تمہیں اپنے ہاتھوں میں اٹھائیں گے، کہیں تم پتھر پر پاؤں نہ مارو۔ \n7۔ یسوع نے اس سے کہا، یہ دوبارہ لکھا ہے، تو اپنے خداوند کو آزمائش نہ کرو۔ {آزمائش: یا، آزماؤ، یا آزمائش کرو، یا ثبوت دو}\n8۔ پھر شیطان اسے ایک بلند پہاڑ پر لے جاتا ہے، اور اسے دنیا کی تمام بادشاہتیں اور ان کی شان دکھاتا ہے؛ \n9۔ اور اس سے کہتا ہے، یہ سب چیزیں میں تمہیں دوں گا، اگر تم گر کر میری عبادت کرو گے۔ \n10۔ پھر یسوع اس سے کہتا ہے، شیطان یہاں سے نکل جاؤ، کیونکہ یہ لکھا ہے، تو اپنے خداوند خدا کی عبادت کرو گے، اور صرف اسی کی عبادت کرو گے۔ \n11۔ پھر شیطان اسے چھوڑ دیتا ہے، اور دیکھو، فرشتے آئے اور اس کی خدمت کی۔ \n12۔ اب جب یسوع نے سنا کہ جان کو قید میں ڈال دیا گیا ہے، تو وہ گلیل چلا گیا؛ {پھینکا...: یا، حوالہ دیا گیا}\n13۔ اور ناصرت چھوڑ کر وہ کفرناحوم میں آباد ہوا، جو سمندر کے کنارے ہے، زابولون اور نفثالیم کی سرحدوں پر: \n14۔ تاکہ وہ پورا ہو جو عیسیٰ نبی نے کہا تھا، \n15۔ زابولون کی زمین، اور نیفتالیم کی سرزمین، {راست} سمندر کے راستے، اردن کے پار، غیر یہودیوں کی گلیل؛ \n16۔ جو لوگ اندھیرے میں بیٹھے تھے، انہوں نے بڑی روشنی دیکھی؛ اور جو لوگ اس علاقے میں بیٹھے اور موت کے سائے میں بیٹھے، ان کے لیے روشنی پھوٹ پڑی۔ \n17۔ اس وقت سے یسوع نے تبلیغ شروع کی، اور کہا، توبہ کرو: کیونکہ آسمان کی بادشاہی قریب ہے۔ \n18۔ اور یسوع، گلیل کے سمندر کے کنارے چلتے ہوئے، دو بھائیوں کو دیکھا، شمعون جسے پیٹر کہا جاتا تھا اور اس کا بھائی، جو سمندر میں جال ڈال رہے تھے: کیونکہ وہ مچھلی پکڑنے والے تھے۔ \n19۔ اور وہ ان سے کہتا ہے، میری پیروی کرو، اور میں تمہیں انسانوں کا شکار بنا دوں گا۔ \n20۔ اور وہ فورا اپنے جال چھوڑ کر اس کا پیچھا کر گئے۔ \n21۔ اور وہاں سے روانہ ہو کر، اس نے دو اور بھائیوں، جیمز (زبدی کا بیٹا) اور اس کا بھائی جان کو ایک جہاز میں اپنے والد زبدی کے ساتھ اپنے جال ٹھیک کرتے دیکھا؛ اور اس نے انہیں بلایا۔ \n22۔ اور وہ فورا جہاز اور اپنے والد کو چھوڑ کر اس کے پیچھے چل پڑے۔ \n23۔ اور یسوع نے پورے گلیل میں سفر کیا، ان کی عبادت گاہوں میں تعلیم دی، بادشاہی کی خوشخبری سنائی، اور لوگوں میں ہر قسم کی بیماریوں اور بیماریوں کا علاج کیا۔ \n24۔ اور اس کی شہرت پورے شام میں پھیل گئی: اور انہوں نے اس کے پاس تمام بیمار لوگ لے آئے جو مختلف بیماریوں اور اذیتوں میں مبتلا تھے، اور جو شیطانوں میں مبتلا تھے، جو پاگل تھے، اور جو فالج کے مریض تھے؛ اور اس نے انہیں شفا دی۔ \n25۔ اور وہاں اس کے پیچھے گلیل سے، دکاپولس، یروشلم سے، یہودیہ سے، اور اردن کے پار سے بہت سے لوگ آئے۔","1۔ اور جب اس نے ہجوم کو دیکھا تو وہ ایک پہاڑ پر چڑھا: اور جب اسے ٹھہرایا گیا تو اس کے شاگرد اس کے پاس آئے: \n2۔ اور اس نے منہ کھولا اور انہیں سکھایا، کہا، \n3۔ خوش نصیب ہیں جو روحانی طور پر غریب ہیں: کیونکہ آسمان کی بادشاہی ان کی ہے۔ \n4۔ جو سوگ منا رہے ہیں وہ مبارک ہیں: کیونکہ انہیں تسلی ملے گی۔ \n5۔ مبارک ہو وہ جو عاجز ہیں: کیونکہ وہ زمین کے وارث ہوں گے۔ \n6۔ مبارک ہیں وہ جو راستبازی کی بھوک اور پیاس رکھتے ہیں: کیونکہ وہ بھر جائیں گے۔ \n7۔ مہربان مبارک ہیں: کیونکہ انہیں رحمت ملے گی۔ \n8۔ پاک دل والے مبارک ہیں: کیونکہ وہ خدا کو دیکھیں گے۔ \n9۔ مبارک ہیں امن قائم کرنے والے: کیونکہ انہیں خدا کے بچے کہا جائے گا۔ \n10۔ مبارک ہیں وہ جو راستبازی کی خاطر ستایا جاتا ہے: کیونکہ آسمان کی بادشاہی ان کی ہے۔ \n11. مبارک ہو، جب {لوگ} تمہیں برا بھلا کہیں گے، تمہیں ستائیں گے، اور تمہارے خلاف ہر قسم کی برائی کہیں گے، میرے لیے۔ {جھوٹا: انگریز جھوٹا}\n12۔ خوش ہو جاؤ، اور بے حد خوش رہو: کیونکہ تمہارا اجر آسمان میں عظیم ہے: کیونکہ تم سے پہلے کے پیغمبروں کو بھی اسی طرح ستایا گیا۔ \n13۔ تم زمین کے نمک ہو: لیکن اگر نمک کا ذائقہ ختم ہو گیا ہے تو اسے کس چیز سے نمکین کیا جائے گا؟ اب سے یہ کسی کام کا نہیں، سوائے اس کے کہ اسے نکال دیا جائے اور انسانوں کے قدموں تلے روند دیا جائے۔ \n14۔ تم دنیا کی روشنی ہو۔ ایک شہر جو پہاڑی پر واقع ہو، چھپا نہیں سکتا۔ \n15۔ نہ ہی لوگ موم بتی جلاتے ہیں، اور اسے ایک بوشل کے نیچے رکھتے ہیں، بلکہ ایک موم بتی پر رکھتے ہیں؛ اور یہ گھر میں موجود سب کو روشنی دیتی ہے۔ {ایک بوشل: اصل لفظ کا مطلب ہے کہ ایک پینٹ ایک پیک سے کم ہوتا ہے}\n16۔ اپنی روشنی انسانوں کے سامنے اس طرح چمکے، تاکہ وہ تمہارے نیک اعمال دیکھ سکیں، اور تمہارے آسمانوں میں موجود باپ کی جلال بخشیں۔ \n17۔ یہ نہ سوچو کہ میں شریعت یا انبیاء کو تباہ کرنے آیا ہوں: میں تباہ کرنے نہیں آیا بلکہ پورا کرنے آیا ہوں۔ \n18۔ کیونکہ میں واقعی تم سے کہتا ہوں، جب تک آسمان اور زمین گزر نہیں جاتے، قانون سے ایک لمحہ یا ایک لفظ بھی نہیں گزرے گا، جب تک سب کچھ پورا نہ ہو جائے۔ \n19۔ جو کوئی ان چھوٹے احکامات میں سے کسی کو توڑے گا اور انسانوں کو ایسا سکھائے گا، اسے آسمان کی بادشاہی میں سب سے چھوٹا کہا جائے گا؛ لیکن جو بھی انہیں کرے گا اور سکھائے گا، اسے آسمان کی بادشاہی میں عظیم کہا جائے گا۔ \n20۔ کیونکہ میں تم سے کہتا ہوں، جب تک تمہاری راستبازی کاتبوں اور فریسیوں کی راستبازی سے بڑھ نہ جائے، تم کسی بھی صورت آسمان کی بادشاہی میں داخل نہیں ہو سکتے۔ \n21۔ تم نے سنا ہے کہ پرانے زمانے میں کہا گیا تھا کہ تم قتل نہیں کرو گے؛ اور جو قتل کرے گا وہ فیصلے کے خطرے میں ہوگا: {by: or, to}\n22۔ لیکن میں تم سے کہتا ہوں، جو بھی اپنے بھائی سے بغیر وجہ کے ناراض ہو گا وہ فیصلے کے خطرے میں ہوگا؛ اور جو بھی اپنے بھائی راکا سے کہے گا، وہ کونسل کے خطرے میں ہوگا؛ لیکن جو کہے گا، اے بے وقوف، وہ جہنم کی آگ کے خطرے میں ہوگا۔ {راکا: یعنی، فضول دوست}\n23۔ لہٰذا اگر تم اپنا تحفہ قربان گاہ پر لے آؤ، اور وہاں یاد رکھو کہ تمہارا بھائی تمہارے خلاف ہے؛ \n24۔ اپنا تحفہ قربان گاہ کے سامنے چھوڑ دو، اور اپنے راستے پر چلو؛ پہلے اپنے بھائی سے صلح کرو، پھر آ کر اپنا تحفہ پیش کرو۔ \n25۔ اپنے مخالف سے جلدی اتفاق کرو، جب تک تم اس کے راستے میں ہو؛ ورنہ کبھی دشمن تمہیں جج کے حوالے کر دے گا، اور جج تمہیں افسر کے حوالے کر دے گا، اور تمہیں قید میں ڈال دیا جائے گا۔ \n26۔ یقینا میں تم سے کہتا ہوں، تم وہاں سے کبھی باہر نہیں آؤ گے، جب تک کہ تم سب سے زیادہ رقم ادا نہ کر لو۔ \n27۔ تم نے سنا ہے کہ پرانے زمانے میں کہا گیا تھا، تو نہ کرو: \n28۔ لیکن میں تم سے کہتا ہوں، جو بھی عورت کو ہوس میں دیکھتا ہے وہ پہلے ہی اپنے دل میں اس کے ساتھ کر چکا ہے۔ \n29۔ اور اگر تمہاری دائیں آنکھ تمہیں ناراض کرے، تو اسے نکال کر اپنے اندر سے پھینک دو: کیونکہ تمہارے لیے فائدہ مند ہے کہ تمہارے کسی عضو میں سے کوئی مر جائے، اور تمہارا پورا جسم جہنم میں نہ پھینکا جائے۔ {ناراض...: یا، تمہیں ناراض کروا دوں}\n30۔ اور اگر تمہارا دایاں ہاتھ تمہیں ناراض کرے تو اسے کاٹ دو اور اپنے جسم سے پھینک دو: کیونکہ تمہارے لیے فائدہ مند ہے کہ تمہارے کسی عضو میں سے کوئی مر جائے، اور تمہارا پورا جسم جہنم میں نہ پھینک دیا جائے۔ \n31۔ کہا گیا ہے، جو اپنی بیوی کو رخصت کرے تو اسے طلاق کا تحریری خط دے دے: \n32۔ لیکن میں تم سے کہتا ہوں، جو اپنی بیوی کو کے لیے چھوڑ دے گا، وہ کرے گا، اور جو طلاق یافتہ عورت سے شادی کرے گا وہ کرے گا۔ \n33۔ پھر تم نے سنا ہے کہ پرانے زمانے میں کہا گیا ہے کہ تم خود کو قربان نہ کرو بلکہ خداوند کے سامنے اپنی قسمیں پوری کرو: \n34۔ لیکن میں تم سے کہتا ہوں، بالکل قسم نہ کھاؤ؛ نہ آسمان کی قسم؛ کیونکہ یہ خدا کا تخت ہے: \n35۔ نہ ہی زمین کے پاس؛ کیونکہ یہ اس کی پاؤں کی چوٹی ہے: نہ یروشلم کے پاس؛ کیونکہ یہ عظیم بادشاہ کا شہر ہے۔ \n36۔ نہ تو اپنے سر کی قسم کھاؤ گے، کیونکہ تم ایک بال بھی سفید یا کالا نہیں بنا سکتے۔ \n37۔ لیکن تمہاری بات چیت ہو، ہاں، ہاں؛ نہیں، نہیں: کیونکہ جو کچھ ان سے زیادہ ہے وہ برائی کا آتا ہے۔ \n38۔ آپ نے سنا ہے کہ کہا گیا ہے، آنکھ کے بدلے آنکھ اور دانت کے بدلے دانت: \n39۔ لیکن میں تم سے کہتا ہوں، کہ تم برائی کی مزاحمت نہ کرو، بلکہ جو تمہیں تمہارے دائیں گال پر مارے گا، وہ دوسرا گال بھی اس کی طرف مڑے۔ \n40۔ اور اگر کوئی آپ پر قانون کے خلاف مقدمہ کرے اور آپ کا کوٹ لے لے، تو اسے بھی آپ کی چادر لے لے۔ \n41۔ اور جو بھی تمہیں ایک میل جانے پر مجبور کرے، وہ دونوں کے ساتھ چلو۔ \n42۔ جو تم سے مانگتا ہے اسے دو، اور جو تم سے قرض لینا چاہتا ہے اس سے منہ نہ موڑو۔ \n43۔ تم نے سنا ہے کہ کہا گیا ہے، تم اپنے پڑوسی سے محبت کرو اور اپنے دشمن سے نفرت کرو۔ \n44۔ لیکن میں تم سے کہتا ہوں، اپنے دشمنوں سے محبت کرو، ان کو برکت دو جو تمہیں لعنت دیتے ہیں، ان کے لیے بھلائی کرو جو تم سے نفرت کرتے ہیں، اور ان کے لیے دعا کرو جو تمہیں نفرت سے استعمال کرتے ہیں اور تمہیں ستاتے ہیں؛ \n45۔ تاکہ تم اپنے آسمانوں میں موجود اپنے باپ کے بچے بن سکو: کیونکہ وہ اپنا سورج برائی اور نیکی پر طلوع کرتا ہے، اور راستوں اور بدکاروں پر بارش برساتا ہے۔ \n46۔ کیونکہ اگر تم ان سے محبت کرتے ہو جو تم سے محبت کرتے ہیں، تو تمہیں کیا انعام ملتا ہے؟ کیا پبلکرز کو بھی ایسا ہی نہیں ملتا؟ \n47۔ اور اگر آپ صرف اپنے بھائیوں کو سلام کرتے ہیں، تو آپ دوسروں سے زیادہ کیا کرتے ہیں؟ کیا پبلکرز بھی ایسا نہیں کرتے؟ \n48۔ لہٰذا تم کامل بنو، جیسے تمہارا باپ جو آسمان میں ہے کامل ہے۔","1۔ خبردار رہو کہ تم لوگوں کے سامنے اپنی خیرات نہ دو تاکہ ان کے سامنے نظر آ سکیں: ورنہ تمہیں اپنے باپ کی طرف سے کوئی انعام نہیں ملے گا جو آسمان میں ہے۔ {خیرات: یا، راستبازی کی} {تمہارے: یا، تمہارے ساتھ}\n2۔ اس لیے جب تم {اپنی} صدقہ کرو، تو اپنے سامنے بگل نہ بجاؤ، جیسا کہ منافق عبادت گاہوں اور گلیوں میں کرتے ہیں، تاکہ وہ لوگوں کی شان حاصل کر سکیں۔ یقینا میں تم سے کہتا ہوں، انہیں ان کا اجر ملتا ہے۔ {نہیں...: یا بگل نہ بجاؤ}\n3۔ لیکن جب تم خیرات کرو، تو اپنے بایاں ہاتھ کو نہ جانے کہ تمہارا دایاں ہاتھ کیا کرتا ہے: \n4۔ تاکہ تمہاری خیرات چھپ کر رہیں: اور تمہارا باپ جو خود چھپ کر دیکھتا ہے، تمہیں کھلے عام انعام دے گا۔ \n5۔ اور جب تم نماز پڑھو گے، تو منافقوں کی طرح نہ بنو گے: کیونکہ وہ عبادت خانوں اور سڑکوں کے کونوں میں کھڑے ہو کر دعا کرنا پسند کرتے ہیں تاکہ انسانوں کو دیکھا جا سکے۔ یقینا میں تم سے کہتا ہوں، انہیں ان کا اجر ملتا ہے۔ \n6. لیکن جب تم دعا کرو، تو اپنے الماری میں داخل ہو جاؤ، اور جب تم اپنا دروازہ بند کر دو، تو اپنے باپ سے جو خفیہ ہے دعا کرو؛ اور تمہارا باپ جو چھپ کر دیکھتا ہے، تمہیں کھلے عام انعام دے گا۔ \n7۔ لیکن جب تم دعا کرو، تو بے معنی تکرار نہ کرو، جیسا کہ کافر کرتے ہیں: کیونکہ وہ سمجھتے ہیں کہ ان کی باتوں کی بات سنی جائے گی۔ \n8۔ لہٰذا ان جیسے نہ بنو: کیونکہ تمہارا باپ جانتا ہے کہ تمہیں کن چیزوں کی ضرورت ہے، اس سے پہلے کہ تم اس سے مانگو۔ \n9۔ اسی طرح دعا کرو: اے ہمارے باپ جو آسمانوں میں ہے، تیرا نام پاک ہو۔ \n10۔ تیری بادشاہی آئے۔ تیری مرضی زمین پر ہو، جیسے آسمان میں ہے۔ \n11۔ آج ہمیں ہمارا روزانہ کا روٹی دو۔ \n12۔ اور ہمارے قرضوں کو معاف کر، جیسے ہم اپنے مقروضوں کو معاف کرتے ہیں۔ \n13۔ اور ہمیں آزمائش میں نہ ڈال، بلکہ برائی سے بچا: کیونکہ بادشاہی، طاقت اور جلال ہمیشہ کے لیے تیرے ہیں۔ آمین۔ \n14۔ کیونکہ اگر تم لوگوں کے گناہوں کو معاف کرو گے تو تمہارا آسمانی باپ بھی تمہیں معاف کرے گا: \n15. لیکن اگر تم لوگوں کے گناہوں کو معاف نہیں کرو گے، تو تمہارا باپ بھی تمہارے گناہوں کو معاف نہیں کرے گا۔ \n16۔ مزید یہ کہ جب روزہ رکھو تو منافقوں کی طرح اداس چہرہ نہ رکھو، کیونکہ وہ اپنے چہرے بگاڑ دیتے ہیں تاکہ لوگوں کو روزہ رکھنے والا دکھائی دیں۔ یقینا میں تم سے کہتا ہوں، ان کا اجر ملتا ہے۔ \n17. لیکن تو، جب روزہ رکھو، اپنا سر مسح کرو، اور اپنا چہرہ دھوؤ؛ \n18۔ کہ تم لوگوں کو روزہ رکھنے کے لیے ظاہر نہ کرو، بلکہ اپنے باپ کے سامنے جو خفیہ ہے، اور تمہارا باپ، جو چھپ کر دیکھتا ہے، تمہیں کھلے عام انعام دے گا۔ \n19۔ زمین پر اپنے لیے خزانے نہ رکھو، جہاں پتنگا اور زنگ آلود ہوتے ہیں، اور جہاں چور چوری کرتے ہیں: \n20۔ لیکن اپنے لیے آسمان میں خزانے رکھو، جہاں نہ پتنگا نہ زنگ آلود ہو، اور جہاں چور نہ توڑ پھوڑ کر نہ چوری کریں: \n21۔ جہاں تمہارا خزانہ ہے، وہاں تمہارا دل بھی ہوگا۔ \n22. جسم کی روشنی آنکھ ہے: اگر تمہاری آنکھ اکیلی ہے، تو تمہارا پورا جسم روشنی سے بھر جائے گا۔ \n23. لیکن اگر تیری آنکھ برا ہے، تو تمہارا پورا جسم تاریکی سے بھر جائے گا۔ تو اگر تمہارے اندر جو روشنی ہے وہ تاریکی ہے، تو وہ تاریکی کتنی عظیم ہے! \n24۔ کوئی انسان دو آقا کی خدمت نہیں کر سکتا: یا تو وہ ایک سے نفرت کرے گا اور دوسرے سے محبت کرے گا؛ یا پھر وہ ایک کو تھامے گا اور دوسرے سے نفرت کرے گا۔ تم خدا اور مامون کی خدمت نہیں کر سکتے۔ \n25۔ اس لیے میں تم سے کہتا ہوں، اپنی جان، جو کھاؤ گے، یا پیو گے، اس بارے میں مت سوچو؛ اور نہ ہی اپنے جسم کے لیے، جو تم پہنو گے۔ کیا زندگی گوشت سے زیادہ نہیں، اور جسم لباس سے بڑھ کر؟ \n26۔ ہوا کے پرندوں کو دیکھو: کیونکہ وہ نہ بوتے ہیں، نہ کاٹتے ہیں، نہ اصطبل میں جمع ہوتے ہیں؛ پھر بھی تمہارا آسمانی باپ انہیں کھلاتا ہے۔ کیا تم ان سے کہیں بہتر نہیں ہو؟ \n27۔ تم میں سے کون سوچ کر اس کے قد میں ایک کیوبٹ اضافہ کر سکتا ہے؟ \n28۔ اور تم لباس کے لیے کیوں سوچتے ہو؟ کھیت کے للیوں کو دیکھو، کیسے اگتے ہیں؛ وہ محنت نہیں کرتے، نہ کاتتے ہیں: \n29۔ اور پھر بھی میں تم سے کہتا ہوں، کہ حتیٰ کہ سلیمان بھی اپنی پوری شان میں ان میں سے ایک کی طرح نہیں تھا۔ \n30۔ کیوں اگر خدا کھیت کی گھاس کو اس طرح کپڑے پہنائے جو آج ہے، اور کل تندور میں ڈال دی جائے گی، تو کیا وہ تمہیں زیادہ لباس نہیں پہنائے گا، اے کم ایمان والے؟ \n31۔ لہٰذا سوچنا نہیں، یہ نہ کہو، ہم کیا کھائیں؟ یا، ہم کیا پئیں؟ یا، ہم کس چیز کے لیے کپڑے پہنیں گے؟ \n32۔ (کیونکہ ان سب باتوں کے بعد غیر یہودی تلاش کرتے ہیں:) کیونکہ تمہارا آسمانی باپ جانتا ہے کہ تمہیں ان سب چیزوں کی ضرورت ہے۔ \n33۔ لیکن سب سے پہلے خدا کی بادشاہی اور اس کی راستبازی کی تلاش کرو؛ اور یہ سب چیزیں تم میں شامل ہو جائیں گی۔ \n34۔ اس لیے کل کے بارے میں نہ سوچو: کیونکہ کل اپنی چیزوں کے بارے میں سوچے گا۔ آج تک اس کی برائی کافی ہے۔","1. فیصلہ نہ کرو کہ تم پر فیصلہ نہ کیا جائے۔ \n2۔ کیونکہ جس فیصلے سے تم فیصلہ کرو گے، تمہارا فیصلہ کیا جائے گا: اور جس پیمانے پر تم فیصلہ کرو گے، وہ تمہارے لیے دوبارہ ناپا جائے گا۔ \n3۔ اور تم اپنے بھائی کی آنکھ میں موجود روشنی کو کیوں دیکھتے ہو، لیکن اپنی آنکھ میں موجود روشنی کو کیوں نہیں دیکھتے؟ \n4۔ یا تم اپنے بھائی سے کیسے کہو گے، مجھے تمہاری آنکھ سے ذرہ نکالنے دو؛ اور دیکھو، تمہاری اپنی آنکھ میں ایک شعاع ہے؟ \n5۔ اے منافق، پہلے اپنی آنکھ سے شعاع نکالو؛ اور پھر صاف دیکھو کہ اپنے بھائی کی آنکھ سے روشنی نکالنا ہے۔ \n6۔ کتوں کو مقدس چیز نہ دو، نہ اپنے موتی سوروں کے سامنے پھینکو، ورنہ وہ انہیں اپنے قدموں تلے روندیں گے اور پھر مڑ کر تمہیں پھاڑ دیں گے۔ \n7۔ مانگو، اور تمہیں دیا جائے گا؛ تلاش کرو، اور تم پاؤ گے؛ دستک دو، اور یہ تمہارے لیے کھل جائے گا: \n8۔ کیونکہ جو بھی مانگتا ہے وہ قبول کرتا ہے؛ اور جو تلاش کرتا ہے وہ پاتا ہے؛ اور جو دستک دیتا ہے اسے کھول دیا جائے گا۔ \n9۔ یا تم میں سے کون سا آدمی ہے جو اگر اس کا بیٹا روٹی مانگے تو اسے پتھر دے گا؟ \n10۔ یا اگر وہ مچھلی مانگے، تو کیا وہ اسے سانپ دے گا؟ \n11۔ اگر تم برے ہو کر اپنے بچوں کو اچھے تحفے دینا جانتے ہو، تو تمہارا باپ جو آسمان پر ہے، ان لوگوں کو جو اس سے مانگتے ہیں، کتنی اور بھلائی دے گا؟ \n12۔ لہٰذا جو کچھ بھی تم چاہتے ہو کہ لوگ تمہارے ساتھ کریں، تم ان کے ساتھ بھی کرو: کیونکہ یہی قانون اور نبی ہیں۔ \n13۔ تنگ دروازے سے داخل ہو جاؤ: کیونکہ دروازہ چوڑا ہے، اور چوڑا راستہ ہے جو تباہی کی طرف لے جاتا ہے، اور وہاں سے بہت سے لوگ اندر جاتے ہیں: {تنگ: یا، تنگ}\n14. کیونکہ اسٹریٹ {ہے} دروازہ، اور تنگ {ہے} وہ راستہ ہے جو زندگی کی طرف لے جاتا ہے، اور بہت کم لوگ اسے پاتے ہیں۔ {کیونکہ: یا، کیسے}\n15۔ جھوٹے نبیوں سے ہوشیار رہو، جو بھیڑ کے لباس میں تمہارے پاس آتے ہیں، لیکن اندر سے وہ بھیڑیے ہیں۔ \n16۔ آپ انہیں ان کے پھلوں سے پہچانیں گے۔ کیا لوگ کانٹوں کے انگور یا کانٹے کے انجیر جمع کرتے ہیں؟ \n17۔ اسی طرح ہر اچھا درخت اچھا پھل لاتا ہے؛ لیکن بدعنوان درخت برا پھل لاتا ہے۔ \n18۔ اچھا درخت برا پھل نہیں دے سکتا، اور نہ ہی خراب درخت اچھا پھل دے سکتا ہے۔ \n19۔ ہر وہ درخت جو اچھا پھل نہیں دیتا اسے کاٹ کر آگ میں پھینک دیا جاتا ہے۔ \n20۔ اسی لیے ان کے پھلوں سے تم انہیں پہچانو گے۔ \n21. ہر وہ شخص جو مجھ سے کہے، اے خداوند، خداوند، آسمان کی بادشاہی میں داخل نہیں ہوگا؛ بلکہ جو میرے باپ کی مرضی کے مطابق جو آسمان میں ہے، وہ عمل کرے گا۔ \n22. اس دن بہت سے لوگ مجھ سے کہیں گے، اے خداوند، کیا ہم نے تیرے نام پر پیش گوئی نہیں کی؟ اور تیرے نام پر شیطانوں کو نکال دیا؟ اور تیرے نام پر بہت سے حیرت انگیز کام کیے؟ \n23۔ اور پھر میں ان سے کہوں گا کہ میں نے تمہیں کبھی نہیں جانا: مجھ سے دور ہو جاؤ، اے بدکاری کرنے والے۔ \n24۔ اس لیے جو بھی میری یہ باتیں سنتا ہے اور کرتا ہے، میں اسے ایک دانا آدمی سے تشبیہ دوں گا، جس نے اپنا گھر چٹان پر بنایا: \n25۔ اور بارش برسی، سیلاب آیا، اور ہوائیں چلیں، اور اس گھر پر ضرب لگائی؛ اور وہ نہیں گری، کیونکہ وہ ایک چٹان پر قائم تھا۔ \n26۔ اور جو بھی میری یہ باتیں سنے گا اور عمل نہیں کرے گا، اسے ایک بے وقوف آدمی سے تشبیہ دی جائے گی، جس نے اپنا گھر ریت پر بنایا: \n27۔ اور بارش برسی، سیلاب آیا، اور ہوائیں چلیں، اور اس گھر پر زور زور سے ٹکرائی؛ اور وہ گر گئی: اور اس کا زوال بہت بڑا تھا۔ \n28۔ اور جب یسوع نے یہ اقوال ختم کیے، تو لوگ ان کے عقیدے پر حیران رہ گئے: \n29۔ کیونکہ اس نے انہیں {ایک} کے طور پر سکھایا، نہ کہ کاتبوں کی طرح۔","1۔ جب وہ پہاڑ سے اترا تو بڑی تعداد اس کے پیچھے آئیں۔ \n2۔ اور دیکھو، ایک کوڑھی آیا اور اس کی عبادت کی، کہنے لگا، اے خداوند، اگر تو چاہو تو مجھے پاک کر سکتا ہے۔ \n3۔ اور یسوع نے اپنا ہاتھ آگے بڑھایا اور اسے چھوا اور کہا، میں کروں گا؛ تو پاک ہو جاؤ۔ اور فورا اس کا کوڑھ پاک ہو گیا۔ \n4۔ اور یسوع نے اس سے کہا، کسی کو نہ بتانا؛ بلکہ اپنی راہ پر جاؤ، پادری کے سامنے خود کو دکھاؤ، اور وہ تحفہ پیش کرو جو موسیٰ نے حکم دیا تھا، ان کے سامنے گواہی کے طور پر۔ \n5۔ اور جب یسوع کفرناؤم میں داخل ہوا، تو اس کے پاس ایک سینچورین آیا اور اس سے التجا کی، \n6۔ اور کہتا ہوں، اے خداوند، میرے بندے گھر پر بیمار پڑا ہے، شدید اذیت میں مبتلا ہے۔ \n7۔ اور یسوع نے اسے کہا، میں آؤں گا اور اسے شفا دوں گا۔ \n8۔ سینچورین نے جواب دیا اور کہا، اے خداوند، میں اس قابل نہیں ہوں کہ تم میرے گھر کے نیچے آؤ، بلکہ صرف کلام کہہ دو، اور میرا بندہ شفا پا جائے گا۔ \n9۔ کیونکہ میں ایک حکمران آدمی ہوں، جس کے نیچے سپاہی ہیں: اور میں اس {آدمی} سے کہتا ہوں، جاؤ، اور وہ جائے گا؛ اور دوسرے سے کہتا ہوں، آؤ، اور وہ آتا ہے؛ اور میرے خادم کو، یہ کرو، اور وہ کرے گا۔ \n10۔ جب یسوع نے یہ سنا، تو وہ حیران ہوا، اور ان لوگوں سے کہا، \"یقینا میں تم سے کہتا ہوں، میں نے اتنا بڑا ایمان نہیں پایا، نہیں، اسرائیل میں نہیں۔ \n11۔ اور میں تم سے کہتا ہوں، کہ بہت سے مشرق اور مغرب سے آئیں گے، اور ابراہیم، اسحاق اور یعقوب کے ساتھ آسمان کی بادشاہی میں بیٹھیں گے۔ \n12۔ لیکن بادشاہی کے بچے باہر کی تاریکی میں پھینک دیے جائیں گے: وہاں رونا اور دانت پیسنا ہوگا۔ \n13۔ اور یسوع نے سینچورین سے کہا، اپنا راستہ چلو؛ اور جیسا تم نے ایمان لکھا، {ویسے} تمہارے ساتھ بھی ایسا ہی ہو۔ اور اس کا خادم اسی وقت شفا پا گیا۔ \n14۔ اور جب یسوع پطرس کے گھر آئے تو انہوں نے اپنی بیوی کی ماں کو سوتے ہوئے اور بخار سے بیمار دیکھا۔ \n15۔ اور اس نے اس کا ہاتھ چھوا، اور بخار ختم ہو گیا، اور وہ اٹھ کر ان کی خدمت کرنے لگی۔ \n16۔ جب قیامت آئی، تو انہوں نے اس کے پاس بہت سے شیطانوں کو لایا جو جنون میں مبتلا تھے: اور اس نے اپنے کلام سے روحوں کو نکال دیا، اور سب بیماروں کو شفا دی: \n17۔ تاکہ وہ پورا ہو جو اسیعیا نبی نے کہا تھا، جس میں کہا تھا، اس نے ہماری کمزوریاں لے لیں اور ہماری بیماریوں کو جنم دیا۔ \n18۔ جب یسوع نے اپنے ارد گرد بڑی تعداد دیکھی، تو اس نے حکم دیا کہ وہ دوسری طرف روانہ ہو جائے۔ \n19۔ اور ایک کاتب آیا اور اس سے کہا، مالک، میں تمہارے پیچھے جاؤں گا جہاں بھی تم جاؤ گے۔ \n20۔ اور یسوع نے اسے کہا، لومڑیوں کے سوراخ ہیں، اور ہوا کے پرندوں کے گھونسلے ہیں؛ لیکن انسان کے بیٹے کے پاس اپنا سر رکھنے کی جگہ نہیں ہے۔ \n21۔ اور اس کے ایک اور شاگرد نے اس سے کہا، اے خداوند، مجھے پہلے اجازت دے کہ میں جا کر اپنے والد کو دفن کروں۔ \n22۔ لیکن یسوع نے اس سے کہا، میرے پیچھے آؤ؛ اور مردوں کو اپنے مردوں کو دفن کرنے دو۔ \n23۔ اور جب اسے جہاز میں داخل کیا گیا تو اس کے شاگرد اس کے پیچھے آئے۔ \n24۔ اور دیکھو، سمندر میں ایک زبردست طوفان آیا، یہاں تک کہ جہاز لہروں سے ڈھک گیا: لیکن وہ سو رہا تھا۔ \n25۔ اور اس کے شاگرد اس کے پاس آئے، اور اسے جگایا اور کہا، خداوند، ہمیں بچا، ہم تباہ ہو جائیں گے۔ \n26۔ اور وہ ان سے کہتا ہے، اے کم ایمان والوں، تم کیوں ڈرتے ہو؟ پھر وہ اٹھا، اور ہواؤں اور سمندر کو ڈانٹا؛ اور وہاں بہت سکون ہوا۔ \n27۔ لیکن لوگ حیران رہ گئے اور کہا، یہ کیسا انسان ہے کہ ہوا اور سمندر بھی اس کی اطاعت کرتے ہیں! \n28۔ اور جب وہ گرگیسینز کے علاقے کے دوسری طرف پہنچا، تو وہاں دو شیطانوں سے ملے، جو قبروں سے نکل رہے تھے، اتنے خوفناک کہ کوئی بھی اس راستے سے نہ گزر سکے۔ \n29۔ اور دیکھتے ہی وہ پکارے، کہنے لگے، یسوع، اے خدا کے بیٹے، ہمارا تجھ سے کیا تعلق ہے؟ کیا تم وقت سے پہلے ہمیں اذیت دینے آئے ہو؟ \n30۔ اور ان سے کافی دور ایک ریوڑ تھا جو بہت سے سور کھا رہا تھا۔ \n31۔ تو شیطانوں نے اس سے التجا کی، کہا، اگر تم ہمیں نکال دو تو ہمیں سوروں کے ریوڑ میں جانے دو۔ \n32۔ اور اس نے ان سے کہا، جاؤ۔ اور جب وہ باہر آئے تو وہ سوروں کے ریوڑ میں چلے گئے: اور دیکھتے ہی پورا سور کا ریوڑ زور زور سے ایک ڈھلوان جگہ سے سمندر میں دوڑتا ہوا پانی میں مر گیا۔ \n33۔ اور جنہوں نے انہیں روکا وہ بھاگ گئے، اور شہر میں داخل ہو گئے، اور شیطانوں کے قبضے میں آنے والوں کو سب کچھ اور جو کچھ ہوا وہ سب بتایا۔ \n34۔ اور دیکھو، پورا شہر یسوع سے ملنے نکلا: اور جب انہوں نے اسے دیکھا تو انہوں نے اس سے درخواست کی کہ وہ ان کے ساحلوں سے نکل جائے۔","1۔ اور وہ ایک جہاز میں داخل ہوا، گزر گیا، اور اپنے ہی شہر میں آیا۔ \n2۔ اور دیکھو، انہوں نے اس کے پاس ایک بیمار شخص کو بستر پر لیٹا لایا: اور یسوع نے ان کے ایمان کو دیکھ کر بیمار لوگوں سے کہا؛ بیٹا، خوش رہو؛ تمہارے گناہ معاف ہو جاؤ۔ \n3۔ اور دیکھو، کچھ کاتبوں نے اپنے اندر کہا، یہ {انسان} کفر کرتا ہے۔ \n4۔ اور یسوع نے ان کے خیالات کو جانتے ہوئے کہا، تم اپنے دلوں میں برے کیوں سوچتے ہو؟ \n5. کیونکہ یہ کہنا آسان ہے کہ {تمہارے} گناہ معاف ہو جائیں؛ یا یہ کہنا کہ اٹھو اور چلو؟ \n6۔ لیکن تاکہ تم جان سکو کہ انسان کا بیٹا زمین پر گناہوں کو معاف کرنے کی طاقت رکھتا ہے، (پھر وہ بیمار بیمار سے کہتا ہے،\" اٹھو، اپنا بستر سنبھالو، اور اپنے گھر جاؤ۔ \n7۔ اور وہ اٹھا اور اپنے گھر چلا گیا۔ \n8۔ لیکن جب ہجوم نے اسے دیکھا تو وہ حیران رہ گئے اور خدا کی جلال دی، جس نے انسانوں کو ایسی طاقت دی تھی۔ \n9۔ اور جب یسوع وہاں سے نکلے، تو انہوں نے ایک آدمی کو دیکھا، جس کا نام متی تھا، رسم و رواج کی وصولی پر بیٹھا تھا: اور اس نے اسے کہا، میرے پیچھے آؤ۔ اور وہ اٹھا اور اس کے پیچھے چلا گیا۔ \n10۔ اور ایسا ہوا، جب یسوع گھر میں گوشت کھا رہا تھا، دیکھو، بہت سے پبلکرز اور گناہ گار آئے اور اس کے اور اس کے شاگردوں کے ساتھ بیٹھ گئے۔ \n11۔ اور جب فریسیوں نے یہ دیکھا، تو انہوں نے اس کے شاگردوں سے کہا، \"اپنے آقا کو پبلکرز اور گناہ گاروں کے ساتھ کیوں کھاتے ہیں؟ \n12۔ لیکن جب یسوع نے سنا {یہ} تو انہوں نے ان سے کہا، جو صحت مند ہیں انہیں طبیب کی ضرورت نہیں، بلکہ بیمار لوگوں کو چاہیے۔ \n13۔ لیکن تم جاؤ اور جانو کہ اس کا کیا مطلب ہے، میں رحم کروں گا، قربانی نہیں: کیونکہ میں راستبازوں کو بلانے نہیں آیا بلکہ گناہ گاروں کو توبہ کی طرف بلایا ہوں۔ \n14۔ پھر یوحنا کے شاگرد اس کے پاس آئے اور کہا، \"ہم اور فریسی اکثر روزہ کیوں رکھتے ہیں، لیکن تمہارے شاگرد روزہ نہیں رکھتے؟ \n15۔ اور یسوع نے ان سے کہا، کیا دلہن کے بچے سوگ منا سکتے ہیں، جب تک دولہا ان کے ساتھ ہے؟ لیکن وہ دن آئیں گے جب دولہا ان سے چھین لیا جائے گا، اور پھر وہ روزہ رکھیں گے۔ \n16۔ کوئی شخص نئے کپڑے کا ٹکڑا پرانے کپڑے پر نہیں ڈالتا، کیونکہ جو چیز اسے بھرنے کے لیے ڈالی جاتی ہے وہ لباس سے نکل جاتی ہے، اور دراڑ مزید خراب ہو جاتی ہے۔ {نیا: یا، کچا، یا، بے ساختہ}\n17۔ انسان نئی شراب پرانی بوتلوں میں نہیں ڈالتے: ورنہ بوتلیں ٹوٹ جاتی ہیں، شراب ختم ہو جاتی ہے، اور بوتلیں ختم ہو جاتی ہیں؛ لیکن نئی شراب نئی بوتلوں میں ڈال دی جاتی ہے، اور دونوں محفوظ رہتی ہیں۔ {بوتلیں: یا، کھال کے تھیلے، یا چمڑے}\n18۔ جب اس نے یہ باتیں ان سے کیں، تو ایک حکمران آیا اور اس کی عبادت کی، کہنے لگا، میری بیٹی اب بھی مر چکی ہے، لیکن آؤ اور اس پر ہاتھ رکھو، وہ زندہ رہے گی۔ \n19۔ اور یسوع اٹھے، اور ان کے پیچھے گئے، اور {ویسے} ان کے شاگردوں نے بھی پیروی کی۔ \n20۔ اور دیکھو، ایک عورت، جو بارہ سال سے خون کی بیماری میں مبتلا تھی، اس کے پیچھے آئی اور اس کے لباس کے کنارے کو چھوا: \n21۔ کیونکہ اس نے اپنے اندر کہا، اگر میں اس کے لباس کو چھو سکوں تو میں مکمل ہو جاؤں گی۔ \n22۔ لیکن یسوع نے اسے پلٹا دیا، اور جب اس نے اسے دیکھا تو کہا، بیٹی، آرام دہ رہو؛ تمہارا ایمان تمہیں مکمل کر چکا ہے۔ اور عورت اس وقت سے مکمل ہوئی۔ \n23۔ اور جب یسوع حکمران کے گھر آیا، اور موسیقاروں اور لوگوں کو شور کرتے دیکھا، \n24۔ اس نے ان سے کہا، جگہ دو، کیونکہ کنواری مر نہیں گئی، بلکہ سو رہی ہے۔ اور وہ اس پر مذاق اڑاتے تھے۔ \n25۔ لیکن جب لوگ سامنے آئے، تو وہ اندر گیا، اس نے اس کا ہاتھ پکڑ لیا، اور نوکرانی اٹھ کھڑی ہوئی۔ \n26۔ اور اس کی شہرت اس پورے ملک میں پھیل گئی۔ {شہرت...: یا، یہ شہرت}\n27۔ اور جب یسوع وہاں سے روانہ ہوئے، دو اندھے آدمی اس کے پیچھے چلے، روتے ہوئے اور کہا، {تو} داؤد کے بیٹے، ہم پر رحم فرما۔ \n28۔ اور جب وہ گھر میں آیا، تو اندھے لوگ اس کے پاس آئے: اور یسوع نے ان سے کہا، کیا تم یقین کرو کہ میں یہ کر سکتا ہوں؟ انہوں نے اس سے کہا، ہاں، خداوند۔ \n29۔ پھر اس نے ان کی آنکھوں کو چھوا اور کہا، تمہارے ایمان کے مطابق تم پر ہو۔ \n30۔ اور ان کی آنکھیں کھل گئیں؛ اور یسوع نے سختی سے ان پر حملہ کیا، کہا، دیکھو {کہ} کوئی نہیں جانتا۔ \n31۔ لیکن جب وہ چلے گئے، تو انہوں نے اس کی شہرت پورے ملک میں پھیلائی۔ \n32۔ جب وہ باہر نکلے، تو انہوں نے اس کے پاس ایک گونگا آدمی لے آیا جو شیطان کے قبضے میں مبتلا تھا۔ \n33۔ اور جب شیطان کو نکال دیا گیا، تو گونگے بولے: اور ہجوم حیران ہو کر کہنے لگے، اسرائیل میں ایسا کبھی نہیں دیکھا گیا۔ \n34۔ لیکن فریسیوں نے کہا، وہ شیطانوں کے شہزادے کے ذریعے شیطانوں کو نکال دیتا ہے۔ \n35۔ اور یسوع نے تمام شہروں اور دیہاتوں میں گھوم کر ان کے عبادت گاہوں میں تعلیم دی، بادشاہی کی خوشخبری سنائی، اور لوگوں میں ہر بیماری اور بیماری کو شفا دی۔ \n36۔ لیکن جب اس نے ہجوم کو دیکھا، تو اس پر رحم ہوا، کیونکہ وہ بے ہوش ہو گئے اور ایسے بکھر گئے جیسے بھیڑیں جن کا چرواہا نہ ہو۔ {بے ہوش...: یا، تھک کر لیٹ گئے}\n37۔ پھر وہ اپنے شاگردوں سے کہتا ہے، فصل واقعی وافر ہے، لیکن مزدور کم ہیں؛ \n38۔ لہٰذا فصل کے رب سے دعا کرو کہ وہ اپنی فصل میں مزدور بھیجے۔","1۔ اور جب اس نے اپنے بارہ شاگردوں کو بلایا، تو اس نے انہیں ناپاک روحوں کے خلاف طاقت دی، انہیں نکالنے اور ہر قسم کی بیماری اور بیماری کو شفا دینے کے لیے۔ {خلاف: یا، ختم}\n2۔ اب بارہ رسولوں کے نام یہ ہیں؛ پہلا، شمعان، جسے پطرس کہا جاتا ہے، اور اس کا بھائی اندریو؛ زبدی کا یعقوب {بیٹا}، اور یوحنا اس کا بھائی؛ \n3۔ فلپ، اور بارتھولومیو؛ تھامس، اور میتھیو پبلکن؛ جیمز {بیٹا} الفائیئس کا، اور لیبیئس، جس کا خاندانی نام تھاڈیئس تھا؛ \n4۔ شمعون کنعانی، اور یہودا اسخریوطی، جس نے بھی اسے دھوکہ دیا۔ \n5۔ یہ بارہ یسوع نے بھیجے اور انہیں حکم دیا، کہ غیر یہودیوں کے راستے میں نہ جاؤ، اور سامری کے کسی بھی شہر میں مت آؤ: \n6۔ بلکہ اسرائیل کے گھر کی کھوئی ہوئی بھیڑوں کی طرف جاؤ۔ \n7۔ اور جب تم جاؤ، تبلیغ کرو، کہو، آسمان کی بادشاہی قریب ہے۔ \n8۔ بیماروں کو شفا دو، کوڑھیوں کو پاک کرو، مردوں کو زندہ کرو، شیطانوں کو نکالو: تم نے آزادانہ طور پر دیا ہے، آزادانہ طور پر دو۔ \n9. اپنے پرس میں سونا، چاندی یا پیتل نہ فراہم کرو، {فراہم کرو: یا حاصل کرو}\n10۔ نہ ہی {تمہارے} سفر کے لیے لکھار، نہ دو کوٹ، نہ جوتے، نہ لاٹھیاں: کیونکہ مزدور اپنے گوشت کے لائق ہے۔ {چھڑی}\n11۔ اور جس بھی شہر یا قصبے میں تم داخل ہو وہاں پہنچو، پوچھو کہ وہاں کون لائق ہے؛ اور وہاں رہو جب تک تم وہاں سے نہ چلے جاؤ۔ \n12۔ اور جب تم کسی گھر میں آؤ تو اسے سلام کرو۔ \n13۔ اور اگر گھر لائق ہے تو اس پر سکون آئے: اور اگر وہ قابل نہ ہو تو تمہارا سکون تمہارے پاس واپس آ جائے۔ \n14. اور جو تمہیں قبول نہیں کرے گا، اور تمہارے الفاظ نہیں سنے گا، جب تم اس گھر یا شہر سے نکلو گے، تو اپنے قدموں کی خاک جھاڑ دو۔ \n15. یقینا میں تم سے کہتا ہوں، قیامت کے دن سدوم اور عمورہ کی سرزمین کے لیے اس شہر سے زیادہ قابل برداشت ہوگا۔ \n16۔ دیکھو، میں تمہیں بھیڑیوں کے درمیان بھیڑ کی طرح بھیجتا ہوں: لہٰذا تم سانپوں کی طرح دانا اور کبوتر کی طرح بے ضرر بنو۔ {بے ضرر: یا، سادہ}\n17۔ لیکن انسانوں سے ہوشیار رہو: کیونکہ وہ تمہیں کونسلوں کے حوالے کر دیں گے، اور اپنے عبادت گاہوں میں تمہیں کوڑے ماریں گے؛ \n18۔ اور تم حکمرانوں اور بادشاہوں کے سامنے میرے لیے پیش کیے جاؤ گے، ان اور غیر قوموں کے خلاف گواہی کے لیے۔ \n19۔ لیکن جب وہ تمہیں حوالے کریں، تو یہ نہ سوچنا کہ تم کیسے یا کیا بولو گے، کیونکہ اسی وقت تمہیں وہی ملے گا جو تم بولو گے۔ \n20۔ کیونکہ تم بولنے والے نہیں بلکہ تمہارے باپ کی روح تم میں بولتی ہے۔ \n21۔ اور بھائی بھائی کو موت کے حوالے کرے گا، اور باپ بچے کو: اور بچے اپنے والدین کے خلاف اٹھ کھڑے ہوں گے، اور انہیں قتل کروا دیں گے۔ \n22۔ اور تم سب {انسان} سے میرے نام کی خاطر نفرت کرو گے: لیکن جو آخر تک برداشت کرے گا وہ نجات پائے گا۔ \n23. لیکن جب وہ اس شہر میں تمہیں ستاتے ہیں، تو تم دوسرے شہر میں بھاگ جاؤ: کیونکہ میں تم سے کہتا ہوں، تم اسرائیل کے شہروں پر نہیں جاؤ گے، جب تک کہ انسان کا بیٹا نہ آ جائے۔ {کیا ہے...: یا، ختم، یا، ختم}\n24۔ شاگرد اپنے مالک سے بالاتر نہیں، اور خادم اپنے رب سے بالاتر نہیں۔ \n25۔ شاگرد کے لیے کافی ہے کہ وہ اس کا مالک ہو، اور خادم اس کا آقا۔ اگر انہوں نے گھر کے مالک بیلزبوب کو بلایا ہے، تو وہ اپنے گھرانے کے کتنے اور لوگ بلائیں گے؟ {بیلزبب: گری۔ بیلزبول}\n26۔ لہٰذا ان سے نہ ڈرو: کیونکہ کوئی چھپی ہوئی چیز نہیں جو ظاہر نہ ہو؛ اور چھپی ہو، جو معلوم نہ ہو۔ \n27۔ جو میں تمہیں اندھیرے میں کہتا ہوں، {کہ} روشنی میں بولو: اور جو تم کان میں سنتے ہو، {جو} گھروں کی چھتوں پر تبلیغ کرو۔ \n28۔ اور ان سے نہ ڈرو جو جسم کو مارتے ہیں، لیکن روح کو مار نہیں سکتے، بلکہ اس سے ڈرو جو جہنم میں روح اور جسم دونوں کو تباہ کر سکتا ہے۔ \n29۔ کیا دو چڑیاں ایک فارتھنگ میں نہیں بیچی جاتیں؟ اور ان میں سے ایک تمہارے والد کے بغیر زمین پر نہیں گرے گی۔ {فارتھنگ: اصل میں اس کی قیمت آدھی پینی فارتھنگ ہے، جو رومن پینی کا دسواں حصہ ہے}\n30۔ لیکن تمہارے سر کے بال بھی گنے ہوئے ہیں۔ \n31۔ اس لیے ڈرو مت، تم بہت سی چڑیوں سے زیادہ قیمتی ہو۔ \n32۔ جو بھی لوگوں کے سامنے مجھے اقرار کرے گا، میں بھی اپنے آسمانی باپ کے سامنے اس کا اقرار کروں گا۔ \n33۔ لیکن جو بھی لوگوں کے سامنے مجھے انکار کرے گا، میں بھی اسے اپنے آسمانی باپ کے سامنے انکار کروں گا۔ \n34۔ یہ نہ سمجھو کہ میں زمین پر امن بھیجنے آیا ہوں: میں امن بھیجنے نہیں آیا بلکہ تلوار بھیجنے آیا ہوں۔ \n35۔ کیونکہ میں آیا ہوں کہ ایک آدمی کو اس کے والد کے خلاف، بیٹی کو اس کی ماں کے خلاف، اور بہو کو اس کی ساس کے خلاف کھڑا کروں۔ \n36۔ اور انسان کے دشمن اس کے اپنے گھرانے کے ہوں گے۔ \n37۔ جو باپ یا ماں سے مجھ سے زیادہ محبت کرتا ہے وہ میرے لائق نہیں؛ اور جو بیٹے یا بیٹی سے مجھ سے زیادہ محبت کرتا ہے وہ میرے لائق نہیں۔ \n38۔ اور جو اپنی صلیب نہیں لیتا اور میرے پیچھے چلتا ہے، وہ میرے لائق نہیں۔ \n39۔ جو اپنی جان پائے گا وہ اسے کھو دے گا: اور جو میری خاطر اپنی جان کھوئے گا وہ اسے پائے گا۔ \n40. جو تمہیں لیتا ہے وہ مجھے قبول کرتا ہے، اور جو مجھے قبول کرتا ہے وہ مجھے بھیجتا ہے۔ \n41۔ جو نبی کے نام پر نبی کو قبول کرے گا، اسے نبی کا اجر ملے گا؛ اور جو نیک آدمی کے نام پر نیک کو قبول کرے گا، اسے نیک آدمی کا اجر ملے گا۔ \n42۔ اور جو بھی ان چھوٹے بچوں میں سے کسی کو صرف شاگرد کے نام پر ٹھنڈا پانی پینے کے لیے دے، میں تم سے کہتا ہوں، وہ اپنا انعام کبھی نہیں کھوئے گا۔","1۔ اور ایسا ہوا، جب یسوع نے اپنے بارہ شاگردوں کو حکم دینے کا کام ختم کیا، تو وہ وہاں سے روانہ ہوا تاکہ ان کے شہروں میں تعلیم دے اور تبلیغ کرے۔ \n2۔ جب یوحنا نے قید خانے میں مسیح کے اعمال سنے، تو اس نے اپنے دو شاگرد بھیجے، \n3۔ اور اس سے کہا، کیا تم وہ ہو جو آنا چاہیے، یا ہم کسی اور کی تلاش میں ہیں؟ \n4۔ یسوع نے جواب دیا اور ان سے کہا، جاؤ اور وہ چیزیں دوبارہ یوحنا دکھاؤ جو تم سنتے اور دیکھتے ہو: \n5. اندھے اپنی بینائی حاصل کرتے ہیں، لنگڑے چلتے ہیں، کوڑھی پاک ہوتے ہیں، بہرے سنتے ہیں، مردوں کو زندہ کیا جاتا ہے، اور غریبوں کو خوشخبری سنائی جاتی ہے۔ \n6۔ اور مبارک ہے {وہ}، جو مجھ میں ناراض نہ ہو۔ \n7۔ اور جب وہ روانہ ہوئے، یسوع نے یوحنا کے بارے میں ہجوم سے پوچھنا شروع کیا، تم لوگ صحرا میں کیا دیکھنے گئے تھے؟ ہوا سے ہلنے والا گھاسہ؟ \n8۔ لیکن تم دیکھنے کیوں گئے تھے؟ نرم لباس میں ملبوس آدمی؟ دیکھو، جو نرم لباس پہنتے ہیں وہ بادشاہوں کے گھروں میں ہوتے ہیں۔ \n9۔ لیکن تم کس لیے باہر گئے تھے؟ ایک نبی؟ ہاں، میں تم سے کہتا ہوں، اور نبی سے بھی زیادہ۔ \n10۔ کیونکہ یہ وہی ہے، جس کے بارے میں یہ لکھا گیا ہے، دیکھو، میں اپنا پیغامبر تمہارے سامنے بھیجتا ہوں، جو تمہارے سامنے راستہ تیار کرے گا۔ \n11۔ یقینا میں تم سے کہتا ہوں، جو عورتوں سے پیدا ہوئے ہیں ان میں یوحنا بپتسمہ دینے والے سے بڑا کوئی نہیں اٹھا: اگرچہ جو آسمان کی بادشاہی میں سب سے کم ہے وہ اس سے بڑا ہے۔ \n12. اور یوحنا بپتسمہ دینے والے کے دنوں سے اب تک آسمان کی بادشاہی تشدد کا شکار ہے، اور پرتشدد لوگ اسے زبردستی لے لیتے ہیں۔ {برداشت کرتا ہے...: یا، زبردستی حاصل کیا جاتا ہے، اور جو لوگوں کو دھکیلتا ہے}\n13۔ کیونکہ تمام انبیاء اور شریعت نے یوحنا تک نبوت کی تھی۔ \n14. اور اگر تم اسے قبول کرو گے، تو یہ ایلیاس ہے، جو آنے والا تھا۔ \n15۔ جس کے پاس سننے کے لیے کان ہیں، اسے سننے دو۔ \n16۔ لیکن میں اس نسل کو کہاں تشبیہ دوں؟ یہ ایسے بچوں کی طرح ہے جو بازاروں میں بیٹھے ہیں اور اپنے ساتھیوں کو پکار رہے ہیں، \n17۔ اور کہا، ہم نے تمہیں آواز دی ہے، اور تم نے رقص نہیں کیا؛ ہم نے تمہارے لیے سوگ منایا ہے، اور تم نے افسوس نہیں کیا۔ \n18۔ کیونکہ یوحنا نہ کھاتا ہے نہ پیتا ہے، اور کہتے ہیں، اس کے پاس شیطان ہے۔ \n19۔ انسان کا بیٹا کھاتا اور پیتا آیا، اور کہتے ہیں، دیکھو ایک لالچی آدمی اور شراب نوشی کرنے والا، جو پبکانے والوں اور گناہ گاروں کا دوست ہے۔ لیکن اس کے بچوں کی حکمت جائز ہے۔ \n20۔ پھر اس نے ان شہروں کو ڈانٹنا شروع کیا جہاں اس کے زیادہ تر عظیم کام کیے گئے، کیونکہ وہ توبہ نہیں کرتے تھے: \n21۔ تم پر افسوس، خورازین! تم پر افسوس، بیت سعیدا! کیونکہ اگر وہ عظیم اعمال جو تم میں کیے گئے، صور اور صیدا میں کیے گئے ہوتے، تو وہ بہت پہلے بوریوں اور راکھ میں توبہ کر چکے ہوتے۔ \n22. لیکن میں تم سے کہتا ہوں، قیامت کے دن صور اور صیدا کے لیے تمہارے مقابلے میں زیادہ قابل برداشت ہوگا۔ \n23. اور تو، کفرناؤم، جو آسمان کی طرف بلند ہے، جہنم میں اتارا جائے گا: کیونکہ اگر وہ عظیم اعمال جو تم میں کیے گئے ہوں، سدوم میں کیے گئے ہوتے، تو وہ آج تک قائم رہتے۔ \n24. لیکن میں تم سے کہتا ہوں، کہ قیامت کے دن سدوم کی سرزمین کے لیے یہ تمہارے مقابلے میں زیادہ قابل برداشت ہوگا۔ \n25۔ اس وقت یسوع نے جواب دیا اور کہا، اے باپ، آسمان و زمین کے رب، میں تیرا شکر گزار ہوں کہ تو نے یہ باتیں دانا اور عاقل لوگوں سے چھپائیں اور بچوں کو ظاہر کر دیں۔ \n26. پھر بھی، اے باپ: کیونکہ یہ تمہاری نظر میں اچھا لگا۔ \n27۔ میرے باپ کی طرف سے سب کچھ مجھے دیا گیا ہے: اور کوئی بھی بیٹے کو نہیں جانتا، سوائے باپ کے؛ نہ ہی کسی باپ کو جانتا ہے، سوائے بیٹے کے، اور {وہ} جسے بھی بیٹا ظاہر کرے {اسے}۔ \n28۔ میرے پاس آؤ، تم سب جو محنت کرتے ہو اور بھاری بوجھ اٹھاتے ہو، اور میں تمہیں آرام دوں گا۔ \n29۔ میرا جوا اپنے اوپر اٹھاؤ، اور میرے بارے میں جانو؛ کیونکہ میں نرم دل اور کمزور ہوں: اور تم اپنی روحوں کو سکون پاؤ گے۔ \n30۔ کیونکہ میرا یوق آسان ہے، اور میرا بوجھ ہلکا ہے۔","1۔ اس وقت یسوع سبت کے دن اناج کے ذریعے گیا؛ اور اس کے شاگرد بھوکے تھے، اور مکئی کے کان توڑنا اور کھانا شروع کر دیا۔ \n2۔ لیکن جب فریسیوں نے یہ دیکھا، تو انہوں نے اس سے کہا، دیکھو، تمہارے شاگرد وہ کام کرتے ہیں جو ہفتہ کے دن ناجائز ہے۔ \n3۔ لیکن اس نے ان سے کہا، کیا تم نے نہیں پڑھا کہ داؤد نے کیا کیا، جب وہ بھوکا تھا، اور جو اس کے ساتھ تھے؟ \n4۔ وہ خدا کے گھر میں کیسے داخل ہوا اور وہ روٹی کھائی، جو نہ اس کے لیے جائز تھی، نہ ہی ان کے لیے جو اس کے ساتھ تھے، بلکہ صرف پادریوں کے لیے؟ \n5۔ یا آپ نے شریعت میں یہ نہیں پڑھا کہ ہفتہ کے دنوں میں مندر کے پادری سبت کی بے حرمتی کرتے ہیں اور بے گناہ ہوتے ہیں؟ \n6۔ لیکن میں تم سے کہتا ہوں، کہ اس جگہ میں {ایک} مندر سے بڑا ہے۔ \n7۔ لیکن اگر تم جانتے کہ {یہ} کیا مطلب ہے، تو میں رحم کروں گا، قربانی نہیں، تو تم بے گناہ والوں کو سزا نہ دیتے۔ \n8۔ کیونکہ انسان کا بیٹا ہفتہ کے دن بھی خداوند ہے۔ \n9۔ اور جب وہ وہاں سے روانہ ہوئے، تو وہ ان کی عبادت گاہ میں گئے: \n10۔ اور دیکھو، ایک آدمی تھا جس کا ہاتھ خشک ہو گیا تھا۔ اور انہوں نے اس سے پوچھا، پوچھا، کیا سبت کے دن شفا دینا جائز ہے؟ تاکہ وہ اس پر الزام لگا سکیں۔ \n11۔ اور اس نے ان سے کہا، تم میں سے کون سا ہوگا جس کے پاس ایک بھیڑ ہو، اور اگر وہ سبت کے دن گڑھے میں گر جائے تو کیا وہ اسے پکڑ کر باہر نہیں اٹھائے گا؟ \n12۔ تو پھر ایک آدمی بھیڑ سے کتنا بہتر ہے؟ اسی لیے سبت کے دنوں میں اچھا کرنا جائز ہے۔ \n13۔ پھر وہ آدمی سے کہتا ہے، اپنا ہاتھ پھیلاؤ۔ اور اس نے اسے پھیلایا؛ اور وہ بالکل ٹھیک ہو گیا، جیسے دوسرا۔ \n14۔ پھر فریسیوں باہر نکلے اور اس کے خلاف ایک مجلس کی کہ وہ اسے کیسے تباہ کر سکتے ہیں۔ {رہا...: یا، مشورہ کیا}\n15۔ لیکن جب یسوع کو معلوم ہوا، تو اس نے خود کو وہاں سے الگ کر لیا: اور بڑی تعداد اس کے پیچھے آئی، اور اس نے سب کو شفا دی؛ \n16۔ اور انہیں حکم دیا کہ وہ اسے ظاہر نہ کریں: \n17۔ تاکہ وہ عمل پورا ہو جو اشیاس نبی نے کہا تھا، \n18۔ دیکھو میرا بندہ جسے میں نے چنا ہے؛ میرا محبوب، جس میں میری جان خوش ہے: میں اپنی روح اس پر ڈالوں گا، اور وہ غیر قوموں پر فیصلہ کرے گا۔ \n19۔ وہ نہ کوشش کرے گا، نہ روئے گا؛ نہ ہی کوئی اس کی آواز سڑکوں پر سنے گا۔ \n20۔ زخمی سرکنڈے کو وہ نہیں توڑے گا، اور دھواں دار فلیس بھی نہیں بجھائے گا، جب تک کہ وہ فتح کے لیے فیصلہ نہ کرے۔ \n21۔ اور غیر یہودی اس کے نام پر بھروسہ کریں گے۔ \n22۔ پھر اس کے پاس ایک شیطان کا دیوانہ لایا گیا، جو اندھا اور گونگا تھا، اور اس نے اسے شفا دی، یہاں تک کہ اندھے اور گونگے دونوں بولتے اور دیکھتے رہے۔ \n23۔ اور سب لوگ حیران رہ گئے اور کہا، کیا یہ داؤد کا بیٹا نہیں؟ \n24. لیکن جب فریسیوں نے سنا تو انہوں نے کہا، یہ {بندہ} شیطانوں کو نہیں نکالتا، بلکہ شیطانوں کے شہزادے بیلزبوب کے ذریعے نکالتا ہے۔ {بیلزبب: یونانی بیلزبول}\n25۔ اور یسوع نے ان کے خیالات کو جانا، اور ان سے کہا، ہر بادشاہی جو اپنے خلاف تقسیم ہو، ویران ہو جاتی ہے؛ اور ہر شہر یا گھر جو اپنے خلاف تقسیم ہو جائے گا وہ قائم نہیں رہے گا: \n26۔ اور اگر شیطان شیطان کو نکال دے، تو وہ اپنے خلاف تقسیم ہو جائے گا؛ تو پھر اس کی بادشاہی کیسے قائم ہوگی؟ \n27۔ اور اگر میں بیلزبوب کے ذریعے شیطانوں کو نکالوں، تو تمہارے بچے کس کے ذریعے انہیں نکالیں گے؟ اسی لیے وہ تمہارے منصف ہوں گے۔ \n28۔ لیکن اگر میں خدا کی روح سے شیطانوں کو نکال دوں، تو خدا کی بادشاہی تمہارے پاس آ جائے گی۔ \n29۔ ورنہ کوئی طاقتور آدمی کے گھر میں کیسے داخل ہو سکتا ہے اور اس کا مال خراب کر سکتا ہے، سوائے اس کے کہ پہلے طاقتور آدمی کو باندھ دے؟ اور پھر وہ اپنا گھر خراب کر دے گا۔ \n30۔ جو میرے ساتھ نہیں ہے وہ میرے خلاف ہے؛ اور جو میرے ساتھ جمع نہیں ہوتا وہ باہر بکھر جاتا ہے۔ \n31۔ اسی لیے میں تم سے کہتا ہوں، ہر قسم کے گناہ اور کفر انسانوں کو معاف کر دیا جائے گا: لیکن {روحان} کے خلاف کفر انسانوں کو معاف نہیں کیا جائے گا۔ \n32۔ اور جو بھی انسان کے بیٹے کے خلاف ایک لفظ کہے گا، اسے معاف کیا جائے گا؛ لیکن جو بھی روح القدس کے خلاف بولے گا، اسے معاف نہیں کیا جائے گا، نہ اس دنیا میں، نہ آنے والی دنیا میں۔ \n33۔ یا تو درخت کو اچھا اور اس کے پھل کو اچھا بنا دو؛ یا پھر درخت کو خراب کر دو، اور اس کے پھل کو خراب کرو، کیونکہ درخت اس کے پھل سے جانا جاتا ہے۔ \n34۔ اے سانپوں کی نسل، تم برے ہونے کی وجہ سے اچھی باتیں کیسے کر سکتے ہو؟ کیونکہ دل کی فراوانی سے منہ بولتا ہے۔ \n35۔ اچھا آدمی دل کے اچھے خزانے سے اچھی چیزیں نکالتا ہے؛ اور برا انسان برے خزانے سے برے کام لاتا ہے۔ \n36۔ لیکن میں تم سے کہتا ہوں، کہ لوگ جو بھی فضول بات کہیں گے، قیامت کے دن اس کا حساب دیں گے۔ \n37۔ کیونکہ تمہارے الفاظ سے تم راستباز بنو گے، اور تمہارے الفاظ سے تم سزا پاؤ گے۔ \n38۔ پھر کچھ کاتبوں اور فریسیوں نے جواب دیا، کہا، استاد، ہم آپ سے کوئی نشانی دیکھنا چاہتے ہیں۔ \n39۔ لیکن اس نے جواب دیا اور ان سے کہا، ایک بدکار اور کرنے والی نسل ایک نشانی کی تلاش میں ہے؛ اور اس کے لیے کوئی نشانی نہیں دی جائے گی، سوائے نبی یونس کی نشانی کے: \n40۔ جیسے یوناس تین دن اور تین راتیں وہیل کے پیٹ میں تھا؛ اسی طرح انسان کا بیٹا زمین کے دل میں تین دن اور تین راتیں رہے گا۔ \n41۔ نینوا کے لوگ اس نسل کے ساتھ عدالت میں اٹھیں گے، اور اسے مذمت کریں گے: کیونکہ انہوں نے یونس کی تبلیغ پر توبہ کی؛ اور دیکھو، یہاں یونس سے بڑا ہے۔ \n42۔ جنوب کی ملکہ اس نسل کے ساتھ فیصلے میں اٹھے گی، اور اسے مذمت کرے گی: کیونکہ وہ زمین کے دور دراز حصوں سے آئی ہے تاکہ سلیمان کی حکمت سنے؛ اور دیکھو، یہاں سلیمان سے بڑا ہے۔ \n43۔ جب ناپاک روح انسان سے نکل جاتی ہے، تو وہ خشک جگہوں سے گزرتا ہے، آرام تلاش کرتا ہے، اور کچھ نہیں پاتا۔ \n44۔ پھر وہ کہتا ہے، میں اپنے گھر میں واپس آؤں گا جہاں سے نکلا ہوں؛ اور جب وہ آئے گا، تو وہ اسے خالی، صاف اور سجا ہوا پاتا ہے۔ \n45۔ پھر وہ جاتا ہے، اور اپنے ساتھ سات اور بدکار روحیں لے جاتا ہے، اور وہ اندر آ کر وہاں بستی ہیں: اور اس آدمی کی آخری حالت پہلی سے بھی بدتر ہے۔ اسی طرح یہ بدکار نسل بھی ہوگی۔ \n46۔ جب وہ ابھی لوگوں سے بات کر رہا تھا، دیکھو، اس کی ماں اور اس کے بھائی باہر کھڑے تھے، اس سے بات کرنے کی خواہش میں۔ \n47۔ پھر ایک نے اس سے کہا، دیکھو، تمہاری ماں اور تمہارے بھائی باہر کھڑے ہیں، تم سے بات کرنے کے خواہشمند۔ \n48۔ لیکن اس نے جواب دیا اور اس سے کہا جس نے اسے بتایا، میری ماں کون ہے؟ اور میرے بھائی کون ہیں؟ \n49۔ اور اس نے اپنے شاگردوں کی طرف ہاتھ بڑھایا اور کہا، دیکھو میری ماں اور میرے بھائیو! \n50۔ جو بھی میرے باپ کی مرضی جو آسمان میں ہے، وہ میرے بھائی، بہن اور ماں کی مرضی کرے گا۔","1۔ اسی دن یسوع گھر سے باہر نکلا اور سمندر کے کنارے بیٹھ گیا۔ \n2۔ اور اس کے پاس بڑی تعداد جمع ہوئی، یہاں تک کہ وہ ایک جہاز میں بیٹھا اور بیٹھ گیا؛ اور پورا ہجوم ساحل پر کھڑا ہو گیا۔ \n3۔ اور اس نے انہیں تمثیلات میں بہت سی باتیں کہیں، کہا، دیکھو، ایک کبوتا بونے کے لیے باہر آیا؛ \n4۔ اور جب اس نے بویا تو کچھ {بیج} راستے کے کنارے گرے، اور پرندوں نے آ کر انہیں کھا لیا: \n5۔ کچھ پتھریلی جگہوں پر گر گئے، جہاں ان کے پاس زیادہ زمین نہیں تھی، اور فورا وہ اچھل گئے، کیونکہ ان کے پاس زمین کی گہرائی نہیں تھی: \n6۔ اور جب سورج نکلا، وہ جل گئے؛ اور چونکہ ان کی جڑ نہیں تھی، وہ مرجھا گئے۔ \n7۔ اور کچھ کانٹوں میں گر گئے؛ اور کانٹے پھوٹ پڑے اور انہیں گلا گھونٹ دیا: \n8۔ لیکن کچھ اچھی زمین میں گرے، اور کچھ نے پھل دیا، کچھ سو گنا، کچھ ساٹھ گنا، کچھ تیس گنا۔ \n9۔ جس کے پاس سننے کی آواز ہے، اسے سننے دو۔ \n10۔ اور شاگرد آئے اور اس سے کہا، تم ان سے تمثیلوں میں کیوں بات کر رہے ہو؟ \n11۔ اس نے جواب دیا اور ان سے کہا، کیونکہ تمہیں آسمان کی بادشاہی کے راز جاننے کے لیے دیا گیا ہے، لیکن یہ انہیں نہیں دیا گیا۔ \n12۔ جس کے پاس ہے، اسے دیا جائے گا، اور اسے زیادہ فراوانی ملے گی؛ لیکن جس کے پاس نہیں ہے، وہ اس سے بھی چھین لیا جائے گا جیسا کہ اس کے پاس ہے۔ \n13۔ لہٰذا میں ان سے تمثیلوں میں بات کرتا ہوں: کیونکہ وہ دیکھنے والے نہیں دیکھتے؛ اور سننے والے نہ سنتے ہیں، نہ سمجھتے ہیں۔ \n14۔ اور انہی میں یسعیاس کی پیش گوئی پوری ہوتی ہے، جو کہتی ہے، سن کر سنو گے، اور سمجھ نہیں پاؤ گے؛ اور دیکھو گے تو دیکھو گے، اور نہ دیکھو گے: \n15۔ کیونکہ اس قوم کا دل گندا ہے، اور ان کے کان سننے سے بے جان ہیں، اور ان کی آنکھیں بند ہیں؛ تاکہ وہ کبھی بھی اپنی آنکھوں سے دیکھ سکیں، کانوں سے سن سکیں، اور دل سے سمجھ سکیں، اور وہ تبدیل ہو جائیں، اور میں انہیں شفا دوں۔ \n16. لیکن تمہاری آنکھیں مبارک ہیں، کیونکہ وہ دیکھتی ہیں، اور تمہارے کان، کیونکہ وہ سنتے ہیں۔ \n17۔ کیونکہ میں واقعی تم سے کہتا ہوں، کہ بہت سے نبی اور نیک لوگ {وہی چیزیں} دیکھنے کی خواہش رکھتے ہیں {جو تم دیکھتے ہو} اور {ان} نہیں دیکھے؛ اور {وہ چیزیں} سننا چاہتے ہیں {جو تم سنتے ہو} اور نہیں سنے {ان}۔ \n18۔ لہٰذا بیج بونے والے کی تمثیل سنو۔ \n19۔ جب کوئی بادشاہی کا کلام سنتا ہے اور اسے نہیں سمجھتا، تو بدکار آتا ہے، اور اپنے دل میں بویا ہوا چیز پکڑ لیتا ہے۔ یہی وہ ہے جسے راستے سے بیج ملا۔ \n20۔ لیکن جس نے بیج کو پتھریلی جگہوں پر لیا، وہی ہے جو کلام سنتا ہے اور خوشی سے اسے قبول کرتا ہے؛ \n21۔ پھر بھی وہ اپنے اندر جڑ نہیں بناتا، بلکہ کچھ وقت کے لیے صبر کرتا ہے: کیونکہ جب کلام کی وجہ سے مصیبت یا ظلم آتا ہے، تو وہ آہستہ آہستہ ناراض ہوتا ہے۔ {ناراض: وہ دوبارہ لوٹتا ہے، یا، گناہ میں گر جاتا ہے}\n22۔ جو کانٹوں کے درمیان بیج حاصل کرتا ہے، وہی کلام سنتا ہے؛ اور اس دنیا کی دیکھ بھال اور دولت کی دھوکہ دہی سے کلام گلا گھونٹتا ہے، اور وہ بے ثمر ہو جاتا ہے۔ \n23. لیکن جس نے بیج کو اچھی زمین میں دیا وہی کلام سنتا ہے اور سمجھتا ہے؛ جو پھل بھی دیتا ہے، اور تقریبا سو، ساٹھ، تیس گنا پیدا کرتا ہے۔ \n24۔ ایک اور تمثیل اس نے ان کے سامنے سنائی، کہا، آسمان کی بادشاہی کو اس آدمی سے تشبیہ دی گئی ہے جس نے اپنے کھیت میں اچھا بیج بویا: \n25۔ لیکن جب لوگ سو رہے تھے، اس کا دشمن آیا اور گندم کے درمیان تار بوئے اور اپنے راستے پر چلا گیا۔ \n26. لیکن جب تلوار نکلی اور پھل نکالا، تو پھر تاریں بھی ظاہر ہوئیں۔ \n27۔ تو گھر والے کے خادم آئے اور اس سے کہا، جناب، کیا تم نے اپنے کھیت میں اچھا بیج نہیں بویا؟ تو پھر یہ کہاں سے نکلا؟ \n28۔ اس نے ان سے کہا، ایک دشمن نے یہ کیا ہے۔ خادموں نے اس سے کہا، کیا تم جا کر انہیں جمع کر سکتے ہو؟ \n29۔ لیکن اس نے کہا، نہیں؛ تاکہ جب تم ٹیر جمع کرو تو گندم بھی ان سے جڑ نہ نکالو۔ \n30۔ دونوں کو ایک ساتھ اگنے دو جب تک فصل نہ آئے: اور فصل کے وقت میں میں ریپرز سے کہوں گا، پہلے ٹیروں کو اکٹھا کرو، اور انہیں گٹھڑیوں میں باندھ کر جلا دو: لیکن گندم کو میرے کھیت میں جمع کرو۔ \n31۔ اس نے ان کے سامنے ایک اور تمثیل سنائی، کہا، آسمان کی بادشاہی سرسوں کے دانے کی مانند ہے، جسے ایک آدمی نے لے کر اپنے کھیت میں بویا: \n32۔ جو واقعی تمام بیجوں میں سب سے چھوٹا ہے: لیکن جب یہ اگایا جاتا ہے تو یہ جڑی بوٹیوں میں سب سے بڑا ہوتا ہے، اور ایک درخت بن جاتا ہے، یہاں تک کہ ہوا کے پرندے آ کر اس کی شاخوں میں ٹھہر جاتے ہیں۔ \n33۔ ایک اور تمثیل اس نے ان سے کہا؛ آسمان کی بادشاہی خمیر کی مانند ہے، جسے ایک عورت نے لیا اور تین کھانے میں چھپا دیا، یہاں تک کہ پورا کھانا خمیر ہو گیا۔ {پیمائشیں: یونانی میں لفظ ایک پیمانہ ہے جس میں تقریبا ڈیڑھ پیک ہوتا ہے، جس میں ایک پینٹ سے کچھ زیادہ کی ضرورت ہوتی ہے}\n34۔ یہ سب باتیں یسوع نے تمثیلوں میں ہجوم سے کہیں؛ اور بغیر تمثیل کے اس نے ان سے نہیں کہا: \n35۔ تاکہ وہ پورا ہو جو نبی نے کہا تھا، جس میں کہا گیا تھا، میں تمثیلات میں اپنا منہ کھولوں گا؛ میں وہ باتیں بیان کروں گا جو دنیا کی بنیاد سے چھپائی گئی ہیں۔ \n36۔ پھر یسوع نے ہجوم کو بھیج دیا، اور گھر میں چلے گئے، اور اس کے شاگرد اس کے پاس آئے اور کہا، \"ہمیں میدان کے تاروں کی تمثیل سناؤ۔ \n37۔ اس نے جواب دیا اور ان سے کہا، جو اچھا بیج پیدا کرتا ہے وہ انسان کا بیٹا ہے؛ \n38۔ کھیت دنیا ہے؛ اچھے بیج بادشاہی کے بچے ہیں؛ لیکن تارے بدکار {ایک} کے بچے ہیں؛ \n39۔ وہ دشمن جس نے انہیں بویا وہ شیطان ہے؛ فصل دنیا کا اختتام ہے؛ اور کاٹنے والے فرشتے ہیں۔ \n40۔ اسی طرح تاریں جمع کی جاتی ہیں اور آگ میں جلی جاتی ہیں؛ اسی طرح اس دنیا کے آخر میں بھی ایسا ہی ہوگا۔ \n41۔ انسان کا بیٹا اپنے فرشتے بھیجے گا، اور وہ اس کی بادشاہی سے وہ سب چیزیں جمع کریں گے جو گناہ اور بدکاری کرتی ہیں؛ {چیزیں...: یا، بدنامی}\n42۔ اور انہیں آگ کے بھٹے میں پھینک دوں: وہاں چیخ و پکار اور دانت پیسنے کی آواز ہوگی۔ \n43۔ پھر نیک اپنے باپ کی بادشاہی میں سورج کی طرح چمکیں گے۔ جس کے پاس سننے کے لیے کان ہیں، اسے سننے دے۔ \n44۔ پھر، آسمان کی بادشاہی ایسے ہے جیسے کسی کھیت میں چھپا ہوا خزانہ ہو؛ جب انسان اسے پاتا ہے تو چھپ جاتا ہے، اور خوشی کے لیے جاتا ہے اور جو کچھ بھی ہے بیچ دیتا ہے، اور وہ کھیت خریدتا ہے۔ \n45. پھر، آسمان کی بادشاہی ایک تاجر کی طرح ہے جو نیک موتی تلاش کر رہا ہو: \n46۔ جس نے جب ایک قیمتی موتی پایا، تو سب کچھ بیچ دیا اور خرید لیا۔ \n47۔ پھر، آسمان کی بادشاہی ایک جال کی مانند ہے جو سمندر میں پھینکا گیا اور ہر قسم کا جمع کیا گیا: \n48۔ جب پانی بھر گیا تو وہ ساحل پر پہنچے، بیٹھ گئے، اچھے سامان کو برتنوں میں جمع کر لیا، لیکن برے کو دور پھینک دیا۔ \n49۔ ایسا ہی ہوگا دنیا کے آخر میں: فرشتے باہر آئیں گے، اور بدکاروں کو راستوں میں سے کاٹ دیں گے، \n50۔ اور انہیں آگ کے بھٹے میں پھینک دوں: وہاں چیخ و پکار اور دانت پیسنے کی آواز ہوگی۔ \n51۔ یسوع ان سے کہتا ہے، کیا تم نے یہ سب باتیں سمجھ لی ہیں؟ وہ اس سے کہتے ہیں، ہاں، خداوند۔ \n52۔ پھر اس نے ان سے کہا، لہٰذا ہر کاتب جو آسمان کی بادشاہی کے لیے ہدایت یافتہ ہے، وہ ایک ایسے شخص کی طرح ہے جو اپنے خزانے سے نئی اور پرانی چیزیں نکالتا ہے۔ \n53۔ اور ایسا ہوا کہ جب یسوع نے یہ تمثیلیں مکمل کیں، تو وہ وہاں سے روانہ ہو گئے۔ \n54۔ اور جب وہ اپنے ملک میں آیا، تو اس نے انہیں ان کی عبادت گاہ میں تعلیم دی، یہاں تک کہ وہ حیران رہ گئے، اور کہا، یہ {انسان} یہ حکمت اور {یہ} عظیم اعمال کہاں سے آیا؟ \n55۔ کیا یہ بڑھئی کا بیٹا نہیں؟ کیا اس کی ماں کا نام مریم نہیں ہے؟ اور اس کے بھائی، یعقوب، یوسیس، اور شمعون اور یہودا؟ \n56۔ اور اس کی بہنیں، کیا وہ سب ہمارے ساتھ نہیں ہیں؟ تو پھر یہ {انسان} یہ سب چیزیں کہاں سے لے آیا؟ \n57۔ اور وہ اس میں ناراض ہوئے۔ لیکن یسوع نے ان سے کہا، نبی بے عزت نہیں ہوتا، سوائے اپنے ملک اور اپنے گھر کے۔ \n58۔ اور انہوں نے وہاں زیادہ عظیم کام نہیں کیے کیونکہ ان کا ایمان نہیں تھا۔","1۔ اس وقت ہیروڈ ٹیٹرارک نے یسوع کی شہرت کے بارے میں سنا، {ٹیٹرارک: یا، چار صوبوں کا گورنر}\n2۔ اور اپنے بندوں سے کہا، یہ یوحنا بپتسمہ دینے والا ہے؛ وہ مردوں میں سے زندہ ہوا ہے؛ اور اس لیے عظیم اعمال اس میں ظاہر ہوتے ہیں۔ {کیا...: یا، اس کے ذریعے کیے گئے ہیں}\n3۔ کیونکہ ہیرودیس نے یوحنا کو مضبوطی سے پکڑ لیا تھا، اسے باندھ دیا اور ہیرودیاس کی خاطر قید میں ڈال دیا، جو اس کے بھائی فلپ کی بیوی تھی۔ \n4۔ کیونکہ جان نے اس سے کہا، یہ جائز نہیں کہ تم اسے رکھو۔ \n5۔ اور جب وہ اسے قتل کرنا چاہتا تو وہ ہجوم سے ڈرتا کیونکہ وہ اسے نبی سمجھتے تھے۔ \n6۔ لیکن جب ہیرودیس کی سالگرہ منائی گئی، ہیرودیاس کی بیٹی ان کے سامنے رقص کرتی رہی اور ہیرودیس کو خوش کیا۔ {اس سے پہلے...: Gr. درمیان میں}\n7۔ جس پر اس نے وعدہ کیا کہ وہ اسے جو چاہے دے گا۔ \n8۔ اور اس نے، اپنی ماں کی ہدایت پر کہا، \"مجھے یہاں یوحنا بپٹسٹ کا سر چارجر میں دو۔ \n9۔ اور بادشاہ معذرت خواہ تھا: پھر بھی قسم کی خاطر، اور جو لوگ اس کے ساتھ گوشت پر بیٹھے تھے، اس نے حکم دیا کہ اسے دیا جائے۔ \n10۔ اور اس نے بھیجا، اور جیل میں جان کا سر قلم کر دیا۔ \n11۔ اور اس کا سر چارجر میں لایا گیا، اور دوشیزہ کو دے دیا گیا: اور اس نے اسے اپنی ماں کے پاس لے آیا۔ \n12۔ اور اس کے شاگرد آئے، جسم اٹھا کر دفن کیا، اور جا کر یسوع کو بتایا۔ \n13۔ جب یسوع نے یہ سنا، تو وہ وہاں سے کشتی کے ذریعے ایک صحرا کی طرف روانہ ہوا، اور جب لوگوں نے اس کی خبر سنی تو وہ پیدل اس کے پیچھے شہروں سے باہر نکل گئے۔ \n14۔ اور یسوع باہر نکلے، اور بہت سے لوگوں کو دیکھا، اور ان کے لیے رحم کیا، اور ان کے مریضوں کو شفا دی۔ \n15۔ اور جب شام ہو گئی، اس کے شاگرد اس کے پاس آئے اور کہا، یہ ایک ویران جگہ ہے، اور وقت گزر چکا ہے؛ ہجوم کو بھیج دو، تاکہ وہ دیہاتوں میں جا کر اپنے لیے خوراک خرید سکیں۔ \n16۔ لیکن یسوع نے ان سے کہا، انہیں جانے کی ضرورت نہیں؛ انہیں کھانے کے لیے دو۔ \n17۔ اور وہ اسے کہتے ہیں، ہمارے پاس یہاں صرف پانچ روٹیاں اور دو مچھلیاں ہیں۔ \n18۔ اس نے کہا، انہیں میرے پاس لے آؤ۔ \n19۔ اور اس نے ہجوم کو گھاس پر بیٹھنے کا حکم دیا، پانچ روٹیاں اور دو مچھلیاں لے گئیں، آسمان کی طرف دیکھتے ہوئے برکت دی، اور بریک کیا، اور روٹیاں اپنے شاگردوں کو اور شاگردوں کو دی۔ \n20۔ اور سب نے کھایا اور بھر گیا، اور جو ٹکڑے باقی تھے ان میں سے بارہ ٹوکریاں بھر گئیں۔ \n21۔ اور جو لوگ کھا چکے تھے وہ تقریبا پانچ ہزار مرد تھے، عورتوں اور بچوں کے علاوہ۔ \n22۔ اور فورا یسوع نے اپنے شاگردوں کو کشتی میں سوار ہونے اور اس کے سامنے دوسری طرف جانے پر مجبور کیا، جبکہ اس نے ہجوم کو بھیج دیا۔ \n23۔ اور جب اس نے ہجوم کو بھیج دیا، تو وہ ایک پہاڑ پر چلا گیا تاکہ دعا کرے: اور جب شام ہوئی تو وہ وہاں اکیلا تھا۔ \n24۔ لیکن جہاز اب سمندر کے بیچ میں تھا، لہروں سے ہل رہا تھا: کیونکہ ہوا مخالف تھی۔ \n25۔ اور رات کی چوتھی پہر میں یسوع ان کے پاس گئے، سمندر پر چلتے ہوئے۔ \n26۔ اور جب شاگردوں نے اسے سمندر پر چلتے دیکھا تو وہ پریشان ہوئے اور کہا، یہ ایک روح ہے؛ اور وہ خوف سے پکارے۔ \n27۔ لیکن فورا یسوع نے ان سے کہا، خوش رہو؛ یہ میں ہوں؛ ڈرو مت۔ \n28۔ اور پطرس نے جواب دیا اور کہا، اے خداوند، اگر تو ہے تو مجھے حکم دے کہ پانی پر تیرے پاس آؤں۔ \n29۔ اور اس نے کہا، آؤ۔ اور جب پطرس کشتی سے اترا تو وہ پانی پر چلا گیا، یسوع کے پاس جانے کے لیے۔ \n30۔ لیکن جب اس نے ہوا کو تیز دیکھا، تو وہ ڈر گیا؛ اور ڈوبنے لگا، اس نے پکارا، خداوند، مجھے بچا۔ {زوردار: یا، مضبوط}\n31۔ اور فورا یسوع نے اپنا ہاتھ بڑھایا، اسے پکڑ لیا اور کہا، اے کم ایمان والے، تم نے شک کیوں کیا؟ \n32۔ اور جب وہ جہاز میں آئے تو ہوا رک گئی۔ \n33۔ پھر جو جہاز میں تھے وہ آئے اور اس کی عبادت کی، کہنے لگے، سچائی سے تو خدا کا بیٹا ہے۔ \n34۔ اور جب وہ چلے گئے، تو وہ گنیساریت کی سرزمین میں آئے۔ \n35۔ اور جب اس جگہ کے لوگوں کو اس کے بارے میں علم ہوا، تو انہوں نے آس پاس کے تمام علاقوں میں بھیجا اور جو بیمار تھا اسے لے آئے؛ \n36۔ اور اس سے دعا کی کہ وہ صرف اس کے لباس کے کنارے کو چھوئیں: اور جتنے چھوئیں وہ مکمل طور پر صحت یاب ہو گئیں۔","1۔ پھر یسوع کے کاتب اور فریسی، جو یروشلم کے تھے، آئے اور کہا، \n2. تمہارے شاگرد بزرگوں کی روایت کی خلاف ورزی کیوں کرتے ہیں؟ کیونکہ وہ روٹی کھاتے وقت ہاتھ نہیں دھوتے۔ \n3۔ لیکن اس نے جواب دیا اور ان سے کہا، تم اپنی روایت کے مطابق خدا کے حکم کی خلاف ورزی کیوں کرتے ہو؟ \n4۔ کیونکہ خدا نے حکم دیا ہے، کہتا ہے، اپنے باپ اور ماں کی عزت کرو: اور جو باپ یا ماں کو لعنت دے، وہ موت کے وقت مر جائے۔ \n5۔ لیکن آپ کہتے ہیں، جو بھی اپنے والد یا ماں سے کہے، یہ ایک تحفہ ہے، جو بھی آپ کو میرے فائدے سے ملے؛ \n6۔ اور اپنے والد یا ماں کی عزت نہ کرو، {وہ آزاد ہو جائے گا}۔ یوں تم نے اپنی روایت سے خدا کے حکم کو بے اثر کر دیا۔ \n7۔ {تم منافقو}، اشیاس نے تمہاری پیشگوئی اچھی کی، کہہ کر، \n8۔ یہ لوگ اپنے منہ سے میرے قریب آتے ہیں، اور اپنے ہونٹوں سے مجھے عزت دیتے ہیں؛ لیکن ان کا دل مجھ سے دور ہے۔ \n9۔ لیکن وہ بے سود میری عبادت کرتے ہیں، کیونکہ عقائد انسانوں کے احکامات سکھاتے ہیں۔ \n10۔ اور اس نے ہجوم کو بلایا اور کہا، سنو اور سمجھو: \n11۔ جو منہ میں جاتا ہے وہ انسان کو ناپاک نہیں کرتا؛ بلکہ جو منہ سے نکلتا ہے، وہ انسان کو ناپاک کرتا ہے۔ \n12۔ پھر اس کے شاگرد آئے اور اس سے کہا، کیا تم جانتے ہو کہ فریسیوں نے یہ بات سن کر ناراض ہو گئے؟ \n13۔ لیکن اس نے جواب دیا اور کہا، ہر وہ پودا جو میرے آسمانی باپ نے نہیں لگایا، اسے جڑ سے اکھاڑ دیا جائے گا۔ \n14۔ انہیں چھوڑ دو: وہ اندھے لوگوں کے رہنما ہیں۔ اور اگر اندھے اندھوں کی رہنمائی کریں گے تو دونوں کھائی میں گر جائیں گے۔ \n15۔ پھر پطرس نے جواب دیا اور اسے کہا، یہ تمثیل ہمیں سناؤ۔ \n16۔ اور یسوع نے کہا، کیا تم بھی ابھی تک سمجھنے سے قاصر ہو؟ \n17۔ کیا تم ابھی تک نہیں سمجھتے کہ جو کچھ منہ سے اندر جاتا ہے وہ پیٹ میں جاتا ہے اور ہوا میں پھینک دیا جاتا ہے؟ \n18۔ لیکن جو چیزیں منہ سے نکلتی ہیں وہ دل سے نکلتی ہیں؛ اور وہ انسان کو ناپاک کرتی ہیں۔ \n19۔ کیونکہ دل سے برے خیالات، قتل،،، چوری، جھوٹا گواہی، کفر نکلتے ہیں: \n20۔ یہ وہ چیزیں ہیں جو انسان کو ناپاک کرتی ہیں: لیکن بغیر دھوئے ہاتھوں سے کھانا انسان کو ناپاک نہیں کرتا۔ \n21۔ پھر یسوع وہاں سے روانہ ہوا اور صور اور صیدا کے ساحلوں کی طرف روانہ ہوا۔ \n22۔ اور دیکھتے، کنعان کی ایک عورت انہی ساحلوں سے نکلی اور اس سے پکارا، اے خداوند، داؤد کے بیٹے مجھ پر رحم فرما؛ میری بیٹی شیطان سے شدید ناراض ہے۔ \n23۔ لیکن اس نے اس کا ایک لفظ بھی جواب نہ دیا۔ اور اس کے شاگرد آئے اور اس سے التجا کی، کہا، اسے بھیج دو؛ کیونکہ وہ ہمارے پیچھے پکار رہی ہے۔ \n24۔ لیکن اس نے جواب دیا اور کہا، میں صرف اسرائیل کے گھر کی گمشدہ بھیڑ کے پاس بھیجا گیا ہوں۔ \n25۔ پھر وہ آئی اور اس کی عبادت کی، کہا، خداوند، میری مدد فرما۔ \n26۔ لیکن اس نے جواب دیا اور کہا، بچوں کی روٹی لینا اور اسے کتوں پر پھینکنا مناسب نہیں۔ \n27۔ اور اس نے کہا، سچ، اے خداوند: پھر بھی کتے اپنے مالکان کی میز سے گرنے والے ٹکڑوں کو کھاتے ہیں۔ \n28۔ پھر یسوع نے جواب دیا اور اس سے کہا، اے عورت، تمہارا ایمان عظیم ہے: جیسا تم چاہو تمہارے لیے ہو۔ اور اس کی بیٹی اسی وقت سے صحت یاب ہو گئی۔ \n29۔ اور یسوع وہاں سے روانہ ہوا، اور جلیل کے سمندر کے قریب پہنچا؛ اور ایک پہاڑ پر چڑھ گیا، اور وہاں بیٹھ گیا۔ \n30۔ اور بڑی تعداد اس کے پاس آئے، جن کے ساتھ لنگڑے، اندھے، گونگے، معذور اور بہت سے دوسرے تھے، اور انہیں یسوع کے قدموں میں پھینک دیا؛ اور اس نے انہیں شفا دی: \n31۔ یہاں تک کہ جب لوگ گونگے کو بولنے، معذور کو مکمل ہونے کے لیے، لنگڑوں کو چلنے کے لیے، اور اندھے کو دیکھنے کے لیے دیکھتے تو حیران ہوتے: اور انہوں نے اسرائیل کے خدا کی شان دی۔ \n32۔ پھر یسوع نے اپنے شاگردوں کو بلایا اور کہا، میں ہجوم پر رحم کرتا ہوں، کیونکہ وہ تین دن سے میرے ساتھ ہیں، اور کھانے کو کچھ نہیں: اور میں انہیں روزہ رکھ کر نہیں بھیجوں گا، ورنہ وہ راستے میں بے ہوش ہو جائیں گے۔ \n33۔ اور اس کے شاگرد اس سے کہتے ہیں، بیابان میں اتنی روٹی کہاں سے ملے کہ اتنی بڑی تعداد بھر سکے؟ \n34۔ اور یسوع نے ان سے کہا، تمہارے پاس کتنی روٹیاں ہیں؟ انہوں نے کہا، سات اور چند چھوٹی مچھلیاں۔ \n35۔ اور اس نے ہجوم کو زمین پر بیٹھنے کا حکم دیا۔ \n36۔ اور اس نے سات روٹیاں اور مچھلیاں لیں، شکر ادا کیا، اور ان کو توڑا، اور اپنے شاگردوں کو دیا، اور شاگردوں کو بھی۔ \n37۔ اور سب نے کھایا اور پیٹ بھر گیا، اور سات ٹوکریوں میں سے ٹوٹا ہوا گوشت اٹھایا۔ \n38۔ اور جو کھاتے تھے وہ چار ہزار مرد تھے، عورتوں اور بچوں کے علاوہ۔ \n39۔ اور اس نے ہجوم کو بھیج دیا، جہاز پر سوار ہو کر مگدالا کے ساحلوں پر پہنچا۔","1۔ فریسی بھی صدوقیوں کے ساتھ آئے، اور انہیں آزمایا کہ وہ انہیں آسمان سے کوئی نشان دکھائیں۔ \n2۔ اس نے جواب دیا اور ان سے کہا، جب شام ہو جائے تو تم کہتے ہو، {موسم اچھا ہوگا}، کیونکہ آسمان سرخ ہے۔ \n3۔ اور صبح، {آج بھی} خراب موسم ہوگا: کیونکہ آسمان سرخ اور نیچا ہے۔ اے منافقو، تم آسمان کا چہرہ دیکھ سکتے ہو؛ لیکن کیا تم وقت کے آثار نہیں دیکھ سکتے؟ \n4۔ ایک بدکار اور کرنے والی نسل کسی نشانی کی تلاش میں ہے؛ اور اسے کوئی نشانی نہیں ملے گی، سوائے نبی یونس کی نشانی کے۔ اور وہ انہیں چھوڑ کر چلا گیا۔ \n5۔ اور جب اس کے شاگرد دوسری طرف آئے، تو وہ روٹی لینا بھول گئے تھے۔ \n6۔ پھر یسوع نے ان سے کہا، فریسیوں اور صدوقیوں کے خمیر سے ہوشیار رہو۔ \n7۔ اور انہوں نے آپس میں بحث کی، کہہ رہے تھے، {یہ اس لیے ہے} کہ ہم نے روٹی نہیں لی۔ \n8. {کون} جب یسوع نے دیکھا، تو انہوں نے ان سے کہا، اے کم ایمان والے، تم لوگ آپس میں کیوں سوچتے ہو، کیونکہ تم نے روٹی نہیں لائی؟ \n9۔ کیا تم ابھی تک نہیں سمجھتے، نہ ہی پانچ ہزار کی پانچ روٹیوں کو یاد رکھتے ہو، اور کتنی ٹوکریاں تم نے اٹھائیں؟ \n10۔ نہ چار ہزار کی سات روٹیاں، اور کتنی ٹوکریاں تم نے اٹھائیں؟ \n11۔ تم کیسے نہیں سمجھتے کہ میں نے تم سے روٹی کے بارے میں بات نہیں کی، تاکہ تم فریسیوں اور صدوقیوں کے خمیر سے ہوشیار ہو؟ \n12۔ پھر انہوں نے سمجھا کہ اس نے کہا کہ وہ روٹی کے خمیر سے نہ ہوشیار رہیں، بلکہ فریسیوں اور صدوقیوں کے عقیدے سے خبردار رہیں۔ \n13۔ جب یسوع قیصریہ فلپی کے ساحلوں پر پہنچے، تو انہوں نے اپنے شاگردوں سے پوچھا، لوگ کہتے ہیں کہ میں انسان کا بیٹا کون ہوں؟ \n14۔ اور انہوں نے کہا، کچھ لوگ کہتے ہیں کہ تم یوحنا بپتسمہ دینے والے ہو: کچھ ایلیاس؛ اور کچھ یرمیا یا نبیوں میں سے ایک۔ \n15۔ وہ ان سے کہتا ہے، لیکن تم کون کہتے ہو کہ میں کون ہوں؟ \n16۔ اور شمعون پطرس نے جواب دیا اور کہا، تو مسیح ہو، زندہ خدا کا بیٹا۔ \n17۔ اور یسوع نے جواب دیا اور کہا، تو مبارک ہو، شمعون بارجونا، کیونکہ گوشت اور خون نے تمہیں نہیں بلکہ میرے باپ کو ظاہر کیا ہے جو آسمان میں ہے۔ \n18. اور میں تم سے یہ بھی کہتا ہوں، کہ تم پیٹر ہو، اور میں اس چٹان پر اپنی کلیسا بناؤں گا؛ اور جہنم کے دروازے اس پر غالب نہیں آ سکیں گے۔ {پیٹر: یہ نام پتھر کی علامت ہے}\n19۔ اور میں تمہیں آسمان کی بادشاہی کی چابیاں دوں گا: اور جو کچھ تم زمین پر باندھو گے وہ آسمان میں باندھا جائے گا، اور جو کچھ تم زمین پر چھوڑو گے وہ آسمان میں آزاد ہوگا۔ \n20۔ پھر اس نے اپنے شاگردوں کو حکم دیا کہ وہ کسی کو نہ بتائیں کہ وہ یسوع مسیح ہے۔ \n21۔ اس وقت سے یسوع نے اپنے شاگردوں کو دکھایا کہ اسے یروشلم جانا چاہیے، بزرگوں، سردار کاہنوں اور کاتبوں سے بہت کچھ برداشت کرنا ہے، قتل ہونا ہے، اور تیسرے دن دوبارہ زندہ ہونا چاہیے۔ \n22۔ پھر پطرس نے اسے پکڑ لیا اور اسے ڈانٹنا شروع کیا، کہا، اے خداوند، یہ تجھ سے دور ہو، یہ تمہارے لیے نہیں ہوگا۔ {بنو...: اپنے آپ پر رحم کرو}\n23۔ لیکن وہ پلٹا اور پطرس سے کہا، شیطان، میرے پیچھے ہٹ جاؤ: تم میرے لیے گناہ ہو، کیونکہ تم خدا کی چیزوں کو نہیں بلکہ انسانوں کی چیزوں سے لطف اندوز ہوتے ہو۔ \n24۔ پھر یسوع نے اپنے شاگردوں سے کہا، اگر کوئی {انسان} میرے پیچھے آئے گا، تو وہ خود کو انکار کرے، اپنی صلیب اٹھا کر میری پیروی کرے۔ \n25۔ جو اپنی جان بچائے گا وہ اسے کھو دے گا: اور جو میری خاطر اپنی جان دے گا وہ اسے پائے گا۔ \n26۔ کیونکہ انسان کو کیا فائدہ ہے اگر وہ پوری دنیا حاصل کرے اور اپنی جان کھو دے؟ یا انسان اپنی جان کے بدلے کیا دے گا؟ \n27۔ کیونکہ انسان کا بیٹا اپنے باپ کی شان میں اپنے فرشتوں کے ساتھ آئے گا؛ اور پھر وہ ہر انسان کو اس کے اعمال کے مطابق انعام دے گا۔ \n28۔ یقینا میں تم سے کہتا ہوں، یہاں کچھ لوگ کھڑے ہیں جو موت کا ذائقہ نہیں چکھیں گے، جب تک کہ وہ انسان کے بیٹے کو اپنی بادشاہی میں آتے ہوئے نہ دیکھیں۔","1۔ اور چھ دن بعد یسوع پیٹر، یعقوب اور یوحنا کو اپنے بھائی لے کر ایک بلند پہاڑ پر لے جاتا ہے، \n2۔ اور ان کے سامنے تبدیل ہو گیا: اور اس کا چہرہ سورج کی طرح چمک رہا تھا، اور اس کا لباس روشنی کی طرح سفید تھا۔ \n3۔ اور دیکھو، ان کے سامنے موسیٰ اور ایلیاس اس سے بات کر رہے تھے۔ \n4۔ پھر پطرس نے جواب دیا اور یسوع سے کہا، اے خداوند، ہمارے لیے یہاں ہونا اچھا ہے: اگر تم چاہو تو یہاں تین خیمے بنا دیں؛ ایک تیرے لیے، ایک موسیٰ کے لیے، اور ایک ایلیاس کے لیے۔ \n5۔ جب وہ ابھی بول رہا تھا، دیکھو، ایک روشن بادل ان پر چھا گیا: اور دیکھو بادل سے ایک آواز آئی، جس نے کہا، یہ میرا محبوب بیٹا ہے، جس سے میں خوش ہوں؛ اسے سنو۔ \n6۔ اور جب شاگردوں نے سنا تو وہ منہ کے بل گر گئے اور خوفزدہ ہو گئے۔ \n7۔ اور یسوع آیا اور انہیں چھوا اور کہا، اٹھو اور ڈرو مت۔ \n8۔ اور جب انہوں نے اپنی آنکھیں اٹھائیں تو انہوں نے صرف یسوع کے سوا کوئی انسان نہیں دیکھا۔ \n9۔ اور جب وہ پہاڑ سے نیچے آئے، یسوع نے انہیں حکم دیا، کہنے لگا، کسی کو یہ خواب نہ سناؤ، جب تک کہ انسان کا بیٹا مردوں میں سے دوبارہ زندہ نہ ہو جائے۔ \n10۔ اور اس کے شاگردوں نے اس سے پوچھا، پھر کاتب کیوں کہتے ہیں کہ ایلیاس کو پہلے آنا چاہیے؟ \n11۔ اور یسوع نے جواب دیا اور ان سے کہا، ایلیاس واقعی سب سے پہلے آئے گا، اور سب کچھ بحال کرے گا۔ \n12۔ لیکن میں تم سے کہتا ہوں، کہ ایلیاس پہلے آ چکا ہے، اور وہ اسے نہیں جانتے تھے، بلکہ اس کے ساتھ جو چاہا کیا ہے۔ اسی طرح بیٹا انسان بھی ان سے تکلیف اٹھائے گا۔ \n13۔ پھر شاگردوں نے سمجھا کہ اس نے ان سے یوحنا بپتسمہ دینے والے کے بارے میں بات کی۔ \n14۔ اور جب وہ ہجوم کے پاس پہنچے، تو ایک {یقینی} آدمی آیا، اس کے سامنے گھٹنے ٹیک کر کہا، \n15۔ اے خداوند، میرے بیٹے پر رحم فرما: کیونکہ وہ پاگل اور پریشان ہے، کیونکہ اکثر وہ آگ میں گرتا ہے، اور اکثر پانی میں۔ \n16۔ اور میں اسے تمہارے شاگردوں کے پاس لے آیا، اور وہ اسے شفا نہ دے سکے۔ \n17۔ پھر یسوع نے جواب دیا اور کہا، اے بے ایمان اور گمراہ نسل، میں تمہارے ساتھ کب تک رہوں گا؟ میں تمہیں کب تک برداشت کروں گا؟ اسے میرے پاس لے آؤ۔ \n18۔ اور یسوع نے شیطان کو ڈانٹا؛ اور وہ اس سے نکل گیا: اور بچہ اسی وقت سے شفا پا گیا۔ \n19۔ پھر شاگرد یسوع کے پاس آئے اور کہا، ہم اسے کیوں نکال نہیں سکے؟ \n20۔ اور یسوع نے ان سے کہا، تمہارے کفر کی وجہ سے: کیونکہ میں تم سے کہتا ہوں، اگر تم سرسوں کے دانے کی طرح ایمان رکھتے ہو، تو تم اس پہاڑ سے کہو گے، یہاں سے اس جگہ چلے جاؤ؛ اور یہ ہٹا دے گا؛ اور تم پر کچھ بھی ناممکن نہیں ہوگا۔ \n21. تاہم یہ لوگ باہر نہیں جاتے بلکہ دعا اور روزے سے جاتے ہیں۔ \n22۔ اور جب وہ گلیل میں مقیم تھے، یسوع نے ان سے کہا، انسان کا بیٹا انسانوں کے ہاتھوں میں دھوکہ دیا جائے گا: \n23۔ اور وہ اسے مار ڈالیں گے، اور تیسرے دن اسے دوبارہ زندہ کیا جائے گا۔ اور وہ بہت افسردہ تھے۔ \n24۔ اور جب وہ کفرناحوم پہنچے، تو جو خراج وصول کرتے تھے {پیسہ} پیٹر کے پاس آئے اور کہا، کیا تمہارا آقا خراج نہیں دیتا؟ {خراجی: اصل میں دیدرخما کہا جاتا ہے، جس کی قیمت پندرہ پینس سٹرلنگ ہے؛ تقریبا سینتیس سینٹ}\n25۔ وہ کہتا ہے، ہاں۔ اور جب وہ گھر میں آیا، یسوع نے اسے روکا، کہا، تم کیا سوچتے ہو، شمعون؟ زمین کے بادشاہ کس کے بارے میں رسم یا خراج لیتے ہیں؟ اپنے بچوں کی، یا اجنبیوں کی؟ \n26۔ پطرس نے اسے کہا، اجنبیوں کے بارے میں۔ یسوع نے اسے کہا، تو بچے آزاد ہو جائیں۔ \n27۔ اس کے باوجود، کہیں ہم انہیں ناراض نہ کریں، تم سمندر میں جاؤ، کانٹا مارو، اور جو مچھلی پہلے نکلی ہے اسے اٹھاؤ؛ اور جب تم اس کا منہ کھولو، تو تمہیں ایک پیسہ ملے گا: جو لے لو، اور میرے اور تمہارے لیے دے دو۔ {ایک ٹکڑا...: یا، ایک اسٹیٹر: یہ آدھا اونس چاندی ہے، قیمت دو شلنگ اور چھ پنس، سٹرلنگ؛ تقریبا پچپن سینٹ}","1۔ اسی وقت شاگرد یسوع کے پاس آئے اور کہا، آسمان کی بادشاہی میں سب سے بڑا کون ہے؟ \n2۔ اور یسوع نے ایک چھوٹے بچے کو اپنے پاس بلایا، اور اسے ان کے درمیان رکھ دیا، \n3۔ اور کہا، \"یقینا میں تم سے کہتا ہوں، جب تک تم تبدیل نہ ہو جاؤ اور چھوٹے بچے نہ بن جاؤ، تم آسمان کی بادشاہی میں داخل نہیں ہو سکتے۔ \n4۔ جو بھی اس چھوٹے بچے کی طرح خود کو عاجز کرے، وہ آسمان کی بادشاہی میں سب سے بڑا ہے۔ \n5۔ اور جو بھی میرے نام پر ایسا ایک چھوٹا بچہ حاصل کرے گا، وہ مجھے قبول کرے گا۔ \n6۔ لیکن جو بھی ان چھوٹے بچوں میں سے کسی کو ناراض کرے جو مجھ پر ایمان رکھتے ہیں، اس کے لیے بہتر ہے کہ اس کی گردن میں ایک چکی کا پتھر لٹکا دیا جائے، اور وہ سمندر کی گہرائی میں ڈوب جائے۔ \n7۔ دنیا پر گناہوں کی افسوس! کیونکہ یہ ضروری ہے کہ گناہ آئے؛ لیکن افسوس اس آدمی پر جس کے ذریعے یہ گناہ آتا ہے! \n8۔ اس لیے اگر تمہارا ہاتھ یا پاؤں تمہیں تکلیف دے، تو انہیں کاٹ دو، اور تم سے پھینک دو: تمہارے لیے بہتر ہے کہ تم زندگی میں رکے یا زخمی ہو جاؤ، بجائے اس کے کہ دو ہاتھ یا دو پاؤں ہمیشہ کی آگ میں پھینک دو۔ \n9۔ اور اگر آپ کی آنکھ آپ کو تکلیف پہنچے، تو اسے نکال کر خود سے نکال دیں: آپ کے لیے بہتر ہے کہ آپ ایک آنکھ کے ساتھ زندگی میں جائیں، بجائے اس کے کہ آپ کی آنکھ جہنم کی آگ میں پھینک دے۔ \n10۔ دھیان رکھو کہ تم ان چھوٹے بچوں میں سے کسی کو حقیر نہ سمجھو؛ کیونکہ میں تم سے کہتا ہوں، کہ آسمان میں ان کے فرشتے ہمیشہ میرے باپ کے چہرے کو دیکھتے ہیں جو آسمان میں ہے۔ \n11۔ کیونکہ انسان کا بیٹا آیا ہے تاکہ وہ جو کھو گیا تھا اسے بچانے کے لیے آیا۔ \n12۔ تم کیا سوچتے ہو؟ اگر ایک آدمی کے پاس سو بھیڑیں ہوں اور ان میں سے ایک گمراہ ہو جائے، تو کیا وہ نوے اور نو کو چھوڑ کر پہاڑوں میں نہیں جاتا اور گمراہ شدہ چیز تلاش کرتا ہے؟ \n13۔ اور اگر وہ اسے پا لے، تو میں تم سے کہتا ہوں، وہ اس {بھیڑ} سے زیادہ خوش ہے، ان نوے نو لوگوں سے جو گمراہ نہیں ہوئے۔ \n14. اسی طرح، یہ آپ کے باپ کی مرضی نہیں ہے جو آسمان میں ہے کہ ان چھوٹے بچوں میں سے کوئی ہلاک ہو جائے۔ \n15۔ مزید یہ کہ اگر تمہارا بھائی تمہارے خلاف غلطی کرے تو جا کر اسے اپنی غلطی بتا دینا، اگر وہ تمہاری بات سنتا ہے تو تم نے اپنے بھائی کو حاصل کر لیا ہے۔ \n16۔ لیکن اگر وہ آپ کی بات نہ سنے، تو ایک یا دو اور ساتھ لے جانا، تاکہ دو یا تین گواہوں کے منہ میں ہر لفظ ثابت ہو سکے۔ \n17۔ اور اگر وہ انہیں سننے میں غفلت کرے تو کلیسیا کو بتانا: لیکن اگر وہ چرچ کو سننا بھول جائے تو وہ تمہارے لیے ایک کافر اور پبلکن کی طرح ہو۔ \n18۔ یقینا میں تم سے کہتا ہوں، جو کچھ تم زمین پر باندھو گے وہ آسمان میں بندھا ہوگا، اور جو کچھ تم زمین پر چھوڑو گے وہ آسمان میں آزاد ہوگا۔ \n19۔ پھر میں تم سے کہتا ہوں، کہ اگر تم میں سے دو زمین پر اس بات پر متفق ہو جائیں کہ وہ کسی بھی چیز سے متعلق ہوں، تو وہ میرے آسمانی باپ کی طرف سے ان کے لیے کیا جائے گا۔ \n20۔ جہاں دو یا تین میرے نام پر جمع ہیں، وہاں میں ان کے درمیان ہوں۔ \n21۔ پھر پطرس اس کے پاس آیا اور کہا، اے خداوند، میرا بھائی کتنی بار میرے خلاف گناہ کرے گا، اور میں اسے معاف کر دوں؟ سات بار تک؟ \n22۔ یسوع اس سے کہتا ہے، میں تم سے سات بار تک نہیں کہتا، بلکہ ستر بار سات بار۔ \n23۔ لہٰذا آسمان کی بادشاہی کو ایک خاص بادشاہ سے تشبیہ دی جاتی ہے، جو اپنے بندوں کا حساب رکھتا ہے۔ \n24۔ اور جب اس نے حساب لگانا شروع کیا، تو ایک اس کے پاس لایا گیا، جو اس کا دس ہزار ٹیلنٹ واجب الادا تھا۔ {ٹیلنٹ: ایک ٹیلنٹ سات سو پچاس اونس چاندی ہے، جو پانچ شلنگ کے بعد ایک اونس پاؤنڈ شلنگ بنتا ہے}\n25۔ لیکن چونکہ اسے ادائیگی نہیں کرنی تھی، اس کے سردار نے حکم دیا کہ اسے بیچ دیا جائے، اس کی بیوی اور بچے اور جو کچھ اس کے پاس ہے، اور ادائیگی کی جائے۔ \n26۔ خادم گر پڑا، اور اس کی عبادت کی، کہا، اے خداوند، میرے ساتھ صبر کرو، اور میں تمہیں سب کچھ ادا کروں گا۔ {اس کی عبادت کی: یا، اس سے دعا کی}\n27۔ پھر اس خادم کے مالک پر رحم ہوا، اسے آزاد کر دیا اور قرض معاف کر دیا۔ \n28۔ لیکن وہی خادم باہر گیا، اور اپنے ایک ساتھی خادم کو پایا، جس پر اس پر سو پینس واجب الادا تھا، اور اس نے اس پر ہاتھ رکھا اور اس کا گلا پکڑ کر کہا، \"جو تم پر واجب الادا ہے وہ مجھے دو۔ {پینس: رومن پینی ایک اونس کا آٹھواں حصہ ہے، جو پانچ شلنگ کے بعد اونس سات پینس آدھا پینی بنتا ہے؛ تقریبا چودہ سینٹ}\n29۔ اور اس کا ساتھی اس کے قدموں میں گر پڑا اور اس سے درخواست کی، کہنے لگا: میرے ساتھ صبر کرو، میں تمہیں سب کچھ ادا کروں گا۔ \n30۔ اور وہ نہیں چاہتا تھا: بلکہ جا کر اسے قید میں ڈال دیا، جب تک کہ وہ قرض ادا نہ کر دے۔ \n31۔ تو جب اس کے ساتھی خادم نے دیکھا کہ کیا ہوا ہے، تو وہ بہت پچھتائے اور آ کر اپنے رب کو سب کچھ بتایا۔ \n32۔ پھر اس کے آقا، جب اس نے اسے بلایا، اس سے کہا، اے بدکار بندہ، میں نے تمہارا سارا قرض معاف کر دیا، کیونکہ تم نے مجھے چاہا: \n33۔ کیا تمہیں اپنے ساتھی خادم پر بھی رحم نہیں کرنا چاہیے تھا، جیسا کہ میں نے تم پر ہمدردی کی؟ \n34۔ اور اس کا سردار غصے میں آ گیا، اور اسے ستانے والوں کے حوالے کر دیا، جب تک کہ وہ اپنی تمام ذمہ داریاں ادا نہ کر دے۔ \n35. اسی طرح میرا آسمانی باپ بھی تمہارے ساتھ کرے گا، اگر تم اپنے دل سے ہر ایک کو اس کے بھائی کے گناہوں کو معاف نہ کرو۔","1۔ اور ایسا ہوا کہ جب یسوع نے یہ اقوال مکمل کیے، تو وہ گلیل سے روانہ ہو کر یردن کے پار یہودیہ کے ساحلوں پر پہنچے؛ \n2۔ اور بڑی تعداد اس کے پیچھے گئی؛ اور اس نے وہاں انہیں شفا دی۔ \n3۔ فریسی بھی اس کے پاس آئے، اسے آزمایا اور کہا، کیا مرد کے لیے جائز ہے کہ وہ اپنی بیوی کو ہر وجہ سے قربان کرے؟ \n4۔ اور اس نے جواب دیا اور ان سے کہا، کیا تم نے نہیں پڑھا کہ جس نے شروع میں انہیں بنایا اس نے انہیں مرد اور عورت بنایا، \n5۔ اور کہا، اسی وجہ سے آدمی باپ اور ماں کو چھوڑ کر اپنی بیوی سے چمٹے گا: اور دونوں ایک جسم ہوں گے؟ \n6۔ اسی لیے وہ دو نہیں، بلکہ ایک جسم ہیں۔ لہٰذا خدا نے جو کچھ جوڑا ہے، اسے انسان جدا نہ کرے۔ \n7۔ وہ اس سے کہتے ہیں، پھر موسیٰ نے طلاق کا حکم کیوں دیا اور اسے قید کر دیا؟ \n8۔ وہ ان سے کہتا ہے، موسیٰ نے تمہارے دل کی سختی کی وجہ سے تمہیں اپنی بیویوں کو دور کرنے کی اجازت دی: لیکن شروع سے ایسا نہیں تھا۔ \n9۔ اور میں تم سے کہتا ہوں، جو اپنی بیوی کو کے علاوہ چھوڑ دے اور کسی اور سے شادی کرے، وہ کرتا ہے: اور جو اس عورت سے شادی کرتا ہے جو ختم ہو گئی ہے وہ کرتا ہے۔ \n10۔ اس کے شاگرد اس سے کہتے ہیں، اگر مرد کی حالت اس کی بیوی کے ساتھ ہو تو شادی کرنا ٹھیک نہیں۔ \n11۔ لیکن اس نے ان سے کہا، تمام {انسان} اس قول کو قبول نہیں کر سکتے، سوائے {انے} کے جو اسے دیا گیا ہو۔ \n12. کیونکہ کچھ خواجہ سرا ایسے ہیں جو اپنی ماں کے پیٹ سے پیدا ہوئے تھے؛ اور کچھ خواجہ سرا ایسے ہیں جو انسانوں کے خواجہ سرا بنائے گئے؛ اور کچھ خواجہ سرا بھی ہیں، جنہوں نے خود کو آسمان کی بادشاہی کے لیے خصی بنا لیا ہے۔ جو اسے قبول کر سکتا ہے، وہ اسے قبول کرے۔ \n13۔ پھر اس کے پاس چھوٹے بچے لائے گئے تاکہ وہ ان پر ہاتھ رکھے اور دعا کرے: اور شاگردوں نے انہیں ڈانٹا۔ \n14۔ لیکن یسوع نے کہا، چھوٹے بچوں کو اجازت دو، اور انہیں میرے پاس آنے سے منع نہ کرو، کیونکہ آسمان کی بادشاہی انہی کی ہے۔ \n15۔ اور اس نے ان پر ہاتھ رکھے اور وہاں سے روانہ ہو گیا۔ \n16۔ اور دیکھو، ایک آیا اور اس سے کہا، اے اچھے مالک، میں کیا اچھا کام کروں تاکہ مجھے ہمیشہ کی زندگی مل سکے؟ \n17۔ اور اس نے اس سے کہا، تم مجھے اچھا کیوں کہتے ہو؟ {کوئی بھلا نہیں} صرف ایک ہے، {یعنی} خدا، لیکن اگر تم زندگی میں داخل ہونا چاہتے ہو تو احکامات کی پاسداری کرو۔ \n18۔ وہ اس سے کہتا ہے، کون سا؟ یسوع نے کہا، تم قتل نہیں کرو گے، نہیں کرو گے، چوری نہیں کرو گے، جھوٹی گواہی نہیں دے گا، \n19۔ اپنے والد اور ماں کی عزت کرو: اور اپنے پڑوسی سے ویسا ہی محبت کرو جیسے تم خود کرو۔ \n20۔ نوجوان نے اس سے کہا، یہ سب چیزیں میں نے اپنی جوانی سے سنبھال کر رکھی ہیں: ابھی کیا کمی ہے؟ \n21۔ یسوع نے اس سے کہا، اگر تم کامل ہونا چاہتے ہو، تو جاؤ {اور} جو تمہارے پاس ہے اسے بیچ دو، اور غریبوں کو دے دو، اور تمہارے پاس آسمان میں خزانہ ہوگا، اور آؤ {اور} میرے پیچھے آؤ۔ \n22۔ لیکن جب نوجوان نے یہ کہاوت سنی، تو وہ غمگین ہو کر چلا گیا، کیونکہ اس کے پاس بہت زیادہ دولت تھی۔ \n23۔ پھر یسوع نے اپنے شاگردوں سے کہا، \"یقینا میں تم سے کہتا ہوں، کہ ایک امیر آدمی آسمان کی بادشاہی میں بمشکل داخل ہو سکتا ہے۔ \n24۔ اور پھر میں تم سے کہتا ہوں، اونٹ کے لیے سوئی کے سوراخ سے گزرنا آسان ہے بہ نسبت امیر آدمی کے خدا کی بادشاہی میں داخل ہونے کے۔ \n25۔ جب اس کے شاگردوں نے یہ سنا تو وہ بہت حیران رہ گئے اور کہا، پھر کون نجات پا سکتا ہے؟ \n26۔ لیکن یسوع نے انہیں دیکھا اور انہیں کہا، انسانوں کے ساتھ یہ ناممکن ہے؛ لیکن خدا کے ساتھ سب کچھ ممکن ہے۔ \n27۔ پھر پطرس نے جواب دیا اور کہا، دیکھو، ہم سب کو چھوڑ کر تیرے پیچھے چلے گئے؛ تو پھر ہمیں کیا ملے گا؟ \n28۔ اور یسوع نے ان سے کہا، \"یقینا میں تم سے کہتا ہوں، کہ تم جو میرے پیچھے آئے، جب انسان کا بیٹا اپنی عظمت کے تخت پر بیٹھے گا، تم بھی بارہ تختوں پر بیٹھو گے، اور اسرائیل کے بارہ قبائل کا فیصلہ کرو گے۔ \n29۔ اور ہر وہ شخص جو میرے نام کے لیے گھر، بھائی، بہن، باپ، ماں، بیوی، بچے یا زمینیں چھوڑ چکا ہے، اسے سو گنا ملے گا اور وہ دائمی زندگی کا وارث ہوگا۔ \n30۔ لیکن بہت سے {جو پہلے ہیں} آخر میں ہوں گے؛ اور آخری {سب سے پہلے} ہوں گے۔","1۔ کیونکہ آسمان کی بادشاہی ایسے انسان کی مانند ہے جو ایک گھر کا مالک ہے، جو صبح سویرے اپنے انگور کے باغ میں مزدور کرائے پر لینے نکلتا ہے۔ \n2۔ اور جب اس نے مزدوروں سے روزانہ ایک پینی کے لیے اتفاق کیا، تو اس نے انہیں اپنے انگور کے باغ میں بھیج دیا۔ {پینی: رومن پینی ایک اونس کا آٹھواں حصہ ہے، جو پانچ شلنگ کے بعد سات پینس آدھا پینی بنتا ہے؛ تقریبا چودہ سینٹ}\n3۔ اور وہ تقریبا تیسرے گھنٹے باہر گیا، اور بازار میں دوسروں کو بے کار کھڑے دیکھا، \n4۔ اور انہوں نے ان سے کہا؛ تم بھی انگور کے باغ میں جاؤ، اور جو کچھ درست ہے میں تمہیں دوں گا۔ اور وہ اپنے راستے پر چلے گئے۔ \n5. پھر وہ چھٹے اور نویں گھنٹے کے قریب باہر گیا، اور اسی طرح کیا۔ \n6۔ اور تقریبا گیارہویں گھنٹے میں وہ باہر گیا، اور دوسرے لوگ بے کار کھڑے دیکھے، اور ان سے کہا، تم سارا دن یہاں کیوں کھڑے ہو؟ \n7۔ وہ اس سے کہتے ہیں، کیونکہ کسی نے ہمیں ملازمت پر نہیں رکھا۔ وہ انہیں کہتا ہے، تم بھی انگور کے باغ میں جاؤ؛ اور جو صحیح ہے، وہ تمہیں ملے گا۔ \n8۔ تو جب ایون آ گیا، تو باغ کے مالک نے اپنے سرپرست سے کہا، مزدوروں کو بلاؤ اور انہیں اجرت دو، آخری سے لے کر پہلے تک۔ \n9۔ اور جب وہ آخری لمحے میں آئے جو {نوکری} کیے گئے، تو انہیں ہر آدمی کو ایک پیسہ ملا۔ \n10۔ لیکن جب پہلا آیا، تو انہوں نے سمجھا کہ انہیں زیادہ ملنا چاہیے تھا؛ اور اسی طرح ہر آدمی کو ایک پیسہ ملتا تھا۔ \n11۔ اور جب انہوں نے اسے وصول کیا، تو انہوں نے گھر کے نیک آدمی کے خلاف سرگوشی کی، \n12۔ کہتا ہے، یہ آخری {سو} ایک گھنٹہ گزارے ہیں، اور تم نے انہیں ہمارے برابر کر دیا، جنہوں نے دن کا بوجھ اور گرمی برداشت کی۔ {کیا ہے...: یا، صرف ایک گھنٹہ جاری رہا}\n13۔ لیکن اس نے ان میں سے ایک کو جواب دیا اور کہا، دوست، میں تمہیں کوئی نقصان نہیں کرتا: کیا تم نے میرے ساتھ ایک پیسہ کے لیے اتفاق نہیں کیا؟ \n14۔ جو تمہارا {ہے} لے لو، اور اپنا راستہ اختیار کرو: میں اس آخری کو بھی دوں گا، جیسے تمہیں دیتا ہوں۔ \n15۔ کیا یہ جائز نہیں کہ میں اپنی آنکھ کے ساتھ جو چاہوں کروں؟ کیا تیری آنکھ برا ہے، کیونکہ میں اچھا ہوں؟ \n16۔ تو آخری سب سے پہلے ہوگا، اور پہلا آخری: کیونکہ بہت سے بلائے جائیں گے، لیکن چند منتخب کیے جائیں گے۔ \n17۔ اور یسوع یروشلم جا رہے تھے اور بارہ شاگردوں کو راستے میں الگ کر کے ان سے کہا، \n18۔ دیکھو، ہم یروشلم کی طرف جاتے ہیں؛ اور انسان کا بیٹا سردار کاہنوں اور کاتبوں کے سامنے دھوکہ دیا جائے گا، اور وہ اسے موت کی سزا دیں گے، \n19۔ اور اسے غیر قوموں کے حوالے کروں گا تاکہ وہ مذاق اڑائیں، کوڑے ماریں، اور اسے صلیب پر چڑھائیں: اور تیسرے دن وہ دوبارہ زندہ ہوگا۔ \n20۔ پھر زبدی کے بچوں کی ماں اپنے بیٹوں کے ساتھ اس کے پاس آئی، اس کی عبادت کی، اور اس سے ایک خاص چیز چاہتی رہی۔ \n21۔ اور اس نے اس سے کہا، تم کیا کرو گی؟ وہ اس سے کہتی ہے، یہ دو بیٹے تمہارے بادشاہت میں بیٹھ سکتے ہیں، ایک تمہارے دائیں ہاتھ اور دوسرا بائیں طرف۔ \n22۔ لیکن یسوع نے جواب دیا اور کہا، تم نہیں جانتے کہ تم کیا مانگتے ہو۔ کیا تم اس پیالے سے پی سکتے ہو جس سے میں پیوں گا، اور اسی بپتسمہ سے بپتسمہ لے سکتے ہو جس سے میں بپتسمہ لیا گیا ہوں؟ وہ اس سے کہتے ہیں، ہم قابل ہیں۔ \n23۔ اور وہ ان سے کہتا ہے، تم واقعی میرے پیالے سے پیو گے، اور اسی بپتسمہ سے بپتسمہ لو گے جس سے میں بپتسمہ لیا گیا ہوں: لیکن میرے دائیں اور بائیں ہاتھ پر بیٹھنا میرا نہیں بلکہ ان کے لیے دیا جائے گا جن کے لیے یہ میرے باپ نے تیار کیا ہے۔ \n24۔ اور جب دس لوگوں نے سنا، تو وہ دونوں بھائیوں کے خلاف ناراض ہو گئے۔ \n25۔ لیکن یسوع نے انہیں اپنے پاس بلایا اور کہا، تم جانتے ہو کہ غیر قوموں کے شہزادے ان پر حکمرانی کرتے ہیں، اور جو بڑے ہیں وہ ان پر اختیار رکھتے ہیں۔ \n26۔ لیکن تم میں ایسا نہیں ہوگا: لیکن جو تم میں سے بڑا ہوگا، وہ تمہارا وزیر بنے؛ \n27۔ اور جو تم میں سے سب سے بڑا بنے گا، وہ تمہارا بندہ بنے: \n28۔ جیسے انسان کا بیٹا خدمت کرنے کے لیے نہیں بلکہ خدمت کرنے اور اپنی جان دینے کے لیے آیا تاکہ بہت سے لوگوں کے لیے فدیہ ہو۔ \n29۔ اور جب وہ یریحو سے روانہ ہوئے، تو ایک بڑی تعداد اس کے پیچھے آئی۔ \n30۔ اور دیکھو، دو اندھے آدمی راستے کے کنارے بیٹھے تھے، جب انہوں نے سنا کہ یسوع گزر گیا ہے، تو انہوں نے پکارا، اے رب، داؤد کے بیٹے ہم پر رحم فرما۔ \n31۔ اور ہجوم نے انہیں ڈانٹا کہ انہیں خاموش رہنا چاہیے، لیکن وہ زیادہ پکار اٹھے، کہنے لگے، اے خداوند، داؤد کے بیٹے ہم پر رحم فرما۔ \n32۔ اور یسوع ساکت کھڑا رہا، انہیں بلایا اور کہا، تم چاہتے ہو کہ میں تمہارے ساتھ کیا کروں؟ \n33۔ وہ اس سے کہتے ہیں، اے خداوند، کہ ہماری آنکھیں کھل جائیں۔ \n34۔ تو یسوع نے ان پر رحم کیا، اور ان کی آنکھوں کو چھوا، اور فورا ان کی آنکھوں کو نظر آ گئی، اور وہ اس کے پیچھے چل پڑے۔","1۔ اور جب وہ یروشلم کے قریب پہنچے، اور بیت فاج، زیتون کے پہاڑ پر پہنچے، تو یسوع نے دو شاگرد بھیجے، \n2۔ ان سے کہتا ہوں، اپنے سامنے گاؤں میں جاؤ، اور فورا تمہیں ایک بندھا گدھا اور اس کے ساتھ ایک بچھوٹا ملے گا: انہیں آزاد کرو، اور انہیں میرے پاس لے آؤ۔ \n3۔ اور اگر کوئی {انسان} تم سے کہے، تو تم کہو گے، خداوند کو ان کی ضرورت ہے؛ اور وہ فورا انہیں بھیج دے گا۔ \n4۔ یہ سب اس لیے کیا گیا تاکہ وہ سب کچھ پورا ہو جو نبی نے کہا تھا، اور کہا تھا: \n5۔ بتاؤ سیون کی بیٹی، دیکھو، تمہارا بادشاہ تمہارے پاس آ رہا ہے، عاجز، گدھے پر بیٹھا ہوا، اور گدھے کا بچہ ہے۔ \n6۔ اور شاگرد گئے، اور یسوع نے حکم کے مطابق کیا، \n7۔ اور گدھے اور بچہ کو لایا اور ان کے کپڑے پہنا دیے، اور انہوں نے اسے وہاں بٹھایا۔ \n8۔ اور بہت بڑی تعداد نے اپنے کپڑے راستے میں پھیلا دیے؛ دوسروں نے درختوں کی شاخیں کاٹ دیں اور راستے میں ان پر تنکے لگا دیے۔ \n9۔ اور جو لوگ پہلے اور اس کے بعد آئیں، انہوں نے پکار کر کہا، ہوشعنا داؤد کے بیٹے کو: مبارک ہے وہ جو خداوند کے نام پر آتا ہے؛ ہوشعنا سب سے بلند ہے۔ \n10۔ اور جب وہ یروشلم میں آیا تو پورا شہر ہل گیا، کہنے لگا، یہ کون ہے؟ \n11۔ اور ہجوم نے کہا، یہ یسوع ہے، ناصری گلیل کا نبی۔ \n12۔ اور یسوع خدا کے مندر میں گیا، اور مندر میں بیچنے اور خریدنے والوں کو نکال دیا، اور صرافوں کی میزیں اور کبوتر بیچنے والوں کی نشستیں گرا دیں، \n13۔ اور ان سے کہا، لکھا ہے، میرا گھر عبادت کا گھر کہلائے گا؛ لیکن تم نے اسے چوروں کا ٹھکانہ بنا دیا ہے۔ \n14۔ اور اندھے اور لنگڑے مندر میں اس کے پاس آئے؛ اور اس نے انہیں شفا دی۔ \n15۔ اور جب سردار کاہنوں اور کاتبوں نے اس کے کیے ہوئے حیرت انگیز کام دیکھے، اور بچے مندر میں روتے ہوئے کہہ رہے تھے، ہوشعنا کو داؤد کے بیٹے کو؛ تو وہ سخت ناراض ہو گئے، \n16۔ اور اس سے کہا، کیا تم سنتے ہو کہ یہ کیا کہتے ہیں؟ اور یسوع نے انہیں کہا، ہاں؛ کیا تم نے کبھی بچوں اور دودھ پلانے والوں کے منہ سے تعریف مکمل نہیں کی؟ \n17۔ اور وہ انہیں چھوڑ کر شہر سے باہر بیت عنیا چلا گیا؛ اور وہاں ٹھہرا۔ \n18۔ اب صبح جب وہ شہر واپس آیا تو اسے بھوک لگی۔ \n19۔ اور جب اس نے راستے میں انجیر کا درخت دیکھا، تو اس کے پاس آیا، اور وہاں صرف پتوں کے سوا کچھ نہیں پایا، اور اس نے کہا، اب سے ہمیشہ کے لیے تم پر کوئی پھل نہ اگے۔ اور جلد ہی انجیر کا درخت مرجھا گیا۔ {ایک انجیر کا درخت: Gr. ایک انجیر کا درخت}\n20۔ اور جب شاگردوں نے اسے دیکھا تو حیران رہ گئے اور کہا، انجیر کا درخت کب مرجھا گیا! \n21۔ یسوع نے جواب دیا اور ان سے کہا، \"یقینا میں تم سے کہتا ہوں، اگر تم ایمان رکھو اور شک نہ کرو، تو نہ صرف انجیر کے درخت کے ساتھ یہ کرو گے، بلکہ اگر تم اس پہاڑ سے کہو گے، ہٹا دو اور سمندر میں پھینک دیے جاؤ؛ یہ ہو جائے گا۔ \n22. اور جو کچھ بھی دعا میں مانگے، ایمان کے ساتھ، تمہیں ملے گا۔ \n23۔ اور جب وہ مندر میں آیا، تو سردار پادری اور قوم کے بزرگ اس کے پاس آئے جب وہ تعلیم دے رہا تھا، اور کہا، تم یہ سب کس اختیار سے کرتے ہو؟ اور تمہیں یہ اختیار کس نے دیا؟ \n24۔ اور یسوع نے جواب دیا اور ان سے کہا، میں بھی تم سے ایک بات پوچھوں گا، اگر تم مجھے بتاؤ گے تو میں بھی تمہیں بتاؤں گا کہ میں یہ سب کس اختیار سے کرتا ہوں۔ \n25۔ یوحنا کا بپتسمہ، کہاں سے تھا؟ آسمان سے، یا انسانوں سے؟ اور انہوں نے خود سے بحث کی، کہا، اگر ہم کہیں، آسمان سے؛ وہ ہم سے کہے گا، پھر تم نے اس پر یقین کیوں نہیں کیا؟ \n26۔ لیکن اگر ہم کہیں، انسانوں سے؛ ہم لوگوں سے ڈرتے ہیں؛ کیونکہ سب جان کو نبی سمجھتے ہیں۔ \n27۔ اور انہوں نے یسوع کا جواب دیا، اور کہا، ہم نہیں بتا سکتے۔ اور اس نے ان سے کہا، میں تمہیں نہیں بتاتا کہ میں یہ سب کس اختیار سے کرتا ہوں۔ \n28۔ لیکن تم کیا سوچتے ہو؟ ایک {یقینی} آدمی کے دو بیٹے تھے؛ اور وہ پہلے کے پاس آیا اور کہا، بیٹا، آج میرے انگور کے باغ میں کام کرو۔ \n29۔ اس نے جواب دیا اور کہا، میں نہیں جاؤں گا، لیکن بعد میں اس نے توبہ کی اور چلا گیا۔ \n30۔ اور وہ دوسرے کے پاس آیا، اور ویسا ہی کہا۔ اور اس نے جواب دیا اور کہا، میں جا رہا ہوں، سر: اور نہیں گیا۔ \n31۔ کیا ان میں سے دونوں نے {اس} کے باپ کی مرضی پوری کی؟ وہ اسے کہتے ہیں، پہلا۔ یسوع ان سے کہتا ہے، یقینا میں تم سے کہتا ہوں، کہ پبلکرز اور فاحشیں تمہارے سامنے خدا کی بادشاہی میں چلی جائیں۔ \n32۔ کیونکہ یوحنا آپ کے پاس راستبازی کی راہ پر آیا، اور آپ نے اس پر یقین نہیں کیا: بلکہ پبلکرز اور فاحشیں اس پر یقین کر لیں: اور جب آپ نے اسے دیکھا تو بعد میں توبہ نہیں کی تاکہ آپ اس پر یقین کر سکیں۔ \n33۔ ایک اور تمثیل سنو: ایک گھر کا مالک تھا، جس نے انگور کا باغ لگایا، اس کے ارد گرد باڑ لگائی، اس میں شراب کا پریس کھودا، ایک برج بنایا، اسے کسانوں کو کرایہ پر دیا، اور ایک دور دراز علاقے میں چلا گیا: \n34۔ اور جب پھل کا وقت قریب آیا، اس نے اپنے خادموں کو کسانوں کے پاس بھیجا تاکہ وہ اس کے پھل حاصل کر سکیں۔ \n35۔ اور کسانوں نے اس کے نوکروں کو لے کر ایک کو مارا، ایک کو مارا، اور دوسرے کو پتھر مارا۔ \n36۔ پھر بھی، اس نے پہلے سے زیادہ خادم بھیجے: اور انہوں نے بھی ان کے ساتھ ایسا ہی کیا۔ \n37۔ لیکن آخر میں اس نے اپنے بیٹے کو ان کے پاس بھیجا، کہا، وہ میرے بیٹے کی عزت کریں گے۔ \n38۔ لیکن جب کسانوں نے بیٹے کو دیکھا، تو انہوں نے آپس میں کہا، یہ وارث ہے؛ آؤ، اسے مار ڈالیں، اور اس کی میراث پر قبضہ کریں۔ \n39۔ اور انہوں نے اسے پکڑ لیا، باغ سے نکال دیا، اور {اس} کو قتل کر دیا۔ \n40۔ جب باغ کا مالک آئے گا، تو وہ ان کسانوں کے ساتھ کیا کرے گا؟ \n41۔ وہ اس سے کہتے ہیں، وہ ان بدکاروں کو بے رحمی سے تباہ کرے گا، اور اپنا انگور کا باغ دوسرے کسانوں کو دے دے گا، جو اسے اپنے موسم کے مطابق پھل دے گا۔ \n42۔ یسوع نے ان سے کہا، کیا تم نے کبھی صحیفوں میں نہیں پڑھا، وہ پتھر جسے معماروں نے رد کیا، وہی ہے کہ کونے کا سر بن جائے: یہ خداوند کا کام ہے، اور ہماری نظر میں حیرت انگیز ہے؟ \n43۔ لہٰذا میں تم سے کہتا ہوں، خدا کی بادشاہی تم سے چھین لی جائے گی، اور ایک ایسی قوم کو دی جائے گی جو اس کے پھل لاتی ہے۔ \n44۔ اور جو بھی اس پتھر پر گرا گا وہ ٹوٹ جائے گا: لیکن جس پر یہ گرے گا، وہ اسے پاؤڈر میں پیس دے گا۔ \n45۔ اور جب سردار کاہنوں اور فریسیوں نے اس کی تمثیلیں سنیں، تو انہوں نے محسوس کیا کہ وہ ان کے بارے میں بات کر رہا ہے۔ \n46۔ لیکن جب انہوں نے اس پر ہاتھ ڈالنے کی کوشش کی، تو وہ ہجوم سے ڈر گئے، کیونکہ انہوں نے اسے نبی سمجھا۔","1۔ آسمان کی بادشاہی ایک خاص بادشاہ کی مانند ہے، جس نے اپنے بیٹے کے لیے شادی کی، \n2۔ اور اس نے اپنے خادموں کو بھیجا کہ جنہیں شادی میں بلایا گیا تھا، انہیں بلائے، لیکن وہ نہیں آئے۔ \n3۔ پھر اس نے دوسرے خادم بھیجے اور کہا، انہیں بتاؤ کہ کہاں حکم دیا گیا ہے، دیکھو، میں نے اپنا کھانا تیار کر لیا ہے: میرے بیل اور میرے موٹے بچے مارے گئے اور سب کچھ تیار ہے: شادی کے لیے آؤ۔ \n4۔ لیکن انہوں نے اسے ہلکا پھلکا کیا، اور اپنے راستے گئے، ایک اس کے کھیت کی طرف، دوسرا اس کے مال کی طرف: \n5۔ اور باقی ماندہ نے اس کے خادموں کو لے کر ان سے بغض سے التجا کی اور انہیں قتل کر دیا۔ \n6۔ لیکن جب بادشاہ نے اس کی خبر سنی تو وہ غصے میں آ گیا: اور اس نے اپنی فوجیں بھیجیں، ان قاتلوں کو تباہ کر دیا، اور ان کے شہر کو جلا دیا۔ \n7۔ پھر وہ اپنے خادموں سے کہتا ہے، شادی تیار ہے، لیکن جو حکم دیے گئے تھے وہ لائق نہیں تھے۔ \n8۔ لہٰذا تم سڑکوں پر جاؤ، اور جتنے بھی ملیں گے، شادی کے لیے دعا کرو۔ \n9۔ تو وہ خادم شاہراہوں پر نکلے، اور جتنے لوگ ملے، چاہے وہ برے ہوں یا اچھے، جمع کیے: اور شادی مہمانوں سے سجا دی گئی۔ \n10۔ اور جب بادشاہ مہمانوں سے ملنے آیا تو اس نے وہاں ایک آدمی دیکھا جس نے شادی کے لباس پر نہیں پہنا تھا: \n11۔ اور وہ اس سے کہتا ہے، دوست، تم یہاں کیسے آئے بغیر شادی کا لباس کے؟ اور وہ بے زبان رہ گیا۔ \n12۔ پھر بادشاہ نے خادموں سے کہا، اسے ہاتھ پاؤں باندھ کر لے جاؤ، اور اسے باہر کے اندھیرے میں پھینک دو؛ وہاں رونا اور دانت پیسنا ہوگا۔ \n13۔ کیونکہ بہت سے لوگ بلایا جاتا ہے، لیکن چند ہی منتخب ہوتے ہیں۔ \n14۔ پھر فریسیوں گئے، اور انہوں نے مشورہ کیا کہ وہ اسے اس کی باتوں میں کیسے الجھا سکتے ہیں۔ \n15۔ اور انہوں نے اپنے شاگردوں کو ہیرودیوں کے ساتھ اس کے پاس بھیجا، کہا، استاد، ہم جانتے ہیں کہ تم سچے ہو، اور خدا کا راستہ سچائی میں سکھاتے ہو، نہ تمہیں کسی انسان کی پرواہ ہے، کیونکہ تم انسانوں کی ذات کو نہیں سمجھتے۔ \n16۔ تو بتاؤ، تم کیا سوچتے ہو؟ کیا قیصر کو خراج دینا جائز ہے یا نہیں؟ \n17۔ لیکن یسوع نے ان کی برائی کو دیکھا اور کہا، تم مجھے کیوں آزماتے ہو، منافقو؟ \n18۔ مجھے خراج کے پیسے دکھاؤ۔ اور انہوں نے اسے ایک پیسہ دیا۔ {پینی: سات پینس آدھا پینی قیمت میں}\n19۔ اور وہ ان سے کہتا ہے، یہ تصویر اور اوپر کی تحریر کس کی ہے؟ {اوپر تحریر: یا، تحریر}\n20۔ وہ اس سے کہتے ہیں، قیصر کی۔ پھر وہ ان سے کہتا ہے، تو قیصر کو وہ چیزیں دے جو قیصر کی ہیں؛ اور خدا کو وہ چیزیں دے دو جو خدا کی ہیں۔ \n21. جب انہوں نے یہ الفاظ سنے، تو وہ حیران ہوئے، اسے چھوڑ کر اپنی راہ پر چلے گئے۔ \n22۔ اسی دن اس کے پاس صدوقیوں آئے، جنہوں نے کہا کہ قیامت نہیں ہوتی، اور انہوں نے ان سے پوچھا: \n23۔ اے آقا، موسیٰ نے کہا، اگر کوئی مرد مر جائے اور اس کے بچے نہ ہوں، تو اس کا بھائی اپنی بیوی سے شادی کرے گا اور اپنے بھائی کے لیے نسل پیدا کرے گا۔ \n24۔ اب ہمارے ساتھ سات بھائی تھے: اور پہلا، جب اس نے ایک مرحومہ بیوی سے شادی کی اور اولاد نہ ہونے کی وجہ سے، اپنی بیوی اپنے بھائی کو دے دی: \n25۔ اسی طرح دوسرا بھی، اور تیسرا، ساتویں تک۔ {ساتویں: گری. سات}\n26۔ اور آخر میں وہ عورت بھی مر گئی۔ \n27. تو قیامت میں وہ ساتوں میں سے کس کی بیوی ہوگی؟ کیونکہ سب کے پاس وہ تھی۔ \n28۔ یسوع نے جواب دیا اور ان سے کہا، تم غلطی کر رہے ہو، نہ صحیفوں کو جانتے ہو، نہ خدا کی طاقت کو۔ \n29۔ کیونکہ قیامت میں وہ نہ تو شادی کرتے ہیں، نہ شادی میں دیے جاتے ہیں، بلکہ آسمان میں خدا کے فرشتوں کی طرح ہیں۔ \n30۔ لیکن مردوں کی قیامت کے بارے میں، کیا تم نے وہ نہیں پڑھا جو خدا نے تم سے کہا تھا، کہتا ہے، \n31. میں ابراہیم کا خدا ہوں، اسحاق کا خدا ہوں، اور یعقوب کا خدا ہوں؟ خدا مردوں کا خدا نہیں بلکہ زندہ لوگوں کا ہے۔ \n32۔ اور جب ہجوم نے {یہ} سنا، تو وہ اس کے عقیدے پر حیران رہ گئے۔ \n33۔ لیکن جب فریسیوں کو معلوم ہوا کہ اس نے صدوقیوں کو خاموش کر دیا ہے، تو وہ سب اکٹھے ہو گئے۔ \n34۔ پھر ان میں سے ایک، {جو کہ} وکیل تھا، نے {اس سے ایک سوال} پوچھا، اسے بہکایا اور کہا، \n35۔ استاد، قانون میں سب سے بڑا حکم کون سا ہے؟ \n36۔ یسوع نے اس سے کہا، تو اپنے خداوند اپنے خدا سے اپنے تمام دل، اپنی پوری جان اور پورے ذہن سے محبت کرے۔ \n37. یہ پہلا اور عظیم حکم ہے۔ \n38۔ اور دوسرا اس جیسا ہے، تو اپنے پڑوسی سے ویسا ہی محبت کرو جیسے تم خود کرو۔ \n39۔ ان دو احکام پر تمام قانون اور انبیاء لٹکتے ہیں۔ \n40۔ جب فریسیوں کو جمع کیا گیا، یسوع نے ان سے پوچھا، \n41۔ کہتے ہیں، تم مسیح کے بارے میں کیا سوچتے ہو؟ وہ کس کا بیٹا ہے؟ وہ اس سے کہتے ہیں، {داؤد کا بیٹا}۔ \n42۔ وہ ان سے کہتا ہے، تو پھر داؤد روح میں اسے خداوند کہتا ہے، کہتا ہے، \n43۔ خداوند نے میرے رب سے کہا، کیا تم میرے دائیں ہاتھ پر بیٹھو، جب تک میں تمہارے دشمنوں کو اپنا سہارا نہ بنا لوں؟ \n44۔ اگر داؤد اسے خداوند کہے، تو وہ اس کا بیٹا کیسے ہے؟ \n45. اور کوئی انسان اس کا جواب بھی نہ دے سکا، نہ ہی اس دن کے بعد کوئی {انسان} اس سے مزید {سوالات} پوچھنے کی ہمت نہ کر سکا۔","1۔ پھر یسوع نے عوام اور اپنے شاگردوں سے کہا، \n2۔ کہتے ہوئے، کاتب اور فریسی موسیٰ کی نشست پر بیٹھے ہیں: \n3۔ لہٰذا جو کچھ وہ آپ کو دیکھنے کو کہتے ہیں، وہ سب دیکھیں اور کریں؛ لیکن آپ ان کے اعمال کے بعد نہ کریں: کیونکہ وہ کہتے ہیں اور نہیں کرتے۔ \n4۔ کیونکہ وہ بھاری بوجھ اور بھاری بوجھ باندھتے ہیں اور انسانوں کے کندھوں پر ڈالتے ہیں؛ لیکن وہ خود انہیں اپنی انگلی سے نہیں ہلا سکتے۔ \n5۔ لیکن وہ اپنے تمام کام انسانوں کو دیکھنے کے لیے کرتے ہیں: وہ اپنے مجسمے چوڑے کرتے ہیں، اور اپنے لباس کے کناروں کو وسیع کرتے ہیں، {فائلیکٹریاں: وہ کاغذ کے ٹکڑے جن میں شریعت کے جملے ہوتے ہیں}\n6۔ اور تہواروں کے سب سے اوپر والے کمروں اور عبادت گاہوں کی اہم نشستوں سے محبت کرتے ہیں، \n7۔ اور بازاروں میں سلام، اور مردوں کو بلایا جائے، ربی، ربی۔ \n8۔ لیکن تم ربی نہ کہلو: کیونکہ ایک تمہارا مالک ہے، {حتی} مسیح؛ اور تم سب بھائی ہو۔ \n9۔ اور اپنے باپ کو زمین پر نہ پکارو: کیونکہ تمہارا باپ آسمان میں ایک ہے۔ \n10۔ نہ تم مالک کہلو: کیونکہ ایک تمہارا مالک ہے، {حتی} مسیح۔ \n11۔ لیکن جو تم میں سب سے بڑا ہوگا وہ تمہارا خادم ہوگا۔ \n12۔ اور جو خود کو بلند کرے گا وہ ذلیل ہو جائے گا؛ اور جو خود کو عاجز کرے گا وہ بلند ہوگا۔ \n13. لیکن تم پر افسوس ہے، کاتبوں اور فریسیوں، منافقو! کیونکہ تم آسمان کی بادشاہی کو انسانوں کے خلاف بند کرتے ہو: کیونکہ تم خود اندر نہیں جاتے، نہ داخل ہونے والوں کو اندر جانے دیتے ہو۔ \n14. تم پر افسوس، کاتبوں اور فریسیوں، منافقو! کیونکہ تم بیواؤں کے گھروں کو کھاتے ہو، اور بہانے کے لیے طویل دعا کرتے ہو: اس لیے تمہیں بڑی لعنت ملے گی۔ \n15۔ تم پر افسوس ہے، کاتبوں اور فریسیوں، منافقو! کیونکہ تم سمندر اور زمین کو گھیر کر ایک کو موعظ بناتے ہو، اور جب وہ بنایا جاتا ہے، تو تم اسے تم سے دوگنا زیادہ جہنم کا بیٹا بناتے ہو۔ \n16۔ تم پر افسوس، اے اندھے رہنما، جو کہتے ہیں، جو مندر کی قسم کھائے گا، وہ کچھ نہیں؛ لیکن جو مندر کے سونے کی قسم کھائے گا، وہ مقروض ہے! \n17۔ اے بے وقوف اور اندھے: کیونکہ سونا بڑا ہے یا وہ مندر جو سونے کو مقدس بناتا ہے؟ \n18۔ اور جو بھی قربان گاہ کی قسم کھائے گا، وہ کچھ نہیں؛ لیکن جو اس پر موجود تحفے کی قسم کھائے گا، وہ قصوروار ہے۔ {قصوروار: یا، مقروض، یا، پابند ہے}\n19۔ {اے بے وقوف اور اندھے}: کیونکہ تحفہ بڑا ہے یا وہ قربان گاہ جو تحفے کو مقدس بناتا ہے؟ \n20۔ جو بھی قربان گاہ کی قسم کھائے گا، وہ اس پر اور اس پر موجود ہر چیز کی قسم کھائے گا۔ \n21۔ اور جو مندر کی قسم کھائے گا، وہ اس کی قسم کھائے گا، اور اس کے بسنے والے کی بھی۔ \n22۔ اور جو آسمان کی قسم کھائے گا، وہ خدا کے تخت اور اس پر بیٹھے ہوئے کے عہد کرے گا۔ \n23. تم پر افسوس ہے، کاتبوں اور فریسیوں، منافقو! کیونکہ تم نے ٹکالے، انیس اور انجن کی عشر رقم ادا کی ہے، اور قانون، فیصلہ، رحم اور ایمان کے اہم اہم معاملات کو چھوڑ دیا ہے: یہ سب تمہیں کرنا چاہیے تھا، اور ایک کو چھوڑنا نہیں چاہیے تھا۔ {انیس: Gr. dill}\n24۔ اندھے رہنما جو مچھر پر زور لگاتے ہیں اور اونٹ کو نگل جاتے ہیں۔ \n25۔ تم پر افسوس ہو، کاتبوں اور فریسیوں، منافقو! کیونکہ تم پیالے اور پلیٹ کے باہر کی صفائی کرتے ہو، لیکن اندر سے وہ ظلم و زیادتی سے بھرے ہوتے ہیں۔ \n26۔ {تو} اندھے فریسی، پہلے پیالہ اور پلیٹ میں موجود {جو ہے} صاف کر، تاکہ ان کا باہر بھی صاف ہو۔ \n27۔ تم پر افسوس ہو، کاتبوں اور فریسیوں، منافقو! کیونکہ تم سفید قبروں کی طرح ہو، جو ظاہری طور پر خوبصورت نظر آتی ہے، لیکن اندر مردہ ہڈیوں اور تمام ناپاکیوں سے بھری ہوئی ہے۔ \n28۔ اسی طرح تم بظاہر انسانوں کے سامنے نیک نظر آتے ہو، لیکن تم اندر منافقت اور بدکاری سے بھرے ہوئے ہو۔ \n29۔ تم پر افسوس ہے، کاتبوں اور فریسیوں، منافقو! کیونکہ تم نبیوں کی قبریں بناتے ہو، اور راستبازوں کی قبروں کو سجاتے ہو، \n30۔ اور کہو، اگر ہم اپنے آباؤ اجداد کے زمانے میں ہوتے تو ہم انبیاء کے خون میں ان کے ساتھ شریک نہ ہوتے۔ \n31۔ اسی لیے تم خود گواہ ہو کہ تم ان کے بیٹے ہو جنہوں نے نبیوں کو قتل کیا۔ \n32۔ پھر اپنے باپ دادا کے پیمائش کو بھر دو۔ \n33. اے سانپوں، اے سانپوں کی نسل، تم جہنم کی لعنت سے کیسے بچ سکتے ہو؟ \n34۔ چنانچہ، دیکھو، میں تمہارے پاس نبی، دانا اور کاتب بھیجتا ہوں: اور ان میں سے کچھ کو تم قتل کرو گے اور صلیب پر چڑھاؤ گے؛ اور ان میں سے کچھ کو تم اپنی عبادت گاہوں میں کوڑے مارو گے، اور انہیں شہر سے شہر تک ستاؤ گے: \n35۔ تاکہ تم پر زمین پر بہایا گیا تمام نیک خون آئے، راستباز ہابیل کے خون سے لے کر زکریا کے خون تک، جو تم نے مندر اور قربان گاہ کے درمیان مارا تھا۔ \n36۔ یقینا میں تم سے کہتا ہوں، یہ سب چیزیں اس نسل پر آئیں گی۔ \n37۔ اے یروشلم، یروشلم، {تو} جو پیغمبروں کو قتل کرتی ہے اور جو تمہارے پاس بھیجے جاتے ہیں انہیں سنگسار کرتی ہو، میں کتنی بار تمہارے بچوں کو اکٹھا کرتا، جیسے مرغی اپنے مرغیوں کو اپنے پروں کے نیچے جمع کرتی ہے، اور تم نہیں چاہتے! \n38۔ دیکھو، تمہارا گھر تمہارے لیے ویران چھوڑ دیا گیا ہے۔ \n39۔ کیونکہ میں تم سے کہتا ہوں، تم مجھے اب سے نہیں دیکھو گے، جب تک کہ تم یہ نہ کہو، مبارک ہے وہ جو خداوند کے نام پر آتا ہے۔","1۔ اور یسوع باہر چلا گیا، اور مندر سے روانہ ہو گیا، اور اس کے شاگرد اس کے پاس آئے تاکہ اسے ہیکل کی عمارتیں دکھا سکیں۔ \n2۔ اور یسوع نے ان سے کہا، کیا تم یہ سب چیزیں نہیں دیکھتے؟ یقینا میں تم سے کہتا ہوں، یہاں ایک پتھر پر دوسرے پتھر نہیں چھوڑے گا جو نہ گرایا جائے۔ \n3۔ اور جب وہ زیتون کے پہاڑ پر بیٹھا تھا، شاگرد اس کے پاس چپکے سے آئے اور کہا، بتاؤ، یہ چیزیں کب ہوں گی؟ اور تمہارے آنے اور دنیا کے خاتمے کی نشانی کیا ہوگی؟ \n4۔ اور یسوع نے جواب دیا اور ان سے کہا، خبردار رہو کہ کوئی انسان تمہیں دھوکہ نہیں دے سکتا۔ \n5۔ کیونکہ بہت سے لوگ میرے نام پر آئیں گے، کہیں گے، میں مسیح ہوں؛ اور بہت سے لوگوں کو دھوکہ دیں گے۔ \n6۔ اور تم جنگوں اور جنگوں کی افواہوں کے بارے میں سنو گے: دیکھو کہ تم پریشان نہ ہو: کیونکہ یہ سب ہونا ضروری ہے، لیکن انجام ابھی نہیں آیا۔ \n7۔ کیونکہ قوم قوم کے خلاف اٹھے گی، اور بادشاہی بادشاہت کے خلاف بادشاہت کے خلاف: اور قحط، وباء، اور زلزلے مختلف جگہوں پر ہوں گے۔ \n8۔ یہ سب {ہیں} غموں کی ابتدا ہیں۔ \n9۔ پھر وہ تمہیں تکلیف میں مبتلا کرنے کے لیے حوالے کریں گے، اور تمہیں مار ڈالیں گے: اور تم میرے نام کے لیے تمام قوموں سے نفرت کرو گے۔ \n10۔ پھر بہت سے لوگ ناراض ہوں گے، ایک دوسرے سے غداری کریں گے، اور ایک دوسرے سے نفرت کریں گے۔ \n11۔ اور بہت سے جھوٹے نبی اٹھیں گے، اور بہت سے لوگوں کو دھوکہ دیں گے۔ \n12۔ اور چونکہ گناہوں کی بھرمار ہوگی، بہت سے لوگوں کی محبت سرد ہو جائے گی۔ \n13۔ لیکن جو آخر تک قائم رہے، وہی نجات پائے گا۔ \n14۔ اور بادشاہی کی یہ خوشخبری پوری دنیا میں تمام قوموں کے لیے گواہی کے طور پر سنائی جائے گی؛ اور پھر انجام ہوگا۔ \n15۔ جب تم ویرانی کی مکروہ کو دیکھو گے، جس کا ذکر دانیال نبی نے کیا ہے، تو مقدس جگہ پر کھڑے ہو جاؤ، (جو پڑھے گا، اسے سمجھ جائے:)\n16۔ پھر جو یہودیہ میں ہیں وہ پہاڑوں کی طرف بھاگ جائیں: \n17۔ جو گھر کی چھت پر ہے وہ اپنے گھر سے کچھ لے جانے کے لیے نیچے نہ آئے: \n18۔ نہ ہی اسے جو کھیت میں ہے واپس جانے دو تاکہ وہ اپنے کپڑے لے سکے۔ \n19۔ اور ان پر افسوس جو حاملہ ہیں، اور ان پر جو ان دنوں دودھ پیتے ہیں! \n20۔ لیکن دعا کرو کہ تمہاری پرواز سردیوں میں نہ ہو، نہ ہی سبت کے دن: \n21۔ کیونکہ پھر بڑی مصیبت آئے گی، جو دنیا کے آغاز سے اب تک نہیں تھی، اور نہ ہی کبھی ہوگی۔ \n22۔ اور جب تک وہ دن مختصر نہ ہوں، کوئی جسم بچ نہیں سکتا: لیکن منتخب لوگوں کی خاطر وہ دن مختصر کیے جائیں گے۔ \n23۔ پھر اگر کوئی شخص تم سے کہے، دیکھو، یہاں مسیح ہے، یا وہاں؛ یقین نہ کرو۔ \n24۔ کیونکہ جھوٹے مسیح اور جھوٹے نبی جنم لیں گے، اور عظیم نشانیاں اور عجائبات دکھائیں گے؛ یہاں تک کہ اگر ممکن ہو تو وہ منتخب لوگوں کو دھوکہ دیں گے۔ \n25۔ دیکھو، میں نے تمہیں پہلے بھی بتایا ہے۔ \n26۔ اگر وہ تم سے کہیں، دیکھو، وہ صحرا میں ہے؛ باہر مت جاؤ: دیکھو، {وہ} خفیہ کمروں میں ہے؛ یقین نہ کرو۔ \n27۔ جیسے بجلی مشرق سے نکلتی ہے اور مغرب کی طرف بھی چمکتی ہے؛ ویسے ہی انسان کے بیٹے کا آنا بھی ہوگا۔ \n28۔ جہاں بھی لاش ہو، وہاں عقاب جمع ہوں گے۔ \n29۔ ان دنوں کی مصیبت کے فورا بعد سورج تاریک ہو جائے گا، چاند اپنی روشنی نہیں دے گا، اور ستارے آسمان سے گریں گے، اور آسمانوں کی طاقتیں ہل جائیں گی: \n30۔ پھر آسمان میں انسان کے بیٹے کی نشانی ظاہر ہوگی، اور پھر زمین کے تمام قبائل سوگ منائیں گے، اور وہ دیکھیں گے کہ انسان کا بیٹا آسمان کے بادلوں میں طاقت اور عظمت کے ساتھ آ رہا ہے۔ \n31۔ اور وہ اپنے فرشتوں کو بگل کی زور دار آواز کے ساتھ بھیجے گا، اور وہ اپنے منتخب لوگوں کو چار ہواؤں سے جمع کریں گے، آسمان کے ایک سرے سے دوسرے سرے تک۔ {کے ساتھ...: یا، بگل اور بڑی آواز کے ساتھ}\n32. اب انجیر کے درخت کی ایک مثال سیکھو؛ جب اس کی شاخ ابھی نرم ہو اور پتے نکالے، تو تم جانتے ہو کہ گرمیوں کا موسم قریب ہے: \n33. اسی طرح، جب تم یہ سب چیزیں دیکھو، تو جان لو کہ یہ دروازوں کے قریب ہے، {حتی}۔ {یہ: یا، وہ}\n34۔ یقینا میں تم سے کہتا ہوں، یہ نسل اس وقت تک نہیں گزرے گی جب تک یہ سب کچھ پورا نہ ہو جائے۔ \n35۔ آسمان اور زمین ختم ہو جائیں گے، لیکن میرے الفاظ ختم نہیں ہوں گے۔ \n36۔ لیکن اس دن اور گھڑی کے بارے میں کوئی {انسان} نہیں جانتا، نہ آسمان کے فرشتوں کو، بلکہ صرف میرے والد کو۔ \n37۔ لیکن جیسے نوئے کے دن تھے، ویسے ہی انسان کے بیٹے کا آنا بھی ہوگا۔ \n38۔ کیونکہ جیسے سیلاب سے پہلے کے دنوں میں وہ کھاتے پیتے، شادی کرتے اور شادی کرتے، یہاں تک کہ نوئے کشتی میں داخل ہوا، \n39۔ اور مجھے معلوم نہیں تھا جب تک سیلاب آیا اور سب کو لے گیا؛ اسی طرح بیٹے کا آنا بھی ہوگا۔ \n40۔ پھر دو کھیت میں ہوں گے؛ ایک کو لے جایا جائے گا، اور دوسرا چھوڑ دیا جائے گا۔ \n41۔ دو {عورتیں} مل پر پیس رہی ہوں گی؛ ایک کو لے لیا جائے گا، اور دوسری کو چھوڑ دیا جائے گا۔ \n42۔ تو دیکھو: کیونکہ تم نہیں جانتے کہ تمہارا رب کس وقت آئے گا۔ \n43۔ لیکن یہ جان لو، اگر گھر کے نیک آدمی کو معلوم ہوتا کہ چور کس پہرے میں آئے گا، تو وہ دیکھتا رہتا، اور اپنے گھر کو ٹوٹنے نہیں دیتا۔ \n44۔ لہٰذا تم بھی تیار رہو: کیونکہ اس وقت جب تم نہیں سمجھتے کہ انسان کا بیٹا آئے گا۔ \n45۔ تو پھر کون ہے وفادار اور دانا خادم، جسے اس کا رب اپنے گھرانے کا حکمران بنا چکا ہے، تاکہ انہیں وقت پر گوشت دے سکے؟ \n46۔ مبارک ہے وہ بندہ، جسے اس کا رب جب آئے گا تو ایسا کرتے ہوئے پائے گا۔ \n47۔ یقینا میں تم سے کہتا ہوں، کہ وہ اسے اپنی تمام مالوں کا حکمران بنائے گا۔ \n48۔ اور اگر وہ ظالم خادم اپنے دل میں کہے، میرا آقا اس کی آمد میں تاخیر کرتا ہے؛ \n49۔ اور اپنے ساتھیوں کو مارنا شروع کرے گا، اور نشے میں دھت لوگوں کے ساتھ کھانا پینا شروع کرے گا؛ \n50۔ اس خادم کا مالک اس دن آئے گا جب وہ اس کی تلاش میں نہ ہو، اور ایک ایسے وقت میں جس کا اسے علم نہ ہو، \n51۔ اور اسے کاٹ کر منافقوں کے ساتھ اس کا حصہ دے دوں گا: وہاں رونا اور دانت پیسنا ہوگا۔ {کاٹ دو...: یا اسے کاٹ دو}","1۔ پھر آسمان کی بادشاہی کو دس کنواریوں سے تشبیہ دی جائے گی، جنہوں نے اپنے چراغ لے کر دولہا سے ملنے نکل آئیں۔ \n2۔ اور ان میں سے پانچ عقلمند تھے، اور پانچ بے وقوف تھے۔ \n3۔ جو لوگ بے وقوف تھے، انہوں نے اپنے چراغ لے لیے اور تیل ساتھ نہیں لے گئے: \n4۔ لیکن دانا اپنے برتنوں میں اپنے چراغوں کے ساتھ تیل لیتے تھے۔ \n5۔ جب دولہا ٹھہرا ہوا تھا، تو سب سو رہے تھے اور سو رہے تھے۔ \n6۔ اور آدھی رات کو ایک چیخ نکلی، دیکھو، دولہا آتا ہے؛ تم اس سے ملنے جاؤ۔ \n7۔ پھر وہ سب کنواری لڑکیاں اٹھیں اور اپنی چراغیں سنوار دیں۔ \n8۔ اور بے وقوف نے عقلمندوں سے کہا، اپنا تیل ہمیں دو؛ کیونکہ ہمارے چراغ بجھ چکے ہیں۔ {بجھ گئے: یا، بجھ رہے ہیں}\n9۔ لیکن دانا نے جواب دیا، {ایسا نہیں}؛ کہیں ہمارے اور تمہارے لیے کافی نہ ہو، بلکہ تم ان کے پاس جاؤ جو بیچتے اور اپنے لیے خریدتے ہیں۔ \n10۔ اور جب وہ خریداری کے لیے گئے، دولہا آیا؛ اور جو تیار تھے وہ اس کے ساتھ شادی میں داخل ہو گئے: اور دروازہ بند ہو گیا۔ \n11۔ اس کے بعد دوسری کنواریاں بھی آئیں اور کہا، اے خداوند، ہمارے لیے کھلا ہے۔ \n12۔ لیکن اس نے جواب دیا اور کہا، \"یقینا میں تم سے کہتا ہوں، میں تمہیں نہیں جانتا۔ \n13۔ لہٰذا دیکھو، کیونکہ تم نہیں جانتے کہ انسان کا بیٹا کب آتا ہے اور نہ ہی گھڑی۔ \n14. کیونکہ {آسمان کی بادشاہی} ایسے ہے جیسے کوئی شخص دور دراز ملک میں سفر کرے، {جس نے} اپنے بندوں کو بلایا اور اپنی چیزیں ان کے حوالے کیں۔ \n15۔ اور ایک کو پانچ ٹیلنٹس دیے، دوسرے کو دو کو، اور دوسرے کو دیے؛ ہر آدمی کو اس کی کئی صلاحیتوں کے مطابق؛ اور فورا اپنا سفر شروع کیا۔ {ٹیلنٹس: ایک ٹیلنٹ ایک سو ستااسی پاؤنڈ دس شلنگ ہے}\n16۔ پھر جس نے پانچ ٹیلنٹس حاصل کیے تھے، جا کر انہی ٹیلنٹس کے ساتھ تبادلہ کیا، اور باقی پانچ ٹیلنٹس بنا لیے۔ \n17۔ اور اسی طرح جس نے دو حاصل کیے، اس نے دوسرے دو بھی حاصل کیے۔ \n18۔ لیکن جس نے اسے پایا تھا، وہ زمین میں کھود کر اپنے مالک کے پیسے چھپا گیا۔ \n19۔ کافی دیر بعد ان خادموں کا مالک آتا ہے اور ان سے حساب کرتا ہے۔ \n20۔ اور جس نے پانچ ٹیلنٹس حاصل کیے تھے وہ آیا اور پانچ ٹیلنٹس لے آیا، اور کہا، اے خداوند، تو نے مجھے پانچ ٹیلنٹس دیے: دیکھو، میں نے ان کے علاوہ پانچ ٹیلنٹس مزید حاصل کر لیے ہیں۔ \n21۔ اس کے رب نے اس سے کہا، شاباش، اے نیک اور وفادار بندہ: تم نے چند معاملات میں وفادار رہا، میں تمہیں بہت سی چیزوں پر حکمران بنا دوں گا: اپنے رب کی خوشی میں داخل ہو جاؤ۔ \n22۔ جس نے دو ٹیلنٹس حاصل کیے تھے، وہ آیا اور کہا، اے خداوند، تو نے مجھے دو ٹیلنٹس دیے: دیکھو، میں نے ان کے علاوہ دو اور ٹیلنٹس حاصل کر لیے ہیں۔ \n23۔ اس کے رب نے اس سے کہا، شاباش، نیک اور وفادار بندہ؛ تم نے کچھ چیزوں میں وفاداری کی ہے، میں تمہیں بہت سی چیزوں پر حکمران بناؤں گا: اپنے رب کی خوشی میں داخل ہو جاؤ۔ \n24۔ پھر جس نے ایک تحفہ حاصل کیا تھا، آیا اور کہا، اے خداوند، میں نے تو جانتا تھا کہ تم سخت آدمی ہو، جو وہاں کاٹتا ہے جہاں تم نے نہیں بویا، اور جہاں نہیں بولا وہاں جمع کر رہا ہے: \n25۔ اور میں ڈر گیا، اور تمہاری صلاحیت زمین میں چھپا لی: دیکھو، {وہاں} تو تمہاری ہے۔ \n26۔ اس کے رب نے جواب دیا اور کہا، {تو} بدکار اور سست بندہ، تو سب سے زیادہ جانتا ہے کہ میں وہاں کاٹتا ہوں جہاں میں نے نہیں بویا، اور جہاں میں نے نہیں بولا وہاں جمع کرو: \n27۔ اس لیے تمہیں چاہیے تھا کہ میرا پیسہ تبادلے والوں کو دے دیتا، اور {پھر} جب میں آتا تو میں اپنی رقم سود کے ساتھ وصول کرتا۔ \n28۔ لہٰذا اس سے صلاحیت لے لو، اور اسے اس کو دے دو جس کے پاس دس صلاحیتیں ہیں۔ \n29۔ کیونکہ ہر اس شخص کو دیا جائے گا جسے دیا جائے گا، اور اسے فراوانی ملے گی، لیکن جس کے پاس نہیں ہے، اس سے وہ بھی لیا جائے گا جو اس کے پاس ہے۔ \n30۔ اور بے فائدہ خادم کو باہر کے تاریکی میں پھینک دو: وہاں رونا اور دانت پیسنا ہوگا۔ \n31۔ جب انسان کا بیٹا اپنی شان میں آئے گا، اور اس کے ساتھ تمام مقدس فرشتے آئیں گے، تو وہ اپنی عظمت کے تخت پر بیٹھے گا: \n32۔ اور اس کے سامنے تمام قومیں جمع ہوں گی: اور وہ انہیں ایک دوسرے سے جدا کرے گا، جیسے چرواہا اپنی بھیڑوں کو بکریوں سے جدا کرتا ہے: \n33۔ اور وہ بھیڑوں کو اپنے دائیں ہاتھ پر رکھے، لیکن بکریوں کو بائیں ہاتھ پر۔ \n34۔ پھر بادشاہ اپنے دائیں ہاتھ پر ان سے کہے گا، آؤ، اے میرے باپ کے بابرکت لوگو، اس بادشاہی کے وارث بنو جو تمہارے لیے دنیا کی بنیاد سے تیار کی گئی ہے: \n35۔ کیونکہ میں بھوکا تھا، اور تم نے مجھے گوشت دیا: میں پیاسا تھا، اور تم نے مجھے پانی دیا: میں اجنبی تھا، اور تم نے مجھے قبول کیا: \n36۔ ننگے اور تم نے مجھے کپڑے پہنائے: میں بیمار تھا، اور تم مجھ سے ملنے آئے: میں قید میں تھا، اور تم میرے پاس آئے۔ \n37۔ پھر راستباز اس کا جواب دیں گے، کہے گا، اے خداوند، جب ہم نے تمہیں بھوکا اور کھانا دیکھا؟ یا پیاسا اور تمہیں پانی دیا؟ \n38۔ جب ہم نے تمہیں اجنبی دیکھا، اور تمہیں اپنے اندر لے آیا؟ یا ننگے اور کپڑے پہنے ہوئے {تم}؟ \n39۔ یا جب ہم نے تمہیں بیمار یا قید میں دیکھا اور تمہارے پاس آئے؟ \n40۔ اور بادشاہ جواب دے گا اور کہے گا، \"یقینا میں تم سے کہتا ہوں، جتنا تم نے میرے سب سے چھوٹے بھائیوں میں سے ایک کے ساتھ کیا ہے، تم نے میرے ساتھ کیا ہے۔ \n41۔ پھر وہ ان سے بائیں طرف بھی کہے گا، مجھ سے دور ہو جاؤ، اے لعنت زدہ ہو، ہمیشہ کی آگ میں، جو شیطان اور اس کے فرشتوں کے لیے تیار ہے: \n42۔ کیونکہ میں بھوکا تھا، اور تم نے مجھے گوشت نہیں دیا: میں پیاسا تھا، اور تم نے مجھے پانی نہیں دیا: \n43۔ میں اجنبی تھا، اور تم نے مجھے ننگا نہیں اپنایا، اور مجھے کپڑے نہیں پہنے: بیمار اور قید میں، اور تم نے مجھے نہیں دیکھا۔ \n44۔ تو کیا وہ اس کا جواب بھی دیں گے، کہیں، اے خداوند، جب ہم نے تمہیں بھوکا، پیاسا، یا اجنبی، ننگا، بیمار یا قید میں دیکھا اور تیری خدمت نہ کی؟ \n45۔ پھر وہ ان کا جواب دے گا، کہے، \"یقینا میں تم سے کہتا ہوں، جتنا تم نے ان میں سے کسی ایک کے ساتھ نہیں کیا، تم نے میرے ساتھ نہیں کیا۔ \n46۔ اور یہ ہمیشہ کی سزا میں جائیں گے، لیکن راستباز ہمیشہ کی زندگی میں جائیں گے۔","1۔ اور جب یسوع نے یہ تمام اقوال مکمل کیے، تو اس نے اپنے شاگردوں سے کہا، \n2۔ تم جانتے ہو کہ دو دن بعد عید فصح ہے، اور انسان کے بیٹے کو دھوکہ دیا جاتا ہے کہ اسے مصلوب کیا جائے۔ \n3۔ پھر اس نے سردار کاہنوں، کاتبوں اور لوگوں کے بزرگوں کو جمع کیا، جو سردار کاہن کے محل میں تھا، جسے کیافا کہا جاتا تھا، \n4۔ اور مشورہ کیا کہ وہ یسوع کو چالاکی سے لے کر اسے قتل کر سکتے ہیں۔ \n5۔ لیکن انہوں نے کہا، عید پر نہیں، تاکہ لوگوں میں ہنگامہ نہ ہو جائے۔ \n6۔ اب جب یسوع بیت عنیا میں تھا، شمعون کوڑھی کے گھر میں، \n7۔ اس کے پاس ایک عورت آئی جس کے پاس بہت قیمتی مرہم کا ایک الاباسٹر ڈبہ تھا، اور اس نے اسے اس کے سر پر ڈال دیا، جب وہ گوشت پر بیٹھا تھا۔ \n8۔ لیکن جب اس کے شاگردوں نے یہ دیکھا تو وہ غصے میں آ گئے اور کہا، یہ ضیاع کس مقصد کے لیے ہے؟ \n9۔ کیونکہ یہ مرہم بہت زیادہ قیمت پر بیچا جا سکتا تھا، اور غریبوں کو دیا جا سکتا تھا۔ \n10۔ جب یسوع نے سمجھا، تو اس نے ان سے کہا، تم عورت کو کیوں پریشان کرتے ہو؟ کیونکہ اس نے میرے ساتھ اچھا کام کیا ہے۔ \n11۔ کیونکہ غریب ہمیشہ تمہارے ساتھ ہیں؛ لیکن میں ہمیشہ نہیں رہے۔ \n12۔ کیونکہ اس نے یہ مرہم میرے جسم پر ڈال دیا ہے، اس نے یہ میری تدفین کے لیے کیا۔ \n13۔ یقینا میں تم سے کہتا ہوں، جہاں بھی یہ انجیل پوری دنیا میں پڑھی جائے، {وہاں} یہ بھی اس عورت کی یاد میں سنایا جائے گا۔ \n14۔ پھر بارہ میں سے ایک، جسے یہودا اسکریوتی کہا جاتا تھا، سردار کاہنوں کے پاس گیا، \n15۔ اور انہوں نے کہا {ان سے}، تم مجھے کیا دو گے، اور میں اسے تمہیں دے دوں گا؟ اور انہوں نے اس سے تیس چاندی کے سکے کا وعدہ کیا۔ \n16۔ اور اس وقت سے اس نے اسے دھوکہ دینے کا موقع تلاش کیا۔ \n17۔ اب بغیر خمیر کی روٹی کے پہلے دن شاگردوں نے یسوع کے پاس آ کر کہا، تم کہاں تیار کرو گے کہ ہم تمہارے لیے فسح کھاؤ؟ \n18۔ اور اس نے کہا، ایسے آدمی کے پاس شہر جاؤ اور اس سے کہو، مالک کہتا ہے، میرا وقت قریب ہے؛ میں اپنے شاگردوں کے ساتھ تمہارے گھر میں عید فسح مناؤں گا۔ \n19۔ اور شاگردوں نے وہی کیا جو یسوع نے انہیں مقرر کیا تھا؛ اور انہوں نے فسح کی تیاری کی۔ \n20۔ اب جب وقت برابر آیا، وہ بارہ کے ساتھ بیٹھ گیا۔ \n21۔ اور جب وہ کھا رہے تھے، اس نے کہا، \"یقینا میں تم سے کہتا ہوں کہ تم میں سے کوئی مجھے دھوکہ دے گا۔ \n22۔ اور وہ بہت غمگین تھے، اور ہر ایک نے اس سے کہا، اے خداوند، کیا میں ہوں؟ \n23۔ اور اس نے جواب دیا اور کہا، جو اپنے ہاتھ کو میرے ساتھ برتن میں ڈالے گا، وہی مجھے دھوکہ دے گا۔ \n24۔ انسان کا بیٹا ویسا ہی ہے جیسا اس کے بارے میں لکھا گیا ہے: لیکن اس آدمی پر افسوس جس کے ہاتھوں انسان کا بیٹا دھوکہ کھاتا ہے! اگر وہ پیدا نہ ہوتا تو اس کے لیے اچھا ہوتا۔ \n25۔ پھر یہودا، جس نے اسے دھوکہ دیا، جواب دیا اور کہا، استاد، کیا میں ہوں؟ اس نے اسے کہا، تو نے کہا ہے۔ \n26۔ اور جب وہ کھا رہے تھے، یسوع نے روٹی لی، اور اسے برکت دی، اور اسے توڑا، اور شاگردوں کو دے دیا، اور کہا، لو، کھاؤ؛ یہ میرا جسم ہے۔ {مبارک ہو: بہت سے یونانی نسخوں نے شکر ادا کیا ہے}\n27۔ اور اس نے پیالہ لیا، شکر ادا کیا، اور انہیں دے دیا، کہا، \"سب پی لو؛ \n28۔ کیونکہ یہ میرا خون ہے نئے عہد نامے کا، جو بہت سے لوگوں کے لیے گناہوں کی معافی کے لیے بہایا جاتا ہے۔ \n29۔ لیکن میں تم سے کہتا ہوں، میں اب سے اس انگور کے پھل سے نہیں پیوں گا، جب تک کہ وہ دن نہ جب میں اسے تمہارے ساتھ اپنے باپ کی بادشاہی میں نیا نہ پیوں۔ \n30۔ اور جب انہوں نے کوئی حمد گایا، تو وہ زیتون کے پہاڑ میں چلے گئے۔ {حمد: یا، زبور}\n31۔ پھر یسوع نے ان سے کہا، آج رات میری وجہ سے تم سب ناراض ہو جاؤ گے: کیونکہ لکھا ہے کہ میں چرواہے کو ماروں گا، اور ریوڑ کی بھیڑیں بکھر جائیں گی۔ \n32. لیکن جب میں دوبارہ زندہ ہو جاؤں گا، تو میں تمہارے سامنے گلیل میں جاؤں گا۔ \n33۔ پطرس نے جواب دیا اور کہا، اگرچہ تمام {لوگ} تیری وجہ سے ناراض ہوں گے، {لیکن} میں کبھی ناراض نہیں ہوں گا۔ {ناراض: یا اگر دوسروں کا ایمان ہل جائے اور ٹوٹ جائے، میرا ایمان مضبوط اور مستقل رہے گا}\n34۔ یسوع نے اس سے کہا، \"واقعی میں تم سے کہتا ہوں، کہ آج رات، مرغے کے بانگ کے سامنے، تم مجھے تین بار انکار کرو گے۔ \n35۔ پطرس نے اس سے کہا، اگرچہ میں تمہارے ساتھ مر جاؤں، پھر بھی تمہیں انکار نہیں کروں گا۔ اسی طرح تمام شاگردوں نے بھی کہا۔ \n36۔ پھر یسوع ان کے ساتھ ایک جگہ آتا ہے جسے گتسمانی کہتے ہیں، اور شاگردوں سے کہتا ہے، یہاں بیٹھو، جب میں وہاں جا کر دعا کرتا ہوں۔ \n37۔ اور اس نے اپنے ساتھ پطرس اور زبیدی کے دو بیٹوں کو لے گیا، اور غمگین اور بہت بوجھل ہو گیا۔ \n38۔ اور وہ تھوڑا آگے گیا، چہرے کے بل گر گیا، اور دعا کی، اے میرے باپ، اگر ممکن ہو تو یہ پیالہ مجھ سے ہٹا دو، لیکن جیسا میں چاہوں نہیں، بلکہ جیسا کہ تم چاہو۔ \n39۔ اور وہ شاگردوں کے پاس آتا ہے، انہیں سوتے ہوئے پاتا ہے، اور پطرس سے کہتا ہے، کیا تم میرے ساتھ ایک گھنٹہ نہیں دیکھ سکتے؟ \n40۔ دیکھو اور دعا کرو، کہ تم آزمائش میں نہ پڑو: روح واقعی {رضامند} ہے، لیکن جسم {کمزور} ہے۔ \n41۔ وہ دوسری بار چلا گیا، اور دعا کی، کہا، اے میرے باپ، اگر یہ پیالہ مجھ سے نہ نکل جائے، جب تک میں اسے نہ پیوں، تو تیری مرضی پوری ہو۔ \n42۔ اور وہ آیا اور انہیں دوبارہ سوتے ہوئے پایا: کیونکہ ان کی آنکھیں بھاری تھیں۔ \n43۔ اور وہ انہیں چھوڑ کر چلا گیا، اور تیسری بار دعا کی، وہی الفاظ کہے۔ \n44۔ پھر وہ اپنے شاگردوں کے پاس آتا ہے، اور ان سے کہتا ہے، اب سو جاؤ، اور آرام کرو: دیکھو، وقت قریب ہے، اور انسان کا بیٹا گناہ گاروں کے ہاتھوں میں دھوکہ دے دیا گیا ہے۔ \n45۔ اٹھو، چلو چلیں: دیکھو، وہ قریب ہے جو مجھے دھوکہ دیتا ہے۔ \n46۔ اور جب وہ ابھی بول رہا تھا، دیکھو، بارہ میں سے ایک، یہودا، آیا، اور اس کے ساتھ ایک بڑی فوج تلواروں اور لاٹھیوں کے ساتھ، قوم کے سردار کاہنوں اور بزرگوں کی طرف سے۔ \n47۔ اب جس نے اسے دھوکہ دیا تھا، اسے ایک اشارہ دیا کہ جسے میں چوموں گا، وہی ہے: اسے مضبوطی سے پکڑو۔ \n48۔ اور فورا وہ یسوع کے پاس آیا اور کہا، سلام، مالک؛ اور اسے بوسہ دیا۔ \n49۔ اور یسوع نے اس سے کہا، دوست، تم کیوں آئے ہو؟ پھر وہ آئے، اور یسوع پر ہاتھ رکھا اور اسے لے لیا۔ \n50۔ اور دیکھو، ان میں سے ایک جو یسوع کے ساتھ تھا، نے اپنا ہاتھ بڑھایا، تلوار نکالی، اور اعلیٰ کاہن کے خادم کو مارا اور اس کا کان کاٹ دیا۔ \n51۔ پھر یسوع نے اس سے کہا، اپنی تلوار دوبارہ اس کی جگہ رکھ دو، کیونکہ جو بھی تلوار اٹھائے گا وہ تلوار کے ساتھ فنا ہو جائے گا۔ \n52۔ کیا تم سمجھتے ہو کہ میں اب اپنے باپ سے دعا نہیں کر سکتا، اور وہ مجھے جلد ہی بارہ سے زیادہ فرشتوں کے لشکر دے گا؟ \n53۔ لیکن پھر صحیفے کیسے پورے ہوں گے، جو اس طرح ہونا ضروری ہے؟ \n54۔ اسی وقت یسوع نے ہجوم سے کہا، کیا تم چور کے خلاف تلواریں اور لاٹھیاں لے کر نکلے ہو تاکہ مجھے لے جاؤ؟ میں روزانہ تمہارے ساتھ مندر میں تعلیم دیتا رہا، اور تم نے مجھے پکڑ نہیں لیا۔ \n55۔ لیکن یہ سب اس لیے کیا گیا کہ انبیاء کی کتابیں پوری ہوں۔ پھر تمام شاگرد اسے چھوڑ کر بھاگ گئے۔ \n56۔ اور جنہوں نے یسوع کو پکڑ لیا تھا، وہ [اسے} کو کائفاس سردار کاہن کے پاس لے گئے، جہاں کاتب اور بزرگ جمع تھے۔ \n57۔ لیکن پیٹر اس کے پیچھے دور تک بڑے پادری کے محل تک گیا، اندر گیا اور نوکروں کے ساتھ بیٹھ کر انجام دیکھنے لگا۔ \n58۔ اب سردار کاہن، بزرگ، اور تمام کونسل نے یسوع کے خلاف جھوٹی گواہی مانگی، تاکہ اسے قتل کیا جا سکے؛ \n59۔ لیکن کوئی نہ ملا: ہاں، اگرچہ بہت سے جھوٹے گواہ آئے، {پھر بھی} انہوں نے کوئی نہیں پایا۔ آخر میں دو جھوٹے گواہ آئے، \n60۔ اور کہا، اس {آدمی} نے کہا، میں خدا کے مندر کو تباہ کر سکتا ہوں، اور اسے تین دن میں تعمیر کر سکتا ہوں۔ \n61۔ اور اعلیٰ پادری اٹھا اور اس سے کہا، کیا تم کچھ جواب نہیں دیتے؟ یہ کیا گواہ ہیں جو تمہارے خلاف ہیں؟ \n62۔ لیکن یسوع خاموش رہا۔ اور اعلیٰ کاہن نے جواب دیا اور کہا، میں زندہ خدا کی قسم دیتا ہوں کہ تم ہمیں بتاؤ کہ کیا تم مسیح ہو، خدا کا بیٹا۔ \n63۔ یسوع نے اسے کہا، تو نے کہا: پھر بھی میں تم سے کہتا ہوں، آخرت میں تم انسان کے بیٹے کو طاقت کے دائیں ہاتھ پر بیٹھا اور آسمان کے بادلوں میں آتے دیکھو گے۔ \n64۔ پھر اعلیٰ پادری نے اس کے کپڑے پھاڑ دیے اور کہا، اس نے کفر کہا ہے؛ ہمیں گواہوں کی اور کیا ضرورت ہے؟ دیکھو، اب تم نے اس کی توہین سن لی ہے۔ \n65۔ تم کیا سوچتے ہو؟ انہوں نے جواب دیا اور کہا، وہ موت کا مجرم ہے۔ \n66۔ پھر انہوں نے اس کے چہرے پر تھوکا، اور اسے مارا؛ اور دوسروں نے {اسے} کو اپنے ہاتھوں کی ہتھیلیوں سے مارا، {ہتھیلیاں...: یا چھڑیاں}\n67۔ کہتا ہے، اے مسیح ہمیں پیش گوئی کرو، وہ کون ہے جس نے تمہیں مارا؟ \n68۔ اب پطرس محل میں بغیر بیٹھا تھا: اور ایک دوشیزہ اس کے پاس آئی اور کہا، \"تو بھی گلیل کے یسوع کے ساتھ ہو۔ \n69۔ لیکن اس نے سب کے سامنے انکار کیا، کہہ دیا، میں نہیں جانتا کہ تم کیا کہہ رہے ہو۔ \n70۔ اور جب وہ برآمدے میں چلا گیا، ایک اور لڑکی نے اسے دیکھا اور وہاں موجود لوگوں سے کہا، یہ {آدمی} بھی یسوع ناصرت کے ساتھ تھا۔ \n71۔ اور پھر اس نے قسم کھا کر انکار کیا، میں اس آدمی کو نہیں جانتا۔ \n72۔ اور کچھ دیر بعد وہ لوگ آئے جو کھڑے تھے، اور پطرس سے کہا، یقینا تم بھی ان میں سے ایک ہو؛ کیونکہ تمہاری گفتگو تمہیں متاثر کرتی ہے۔ \n73۔ پھر اس نے گالیاں دینا شروع کیں اور قسم کھائی، {کہا}، میں اس آدمی کو نہیں جانتا۔ اور فورا مرغ کا عملہ۔ \n74۔ اور پطرس کو یسوع کا کلام یاد آیا، جس میں کہا گیا تھا، مرغے کے سامنے تین بار انکار کرو۔ اور وہ باہر گیا، اور بری طرح رویا۔","1۔ جب صبح ہوئی، تو قوم کے تمام سردار پادریوں اور بزرگوں نے یسوع کے خلاف مشورہ کیا کہ اسے قتل کر دیں: \n2۔ اور جب انہوں نے اسے باندھ دیا، تو اسے لے گئے اور گورنر پونٹیئس پیلاطس کے حوالے کر دیا۔ \n3۔ پھر یہودا، جس نے اسے دھوکہ دیا تھا، جب اس نے دیکھا کہ وہ سزا یافتہ ہے، تو توبہ کی اور تیس چاندی کے سکے سردار کاہنوں اور بزرگوں کے پاس لے آیا، \n4۔ کہتے ہوئے، میں نے گناہ کیا ہے کہ میں نے معصوم خون سے غداری کی ہے۔ اور انہوں نے کہا، یہ ہمارے لیے کیا ہے؟ دیکھو {اس کے لیے}۔ \n5۔ اور اس نے مندر میں چاندی کے ٹکڑے پھینک دیے، اور چلا گیا، اور جا کر خودکشی کر لی۔ \n6۔ اور سردار کاهنوں نے چاندی کے ٹکڑے لے کر کہا، انہیں خزانے میں رکھنا جائز نہیں کیونکہ یہ خون کی قیمت ہے۔ \n7۔ اور انہوں نے مشورہ لیا، اور اپنے ساتھ مٹی کے مٹی کے کھیت کو خریدا، تاکہ اجنبیوں کو دفن کیا جا سکے۔ \n8۔ اسی لیے اس میدان کو آج تک خون کا میدان کہا جاتا ہے۔ \n9۔ پھر وہ پورا ہوا جو یرمی نبی نے کہا تھا، اور انہوں نے تیس چاندی کے ٹکڑے لیے، اس کی قیمت جس کی قدر کی گئی، جسے بنی اسرائیل نے قیمتی سمجھا؛ {کون...: یا، جنہیں انہوں نے بنی اسرائیل سے خریدا}\n10۔ اور انہیں مٹی کے کھیت کے لیے دیا، جیسا کہ خداوند نے مجھے مقرر کیا۔ \n11۔ اور یسوع گورنر کے سامنے کھڑا تھا: اور گورنر نے اس سے پوچھا، کہا، کیا تم یہودیوں کا بادشاہ ہو؟ اور یسوع نے اسے کہا، تو کہتا ہے۔ \n12۔ اور جب اس پر سردار پادریوں اور بزرگوں کا الزام لگا، تو اس نے کچھ جواب نہ دیا۔ \n13۔ پھر پیلاطس نے اس سے کہا، کیا تم نہیں سنے کہ وہ تمہارے خلاف کتنی باتیں گواہی دیتے ہیں؟ \n14۔ اور اس نے کبھی جواب نہیں دیا؛ اتنا کہ گورنر حیران ہوا۔ \n15۔ اس دعوت میں گورنر لوگوں کے لیے ایک قیدی کو آزاد کرتا تھا، جسے وہ چاہتے تھے۔ \n16۔ اور اس وقت ان کے پاس ایک نمایاں قیدی تھا، جسے باراباس کہا جاتا تھا۔ \n17۔ لہٰذا جب وہ سب اکٹھے ہوئے، پیلاطس نے ان سے کہا، تم کس کو چھوڑو گے جو میں تمہیں دے دوں؟ باراباس، یا یسوع جسے مسیح کہا جاتا ہے؟ \n18۔ کیونکہ وہ جانتا تھا کہ حسد کی وجہ سے انہوں نے اسے نجات دی ہے۔ \n19۔ جب اسے عدالت کی نشست پر اتارا گیا، اس کی بیوی نے اسے بھیجا اور کہا، \"اس عادل آدمی سے کوئی واسطہ نہ رکھو، کیونکہ میں نے آج خواب میں اس کی وجہ سے بہت کچھ برداشت کیا ہے۔ \n20۔ لیکن سردار پادریوں اور بزرگوں نے ہجوم کو قائل کیا کہ وہ باراباس سے دعا کریں اور یسوع کو تباہ کریں۔ \n21۔ گورنر نے جواب دیا اور ان سے کہا، کیا تم دونوں میں سے چاہو گے کہ میں تمہیں آزاد کر دوں؟ انہوں نے کہا، باراباس۔ \n22۔ پیلاطس ان سے کہتا ہے، تو پھر میں یسوع کے ساتھ کیا کروں جسے مسیح کہا جاتا ہے؟ {وہ سب اس سے کہتے ہیں، اسے مصلوب کیا جائے۔ \n23۔ اور گورنر نے کہا، کیوں، اس نے کیا برا کیا ہے؟ لیکن انہوں نے اور زیادہ پکارا، کہنے لگے، اسے مصلوب کیا جائے۔ \n24۔ جب پیلاطس نے دیکھا کہ وہ کچھ نہیں کر سکتا، بلکہ ایک ہنگامہ برپا ہوا ہے، تو اس نے پانی لیا اور ہجوم کے سامنے اپنے ہاتھ دھوئے، کہنے لگا، میں اس نیک شخص کے خون سے بے گناہ ہوں: دیکھو۔ \n25۔ پھر سب لوگوں نے جواب دیا اور کہا، اس کا خون ہم پر اور ہمارے بچوں پر ہو۔ \n26۔ پھر اس نے باراباس کو ان کے حوالے کیا: اور جب اس نے یسوع کو کوڑے مارے، تو اسے مصلوب ہونے کے لیے پہنچایا۔ \n27۔ پھر گورنر کے سپاہیوں نے یسوع کو مشترکہ ہال میں لے جایا، اور پورا گروہ {سپاہیوں کا} کو اپنے پاس جمع کیا۔ {کامن ہال: یا، گورنر کا گھر}\n28۔ اور انہوں نے اسے کپڑے اتار کر سرخ لباس پہنایا۔ \n29۔ اور جب انہوں نے کانٹوں کا تاج لگایا، تو اس کے سر پر رکھ دیا، اور دائیں ہاتھ میں ایک سرکنڈہ رکھا، اور اس کے سامنے گھٹنے ٹیک کر اس کا مذاق اڑایا، کہا، سلام، یہودیوں کے بادشاہ! \n30۔ اور انہوں نے اس پر تھوکا، اور سرکنڈے کو لے کر اس کے سر پر مارا۔ \n31۔ اور اس کے بعد انہوں نے اس کا مذاق اڑایا، اس کا لباس اتار دیا، اور اسے صلیب پر چڑھانے لے گئے۔ \n32۔ اور جب وہ باہر نکلے تو انہوں نے سائرین کے ایک آدمی کو پایا، جس کا نام شمعون تھا: جسے انہوں نے اپنی صلیب اٹھانے پر مجبور کیا۔ \n33۔ اور جب وہ ایک جگہ پہنچے جسے گولگوتھا کہا جاتا ہے، یعنی کھوپڑی کی جگہ، \n34۔ انہوں نے اسے پینے کے لیے سرکہ دیا جو گال کے ساتھ ملا ہوا تھا: اور جب اس نے اس کا ذائقہ چکھا تو وہ نہیں پیتا۔ \n35۔ اور انہوں نے اسے مصلوب کر دیا، اور اس کے کپڑے پھاڑ دیے، قرعہ ڈالا تاکہ نبی کی بات پوری ہو، انہوں نے میرے کپڑے ان میں تقسیم کیے، اور میرے لباس پر قرعہ ڈالے۔ \n36۔ اور بیٹھ کر وہ اسے وہاں دیکھتے رہے؛ \n37۔ اور اس کے سر پر اس کا الزام لکھا ہے، یہ یسوع ہے یہودیوں کا بادشاہ۔ \n38۔ پھر اس کے ساتھ دو چور صلیب پر چڑھائے گئے، ایک دائیں ہاتھ پر اور دوسرا بائیں طرف۔ \n39۔ اور جو گزرے وہ اسے برا بھلا کہتے تھے، سر ہلاتے ہوئے، \n40۔ اور کہو، تو جو مندر کو تباہ کرتا ہے اور تین دن میں تعمیر کرتا ہے، خود کو بچا۔ اگر تم خدا کے بیٹے ہو، تو صلیب سے نیچے آؤ۔ \n41۔ اسی طرح سردار کاہنوں نے بھی اس کا مذاق اڑاتے ہوئے، کاتبوں اور بزرگوں کے ساتھ کہا، \n42۔ اس نے دوسروں کو بچایا؛ خود کو وہ نہیں بچا سکتا۔ اگر وہ اسرائیل کا بادشاہ ہے، تو اب وہ صلیب سے نیچے آئے، اور ہم اس پر یقین کریں گے۔ \n43۔ اس نے خدا پر بھروسہ کیا؛ اگر وہ چاہے تو اب اسے نجات دے: کیونکہ اس نے کہا، میں خدا کا بیٹا ہوں۔ \n44۔ وہ چور بھی جو اس کے ساتھ صلیب پر چڑھائے گئے تھے، اس کے دانتوں میں وہی پھینک دیتے تھے۔ \n45۔ اب چھٹے گھنٹے سے نویں گھنٹے تک پورے ملک پر اندھیرا چھا گیا۔ \n46۔ اور تقریبا نویں گھنٹے میں یسوع نے زور سے پکارا، کہا، ایلی، ایلی، لاما سبچتھانی؟ یعنی، میرے خدا، میرے خدا، تو نے مجھے کیوں چھوڑ دیا؟ \n47۔ ان میں سے کچھ جو وہاں کھڑے تھے، جب انہوں نے یہ سنا، کہا، یہ {آدمی} ایلیاس کو پکار رہا ہے۔ \n48۔ اور فورا ان میں سے ایک نے دوڑا، ایک گھونٹ لیا، سرکہ بھرا، اور اسے سرکنڈے پر رکھا، اور اسے پانی دیا۔ \n49۔ باقی نے کہا، چلو دیکھتے ہیں کہ ایلیاس اسے بچانے آتا ہے یا نہیں۔ \n50۔ یسوع نے جب دوبارہ بلند آواز میں رویا تو بھوت کو حوالے کر دیا۔ \n51۔ اور دیکھو، مندر کا پردہ اوپر سے نیچے تک دو حصوں میں پھٹ گیا؛ اور زمین لرز گئی، اور چٹانیں پھٹ گئیں؛ \n52۔ اور قبریں کھول دی گئیں؛ اور بہت سے مقدسین کے جسم جو سوتے تھے اٹھے، \n53۔ اور اپنی قیامت کے بعد قبروں سے باہر آیا، مقدس شہر میں گیا، اور بہت سے لوگوں کے سامنے ظاہر ہوا۔ \n54۔ اب جب سینچورین اور اس کے ساتھ جو لوگ یسوع کو دیکھ رہے تھے، زلزلے اور وہ سب کچھ دیکھا جو ہوئے، تو وہ بہت خوفزدہ ہوئے اور کہا، واقعی یہ خدا کا بیٹا ہے۔ \n55۔ اور وہاں بہت سی عورتیں دور کہیں دیکھ رہی تھیں، جو یسوع کے پیچھے گلیل سے آئے اور اس کی خدمت کر رہے تھے: \n56۔ جن میں مریم مگدلین اور مریم (جیمز اور جوزس کی والدہ) اور زبدی کے بچوں کی ماں شامل تھیں۔ \n57۔ جب ایون آیا، تو اریماتیہ کا ایک امیر آدمی آیا، جس کا نام یوسف تھا، جو خود بھی یسوع کا شاگرد تھا: \n58۔ وہ پیلاطس کے پاس گیا، اور یسوع کے جسم کی بھیک مانگی۔ پھر پیلاطس نے حکم دیا کہ جسم کو آزاد کیا جائے۔ \n59۔ اور جب یوسف نے لاش لی، تو اسے صاف کپڑے میں لپیٹ دیا، \n60۔ اور اسے اپنی نئی قبر میں رکھ دیا، جو اس نے چٹان میں تراشا تھا: اور ایک بڑا پتھر قبر کے دروازے تک لپیٹا اور روانہ ہو گیا۔ \n61۔ اور وہاں مریم مگدلین اور دوسری مریم قبر کے ساتھ بیٹھی تھیں۔ \n62۔ اگلے دن، جو تیاری کے دن کے بعد آیا، سردار کاہن اور فریسی مل کر پیلاطس کے پاس آئے، \n63۔ جناب، ہمیں یاد ہے کہ اس دھوکے باز نے کہا تھا، جب وہ زندہ تھا، تین دن بعد میں دوبارہ اٹھوں گا۔ \n64۔ لہٰذا حکم دو کہ قبر تیسرے دن تک محفوظ رہے، ورنہ اس کے شاگرد رات کو آئیں گے اور اسے لے جائیں گے، اور لوگوں سے کہیں گے، وہ مردوں میں سے زندہ ہوا ہے: اس لیے آخری غلطی پہلی سے بھی بدتر ہوگی۔ \n65۔ پیلاطس نے ان سے کہا، تم ایک گھڑی رکھو: اپنی راہ جاؤ، جتنا ہو سکے اسے یقینی بناؤ۔ \n66۔ تو وہ گئے، اور قبر کو یقینی بنایا، پتھر کو مہر بند کیا اور پہرہ لگایا۔","1۔ سبت کے آخر میں، جب ہفتے کے پہلے {دن} کی طرف طلوع ہونے لگا، مریم مگدلین اور دوسری مریم قبر دیکھنے آئیں۔ \n2۔ اور دیکھو، ایک عظیم زلزلہ آیا: کیونکہ خداوند کا فرشتہ آسمان سے نیچے آیا، اور دروازے سے پتھر ہٹا کر اس پر بیٹھ گیا۔ {تھا: یا، تھا}\n3۔ اس کا چہرہ بجلی کی طرح تھا، اور اس کا لباس برف کی طرح سفید: \n4۔ اور اس کے خوف سے محافظ کانپ گئے، اور مردہ انسان بن گئے۔ \n5۔ اور فرشتے نے جواب دیا اور عورتوں سے کہا، \"ڈرو مت، کیونکہ میں جانتا ہوں کہ تم یسوع کی تلاش میں ہو، جو صلیب پر چڑھایا گیا تھا۔ \n6۔ وہ یہاں نہیں ہے: کیونکہ وہ زندہ ہو گیا ہے، جیسا کہ اس نے کہا۔ آؤ، وہ جگہ دیکھو جہاں خداوند تھا۔ \n7۔ اور جلدی جاؤ، اور اپنے شاگردوں کو بتاؤ کہ وہ مردوں میں سے زندہ ہو گیا ہے؛ اور دیکھو، وہ تمہارے سامنے گلیل میں آتا ہے؛ وہاں تم اسے دیکھو گے: دیکھو، میں نے تمہیں بتایا ہے۔ \n8۔ اور وہ خوف اور خوشی کے ساتھ قبر سے جلدی روانہ ہوئے؛ اور اپنے شاگردوں کو پیغام دینے کے لیے دوڑے۔ \n9۔ اور جب وہ اس کے شاگردوں کو بتانے گئے، دیکھو، یسوع نے ان سے ملاقات کی اور کہا، سلام علیے۔ اور وہ آئے اور اسے پاؤں سے پکڑ کر عبادت کی۔ \n10۔ پھر یسوع نے ان سے کہا، ڈرو مت: جا کر میرے بھائیوں کو بتاؤ کہ وہ گلیل میں جائیں گے، اور وہاں وہ مجھے دیکھیں گے۔ \n11۔ جب وہ جا رہے تھے، دیکھو، کچھ پہرے دار شہر میں آئے اور سردار کاهنوں کو وہ سب کچھ دکھایا جو کیے گئے تھے۔ \n12۔ اور جب وہ بزرگوں کے ساتھ جمع ہوئے اور مشورہ کیا، تو انہوں نے سپاہیوں کو بڑی رقم دی، \n13۔ کہتے ہوئے، کہو، اس کے شاگرد رات کو آئے اور جب ہم سو رہے تھے تو اسے لے گئے۔ \n14۔ اور اگر یہ گورنر کے کانوں تک پہنچا تو ہم اسے قائل کریں گے، اور تمہیں محفوظ رکھیں گے۔ \n15۔ تو انہوں نے پیسے لے لیے، اور جیسا انہیں سکھایا گیا تھا ویسا ہی کیا: اور یہ کہاوت آج تک یہودیوں میں عام طور پر سنائی جاتی ہے۔ \n16۔ پھر گیارہ شاگرد گلیل چلے گئے، اس پہاڑ میں جہاں یسوع نے انہیں مقرر کیا تھا۔ \n17۔ اور جب انہوں نے اسے دیکھا تو اس کی عبادت کی: لیکن کچھ نے شک کیا۔ \n18۔ اور یسوع آئے اور ان سے کہا، \"تمام طاقت مجھے آسمان اور زمین میں دی گئی ہے۔ \n19۔ تو جاؤ، اور تمام قوموں کو تعلیم دو، انہیں باپ، بیٹے اور روح القدس کے نام پر بپتسمہ دو: {تعلیم دو...: یا، شاگرد بنو، یا تمام قوموں کے عیسائی بناؤ}\n20۔ انہیں سکھاتا ہوں کہ وہ سب کچھ جو میں نے تمہیں حکم دیا ہے اس پر عمل کریں: اور دیکھو، میں ہمیشہ تمہارے ساتھ ہوں، {حتیٰ کہ} دنیا کے آخر تک۔ آمین۔"];
